window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-pneumo-pne-2"]={"block":"medcurso:medcurso-pneumo-pne-2","label":"Medcurso · PNE 2","count":425,"questions":[{"id":"medcurso-pneumo-pne-2-345437","number":"345437","sourceNumber":"345437","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em relação ao diagnóstico da tuberculose pulmonar e o controle do seu tratamento, a\npesquisa bacteriológica assume um importante papel. Nesse contexto, assinale a alternativa\ncorreta:","options":{"A":"O teste rápido molecular para tuberculose pode ser utilizado para triagem de resistência à\nrifampicina.","B":"A baciloscopia de escarro não é indicada se não houver suspeita clínica, ainda que se tenha\nsuspeita radiológica.","C":"O teste rápido molecular para tuberculose pode ser útil para o diagnóstico em casos de\nretratamento.","D":"A baciloscopia de escarro pode ser realizada em duas amostras, desde que a primeira tenha um\nresultado positivo."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-343835","number":"343835","sourceNumber":"343835","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem, 61 anos, com quadro de febre alta há 4 dias, tosse e dor torácica ventilatório\ndependente. Ao exame físico, febril (Tax 39ºc), com olhos encovados, mucosas secas, frequência\nrespiratória de 31 incursões por minuto, SpO2- 94% em ar ambiente, PA de 80 x 50 mmHg e\nfrequência cardíaca de 100 bpm. Ausculta pulmonar com estertores crepitantes em base pulmonar\nesquerda e diminuição da expansibilidade torácica localizada. Qual a conduta mais adequada para\no caso?","options":{"A":"Ceftriaxone e azitromicina, hidratação venosa injetável e internação hospitalar.","B":"Levofloxacina e azitromicina, hidratação venosa injetável e internação hospitalar.","C":"Levofloxacina, hidratação oral e acompanhamento ambulatorial.","D":"Amoxicilina/ Ac. Clavulâmico e azitromicina , hidratação oral e acompanhamento ambulatorial."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-343840","number":"343840","sourceNumber":"343840","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem, 45 anos, com diagnóstico laboratorial confirmado de tuberculose (TB)\npulmonar inicia tratamento com o esquema básico\n(EB) para TB preconizado pelo Ministério da\nSaúde. Os exames laboratoriais no início do tratamento mostraram testes rápidos para HIV,\nhepatite B, hepatite C e sífilis não reagentes, função renal normal e transaminases normais. Um\nmês após o início do tratamento retorna ao atendimento médico devido mal-estar abdominal, está\nictérico ao exame físico. As transaminases estão aproximadamente dez vezes acima do limite\nsuperior de normalidade. Nesta situação, a conduta correta seria:","options":{"A":"Substituir o esquema básico pelo esquema específico para hepatopatas.","B":"Suspender o EB até melhora das transaminases e depois reintroduzir as mesmas drogas de\nforma gradual.","C":"Manter o esquema básico e associar um medicamento hepatoprotetor.","D":"Suspender o EB até melhora das transaminases e depois introduzir um esquema alternativo\npara hepatopatas."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-283276","number":"283276","sourceNumber":"283276","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em relação ao choque séptico refratário à volume assinale a alternativa correta quanto\nàs opções de sequência terapêutica progressiva\nde modo genérico após expansão volêmica sem\nresposta.","options":{"A":"Noradrenalina, vasopressina e hidrocortisona.","B":"Dopamina, dobutamina e vasopressina.","C":"Vasopressina, dobutamina e hidrocortisona.","D":"Noradrenalina, dopamina e hidrocortisona."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-291763","number":"291763","sourceNumber":"291763","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem, 45 anos de idade, morador de zona rural, procurou atendimento médico por\nqueixa de úlcera dolorosa em dorso do pé esquerdo há seis meses. No interrogatório sistemático,\nqueixou-se, também, de astenia e tosse seca. Tabagista de 25 anos/maço, sem outras\ncomorbidades. Ao exame físico, regular estado geral, afebril. Apresentava úlcera com 20 mm de\ndiâmetro, com bordas elevadas, eritematosas e fundo com pontilhado hemático. Realizada biópsia\nda lesão, evidenciou processo granulomatoso, com presença de células leveduriformes com\nbrotamento em roda de leme. Radiografia de tórax com infiltrado retículo-nodular difuso. Paciente\nperdeu seguimento e, três meses depois, voltou a procurar atendimento médico com quadro de\nhipotensão, apresentando exames laboratoriais com Na = 119 mEq/L; e K = 6,1mEq/L,\nnecessitando de internação hospitalar. Diante do caso, Identifique a hipótese diagnóstica principal\nno atendimento inicial.","options":{"A":"Paracoccidioidomicose.","B":"Leishmaniose.","C":"Esporotricose.","D":"Tuberculose."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-283280","number":"283280","sourceNumber":"283280","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente do sexo feminino, 32 anos, dá entrada no pronto atendimento com quadro\nagudo de febre, convulsões e rebaixamento do\nnível de consciência. Tomografia de crânio normal.\nO exame do líquor revelava 40 células, com 67% de linfócitos, 30% de monócitos e 3% de\nneutrófilos. Proteínas de 59 mg/dl, glicose de 65 mg/dl e lactato de 24 mg/dl. Baseado nestes\ndados, qual diagnóstico provável?","options":{"A":"Meningoencefalite por tuberculose.","B":"Meningoencefalite por herpes.","C":"Meningoencefalite por HIV.","D":"Meningoencefalite auto-imune."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-281101","number":"281101","sourceNumber":"281101","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em relação à tuberculose pleural, analise as seguintes afirmativas: I - Ocorre\ngeralmente entre três e seis anos após a infecção\nprimária; II - O exame físico do tórax mostra\nmacicez e aumento do frêmito toracovocal na área do derrame pleural; III - Ocorre por extensão\ndireta do foco caseoso pulmonar subpleural ou por disseminação hematogênica. Está ou estão\nCORRETA(S) a(s) afirmativa(s):","options":{"A":"I, II e III.","B":"II, apenas.","C":"I, apenas.","D":"III, apenas.","E":"I e II, apenas."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-283298","number":"283298","sourceNumber":"283298","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em virtude da dificuldade de isolamento do bacilo da tuberculose nas crianças\ninfectadas, o Ministério da Saúde recomenda\num score para o diagnóstico, o qual considera todos\nos itens abaixo, EXCETO:","options":{"A":"Estado nutricional.","B":"Contato com adulto tuberculoso.","C":"Teste tuberculínico.","D":"Baciloscopia."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-281154","number":"281154","sourceNumber":"281154","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Escolar de 6 (seis) anos de idade é trazida ao pronto atendimento com tosse\npersistente e febre do tipo intermitente\nquotidiano há duas semanas. Exame físico: fácies atípica,\nFR: 50 irpm, FC: 125bpm e murmúrio vesicular diminuído nos 2/3 inferiores do hemitórax esquerdo.\nRaio x de tórax: extenso derrame pleural. A toracocentese apresentou líquido amarelado e a\ncitologia diferencial demonstrou mais de 80% de linfócitos. O agente etiológico mais provável dessa\ncondição clínica é:","options":{"A":"Streptococcus pyogenes do grupo A.","B":"Streptococcus pneumoniae.","C":"Staphylococcus aureus.","D":"Mycoplama pneumoniae.","E":"Mycobacterium tuberculosis."},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-251872","number":"251872","sourceNumber":"251872","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Na pneumonia comunitária, para que serve o escore CURB-65?","options":{"A":"Para avaliar comorbidades.","B":"Para escolher classe de antibiótico.","C":"Para estabelecer mortalidade e local de tratamento do paciente.","D":"Para detectar potenciais doadores de órgãos."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-251875","number":"251875","sourceNumber":"251875","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Considere três pacientes com quadro de sepse e as seguintes hemoculturas: I.\nStaphylococcus aureus resistente a oxacilina.\nII. Escherichia coli produtora de ESBL. III.\nPseudomonas aeroginosa resistente a carbapenêmicos. Polimixina, meropenem e teicoplanina são\nindicados, respectivamente, para:","options":{"A":"III, II, I.","B":"I, II, III.","C":"I, III, II.","D":"Nenhuma das anteriores."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-251877","number":"251877","sourceNumber":"251877","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente de 33 anos é admitido com sinais de choque séptico de foco urinário por\nlitíase obstrutiva em rim direito. Sobre o tratamento a ser instituído, assinale a correta:","options":{"A":"A reposição volêmica deve ser feita com colóides.","B":"A antibioticoterapia idealmente deve ser guiada por cultura.","C":"O vasopressor ideal no momento é a dopamina.","D":"As variáveis hemodinâmicas são fundamentais para o sucesso do tratamento."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-247165","number":"247165","sourceNumber":"247165","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Quanto ao tratamento nas 6 primeiras horas de quadro de sepse grave, é CORRETO\nafirmar que:","options":{"A":"A reposição de voluma guiada pelos níveis de pressão venosa central (PVC) é indicada já que\nesta pressão permite a avaliação fidedigna do volume de enchimento do coração esquerdo.","B":"No paciente idoso com sepse grave, o volume só pode ser administrado após avaliação da\npressão venosa central (PVC).","C":"O tratamento agressivo nas primeiras 6 horas com aderência ao conjunto de medidas \"\"pacote\"\",\nreposição de volume a administração\nprecoce de antibióticos irá influir diretamente na\nmorbimortalidade.","D":"A administração de Ringer Lactato traz vantagens comprovadas ao paciente politraumatizado.","E":"A dopamina é o vasopressor de primeira escolha para o tratamento dos quadros de choque"},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-247177","number":"247177","sourceNumber":"247177","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Assinale a alternativa que completa CORRETAMENTE a frase abaixo. No derrame\npleural por tuberculose, habitualmente se encontra:","options":{"A":"Desidrogenase lática em valores acima de 1.000 U/L.","B":"Proteínas em valores baixos, podendo caracterizar transudato.","C":"Predomínio linfomonocitário na celularidade específica.","D":"Presença do Mycobacterium tuberculosis na maioria dos casos.","E":"Líquido pleural purulento."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-251909","number":"251909","sourceNumber":"251909","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em uma discussão de caso clínico com a equipe da Unidade Básica de Saúde do Rui\nLino, aborda-se algumas situações sobre a avaliação dos contatos domiciliares de pacientes TB\npulmonares com baciloscopia positiva. Sobre esse assunto, assinale a afirmativa INCORRETA.","options":{"A":"No adulto sintomático com exame de escarro positivo, a conduta inicial é a orientação. Caso o\nraio X seja sugestivo de TB, é indicado o tratamento.","B":"No adulto assintomático e no adulto sintomático com exame de escarro negativo, a conduta é a\norientação.","C":"Nas crianças de até 15 anos, não vacinadas, realiza-se a PPD. Caso seja reator a PPD,\n\nrealiza-se raio X de tórax. Caso o raio X seja sugestivo de TB e tenha sintomas clínicos, é indicado\ntratamento.","D":"Nas crianças de até 15 anos, vacinadas e sintomáticas, realiza-se raios-X de tórax. Com exame\nnormal e sem sintomas clínicos, realizam-se orientação e medicação sintomática e é feito\nacompanhamento."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-251914","number":"251914","sourceNumber":"251914","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em uma saúde itinerante em Feijó, a equipe multiprofissional discute sobre a\nquimioprofilaxia da TB, referente a alguns\ncasos atendidos. Sobre esse assunto, analise as\nalternativas abaixo: I. Nas grávidas, a quimioprofilaxia deve ser iniciada no terceiro trimestre da\ngestação. II. Nos índios, recomenda-se que todo contato de TB bacilífero, forte reator à PPD\n(>10mm), independentemente da idade e do estado vacinal, após avaliação clínica e afastada a\npossibilidade de TB doença por meio de baciloscopia e exame radiológico, receba terapia\npreventiva. III. Na quimioprofilaxia primária, administra-se isoniazida em pessoas não infectadas\npara prevenir a infecção. IV. Na quimioprofilaxia secundária, administra-se isoniazida em pessoas\njá infectadas pelo Mtb, mas sem sinais de doença, para prevenir a evolução da infecção à doença.\nConsiderando as alternativas a cima, assinale a afirmativa CORRETA.","options":{"A":"Apenas I e III.","B":"Apenas I e IV.","C":"Apenas II, III e IV.","D":"I, II, III e IV."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-247235","number":"247235","sourceNumber":"247235","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente com 20 anos de idade procurou pronto-socorro com história de pele\namarelada e vômitos. Refere estar em\ntratamento há 10 dias, na UBS, por tuberculose pulmonar\nbacilífera. Ao exame: PA= 80x40 mmHg e FC= 130 bpm. O plantonista indicou internação. Com\nrelação ás normas de biossegurança, qual a melhor conduta?","options":{"A":"Paciente em quarto com isolamento e profissionais de saúde usando máscara cirúrgica.","B":"Paciente em quarto com isolamento e profissionais de saúde usando máscara respiratória (M95).","C":"Paciente em quarto comum e profissionais de saúde usando máscara respiratória (M95).","D":"Paciente em quarto com isolamento e paciente usando máscara respiratória (M95).","E":"Não há necessidade de isolamento desse paciente."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-217739","number":"217739","sourceNumber":"217739","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O Ministério da Saúde prevê atualmente o tratamento da ILTB (infecção latente pelo\nMycobacterium tuberculosis), independente da realização do PPD (prova tuberculínica) ou do IGRA\n(Interferon Gamma Release Assay) em todos as situações abaixo citadas, EXCETO em:","options":{"A":"Portadores de HIV com contagem de células CD4+ menor ou igual a 350 células/µl.","B":"Recém-nascidos coabitantes de caso-fonte confirmado por critério laboratorial.","C":"Adultos vacinados com BCG que sejam contactantes de pessoa com tuberculose pulmonar\nbacilífera.","D":"Pessoas vivendo com HIV contatos de TB pulmonar com confirmação laboratorial."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-217669","number":"217669","sourceNumber":"217669","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O Brasil está inserido no grupo de 22 países que concentram 80% dos casos de\nTuberculose (TB) no mundo. A doença é frequente em áreas de grande concentração humana e\ncom precários serviços de infraestrutura urbana. Marque a assertiva CORRETA com relação à TB\nna criança:","options":{"A":"Crianças que receberam BCG ao nascer estão protegidas contra a infecção por Mycobacterium\ntuberculosis.","B":"A forma mais frequente de TB extrapulmonar na infância é a TB pleural.","C":"Preconiza-se tratar TB em pré-escolares com rifampicina, isoniazida, pirazinamida e etambutol.","D":"Suspeita-se de TB pulmonar em crianças com pneumonia com evolução ? 2 semanas, sem\nresposta a antimicrobianos."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-182610","number":"182610","sourceNumber":"182610","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um paciente com quadro de hipotensão, taquicardia, hipoperfusão periférica, oligúria e\nencefalopatia, apresenta diminuição da resistência vascular periférica, venodilatação e o\nextravasamento de líquido a partir da microvasculatura levam a um volume intravascular\ninadequado e a uma redução da pré carga. Além disso, apresenta uma diminuição da resposta do\ntrabalho sistólico à reposição de volume, redução da fração de ejeção biventricular e dilatação\nventricular. Diante do quadro acima a melhor conduta terapêutica será:","options":{"A":"Angioplastia coronárias.","B":"Identificar e controlar a fonte de perda sanguínea.","C":"Antibioticoterapia precoce, reposição de líquidos e agentes vasopressores e inotrópicos.","D":"Pericardiocentese de alívio imediata."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-182647","number":"182647","sourceNumber":"182647","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A tuberculose (TB) é uma doença infecciosa de grande impacto no Brasil. O manejo na\nmaioria das vezes é fácil, porém há situações que exigem conhecimento mais aprofundado do\nmédico assistente para o êxito no tratamento do paciente. Com relação à TB, considere as\nafirmativas abaixo: I. É possível tratar empiricamente TB pulmonar em pacientes com pesquisa de\nBAAR negativa, que apresentem quadro clínico-radiológico sugestivo da doença, associado à\nreatividade do PPD; II. Considera-se TB multirresistente quando o teste de sensibilidade evidenciar\nresistência concomitantemente à Rifampicina e Estreptomicina; III. Pacientes com cirrose hepática\nque sejam portadores de TB deverão ser tratados com esquema terapêutico composto por\nestreptomicina, etambutol e ofloxacina; IV. Constitui-se em indicação para realizar cultura para\nmicobactérias no escarro: pesquisa de BAAR positiva em paciente que iniciou tratamento há mais\nde 60 dias.; V. A vacina BCG tem como finalidade evitar a infecção pelo Mycobacterium\ntuberculosis; Estão CORRETAS:","options":{"A":"II, IV.","B":"I, II, V.","C":"I, III, IV.","D":"II, III, IV, V."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-182684","number":"182684","sourceNumber":"182684","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente com quadro de tosse, dor torácica, dispneia, febre e queda do estado geral há\n7 dias. Radiografia de tórax conforme figura\nabaixo. Você espera encontrar quais alterações no\nexame físico pulmonar?","options":{"A":"Murmúrio vesicular abolido e aumento no Frêmito tóraco-vocal.","B":"Murmúrio vesicular reduzido com crepitações e aumento no Frêmito tóraco-vocal.","C":"Murmúrio vesicular reduzido com crepitações e diminuição no Frêmito tóraco-vocal.","D":"Murmúrio vesicular abolido e diminuição no Frêmito tóraco-vocal."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-182640","number":"182640","sourceNumber":"182640","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Escolar de 8 anos, vem à consulta em posto de saúde, com tosse produtiva há mais de\n3 semanas, PPD de 6mm, com imagem radiológica\nmantida após tratamento com amoxicilina,\nusada pensando-se no diagnóstico de pneumonia comunitária. O avô materno está em tratamento\npara Tuberculose (TB) pulmonar há 4 meses. A conduta adequada nesse caso é iniciar:","options":{"A":"Tratamento para pneumonia atípica usando um macrolídeo, reavaliar depois de 2 meses. Não\nhavendo melhoras, avaliar início de tratamento\npara TB pulmonar.","B":"Tratamento com esquema básico para TB com quatro drogas (2RHZE/4RH).","C":"Tratamento com esquema básico para TB com três drogas (2RHZ/4RH).","D":"Quimioprofilaxia para TB com isoniazida."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-135916","number":"135916","sourceNumber":"135916","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em qual das situações abaixo descritas você não usaria o esquema básico para o\ntratamento da tuberculose?","options":{"A":"Paciente com diagnóstico de tuberculose disseminada;","B":"Portador de cirrose hepática Child B;","C":"Mulher com 13 semanas de idade gestacional;","D":"Paciente com lesão renal crônica (clearence de creatinina estimado: 60 ml/min)."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-108643","number":"108643","sourceNumber":"108643","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Gestante de 21 semanas, apresentando tosse, emagrecimento e hiporexia há 5\nsemanas submete-se à pesquisa de BAAR no escarro,\ncujo resultado foi positivo (duas cruzes).\nPaciente diz que há 10 anos iniciou tratamento com esquema básico para tuberculose pulmonar,\nmas abandonou o mesmo depois de 60 dias a partir do início do tratamento. A paciente não\napresenta critérios para internação hospitalar. Nesta situação, a melhor conduta será:","options":{"A":"Iniciar o esquema básico para tuberculose pulmonar.","B":"Solicitar cultura para micobactérias no escarro e iniciar o esquema básico acrescentando\npiridoxina.","C":"Solicitar cultura para micobactérias no escarro e aguardar o resultado para decidir sobre o\nesquema terapêutico.","D":"Iniciar o esquema para tuberculose multirresistente."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-84508","number":"84508","sourceNumber":"84508","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A atual recomendação do Ministério da Saúde quando ocorre exantema leve em um\npaciente que iniciou o esquema básico para a tuberculose pulmonar é:","options":{"A":"Suspender o esquema básico e reiniciar cada tuberculostático separadamente, visando\nidentificar qual foi o responsável pelo surgimento do referido efeito colateral.","B":"Manter o esquema básico e administrar o anti-histamínico.","C":"Substituir apenas a rifampicina pela estreptomicina, pois a primeira é a droga mais implicada nos\ncasos de exantema.","D":"Substituir imediatamente o esquema básico pelo esquema de multirresistência.","E":"Como se trata de um efeito colateral maior, deve-se suspender o esquema básico, aguardar a\nresolução do exantema e depois iniciar um esquema alternativo."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-66915","number":"66915","sourceNumber":"66915","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Segundo o Ministério da Saúde, o esquema atual para tratamento de um caso novo de\ntuberculose em uma criança de 8 anos de idade, deverá ser feito usando:","options":{"A":"Rifampicina, Isoniazida e Pirimetamina;","B":"Rifampicina, Isoniazida e Pirazinamida;","C":"Rifampicina, Isoniazida, Pirimetamina e Etambutol;","D":"Rifampicina, Isoniazida, Pirazinamida e Etambutol."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-50036","number":"50036","sourceNumber":"50036","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente do sexo feminino, 26 anos, refere dor torácica posterior à esquerda\nventilatório-dependente há aproximadamente 30\ndias. Também refere febre baixa com períodos de\nastenia e mal estar geral recorrente. Nega Etilismo e Tabagismo. História patológica pregressa -\nepisódios de infecções de pele recorrentes nos últimos meses. Ao exame físico - Aparelho\nrespiratório - Murmúrio vesicular abolido em 2/3 do pulmão esquerdo; Frêmito toracovocal\ndiminuído em base de pulmão esquerdo; Aparelho cardiovascular - sem anormalidades. Pele -\nLesões eritematosas ovaladas pruriginosas de diversos tamanhos em braços e pernas. Foi\nrealizado RX tórax que revelou: imagem hipodensa (velamento total) na base de pulmão esquerdo,\ncom mediastino e traqueia centrada e área cardíaca de tamanho normal. Com base nos dados\nclínicos apresentados, responda: Qual seria sua próxima conduta propedêutica para diagnóstico do\nCASO CLÍNICO?","options":{"A":"Solicitar TC de tórax de alta resolução;","B":"Solicitar Broncoscopia;","C":"Solicitar Toracocentese diagnóstica com biópsia de pleura;","D":"Solicitar Reação de Mantoux;"},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-50080","number":"50080","sourceNumber":"50080","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente de 46 anos de idade iniciou tratamento com esquema básico para tuberculose\nhá 100 dias em virtude de quadro clínico\ncompatível com tuberculose pulmonar e pesquisa de\nBAAR no escarro positiva (três cruzes) em duas amostras consecutivas. Mensalmente tem\nrealizado pesquisa de BAAR no escarro: 30, 60 e 90 dias, todas positivas. Refere melhora discreta\ndo quadro clínico. Qual a conduta mais adequada neste momento?","options":{"A":"Manter o esquema básico e solicitar cultura para micobactérias no escarro e teste de\nsensibilidade aos tuberculostáticos.","B":"Suspender o esquema básico, solicitar cultura para micobactérias no escarro e teste de\nsensibilidade.","C":"Substituir imediatamente o esquema básico pelo esquema de multirresistência para tuberculose\npreconizado pelo Ministério da Saúde.","D":"Substituir imediatamente o esquema básico pelo esquema IR, o qual acrescenta etambutol ao\nesquema."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-29397","number":"29397","sourceNumber":"29397","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em uma consulta na Unidade de Saúde da Família comparece uma mulher de 30 anos\napresentando há 5 semanas emagrecimento de 4 quilos, tosse produtiva, febre baixa que\ngeralmente aparece após o final da tarde e sudorese o período noturno. Ao exame físico não se\nobservaram alterações significativas, nem na ausculta pulmonar. A partir desse quadro clinico, que\nexame seria mais indicado para identificação do agente etiológico, que permitiria o início do\ntratamento em curto prazo?","options":{"A":"cultura do escarro.","B":"baciloscopia do escarro pela coloração de Ziehl-Nielsen.","C":"raio X de tórax em PA e perfil.","D":"broncoscopia com lavado broncoalveolar.","E":"baciloscopia do escarro pela colaboração de Gram."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-29373","number":"29373","sourceNumber":"29373","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Jovem de 25 anos, evoluindo com febre, sudorese noturna e emagrecimento, com\nquadro de derrame pleural de moderado volume\nà esquerda. A análise do líquido revelou, exsudato\nlinfocítico (90%), dosagem da enzima adenosina desaminase com resultado de 90U/L. Deverá estar\nsendo tratada com:","options":{"A":"Levofloxacina","B":"Fluconazol","C":"Esquema I (tuberculostáticos) 6 meses","D":"Esquema I (tuberculostáticos) 9 meses","E":"Claritromicina"},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-343158","number":"343158","sourceNumber":"343158","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Uma boa amostra de escarro:","options":{"A":"É a que provém da árvore brônquica, obtida sem o esforço de tosse, e não a que se obtém da\nfaringe ou por aspiração de secreções nasais, tampouco a que contém somente saliva.","B":"É a que provém da árvore brônquica, obtida após esforço de tosse, e não a que se obtém da\nfaringe, mas nunca por aspiração de secreções nasais, tampouco a que contém somente saliva.","C":"É a que provém da árvore brônquica, obtida após esforço de tosse, e não a que se obtém da\nfaringe ou por aspiração de secreções nasais, melhor a que contém somente saliva.","D":"É a que provém da árvore brônquica, obtida após esforço de tosse, e não a que se obtém da\nfaringe ou por aspiração de secreções nasais, tampouco a que contém somente saliva."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-341044","number":"341044","sourceNumber":"341044","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem, 81 anos de idade, internado em enfermaria de hospital secundário por quadro\nde pneumonia, em uso de ceftriaxona. No 5º dia\nde internação, evoluiu com delirium hipoativo,\nhipotensão e febre. Foi realizado novo rastreio infeccioso, sendo diagnosticada infecção do trato\nurinário. A urocultura foi entregue ao médico com um problema de impressão, mas era possível ler\n\"\"ESBL positivo\"\". Considerando o caso clínico descrito, indique, entre as bactérias citadas a que,\nmais provavelmente, cresceu na urocultura:","options":{"A":"Staphylococcus aureus.","B":"Proteus mirabilis.","C":"Klebsiella pneumoniae.","D":"Enterococcus sp."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-343165","number":"343165","sourceNumber":"343165","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em PVHIV, o acometimento ganglionar da Tuberculose tende a ser bilateral, associado\ncom maior comprometimento do estado geral.","options":{"A":"Ao exame físico, os gânglios podem apresentar-se endurecidos e nunca amolecidos, aderentes\nentre si e aos planos profundos, podendo\nevoluir para flutuação e/ou fistulização espontânea, com\na inflamação da pele adjacente.","B":"Ao exame físico, os gânglios podem apresentar-se endurecidos ou amolecidos, não aderentes\nentre si e aos planos profundos, podendo\nevoluir para flutuação e/ou fistulização espontânea, com\na inflamação da pele adjacente.","C":"Ao exame físico, os gânglios podem apresentar-se endurecidos ou amolecidos, aderentes entre\nsi e aos planos profundos, podendo evoluir\npara flutuação e/ou fistulização espontânea, com a\ninflamação da pele adjacente.","D":"Ao exame físico, os gânglios podem apresentar-se endurecidos ou amolecidos, aderentes entre\nsi e aos planos profundos, podendo evoluir\npara flutuação, mas não para fistulização espontânea,\ncom a inflamação da pele adjacente."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-343168","number":"343168","sourceNumber":"343168","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Outra forma de TB do sistema nervoso central é a forma localizada (tuberculomas).\nPodemos indicar como correto o item:","options":{"A":"Nessa apresentação, o quadro clínico é o de um processo expansivo intracraniano de\ncrescimento rápido , com sinais e sintomas de\nhipertensão intracraniana, sendo que a febre pode\nnão estar presente.","B":"Nessa apresentação, o quadro clínico é o de um processo expansivo intracraniano de\ncrescimento lento, com sinais e sintomas de\nhipertensão intracraniana, sendo que a febre sempre\ndeve estar presente.","C":"Nessa apresentação, o quadro clínico é o de um processo expansivo intracraniano de\ncrescimento lento, com sinais e sintomas de\nhipertensão intracraniana, sendo que a febre pode não\nestar presente.","D":"Nessa apresentação, o quadro clínico não é o de um processo expansivo intracraniano de\ncrescimento lento, com sinais e sintomas de\nhipertensão intracraniana, sendo que a febre pode não\nestar presente."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-343221","number":"343221","sourceNumber":"343221","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A rotina radiográfica básica em pacientes com suspeita de tuberculose inclui o uso das\nincidências posteroanteriores e perfil esquerdo.","options":{"A":"A radiografia apicolordótica (incidência de Fleischner) poderá complementar a rotina nos casos\nem que há dúvidas na interpretação dos\nápices pulmonares.","B":"A radiografia apicolordótica (incidência de Fleischner) nunca poderá complementar a rotina nos\ncasos em que há dúvidas na interpretação dos\nápices pulmonares.","C":"A radiografia apicolordótica (incidência de Fleischner) poderá complementar a rotina, mas não\nnos casos em que há dúvidas na interpretação\ndos ápices pulmonares.","D":"A radiografia apicolordótica (incidência de Fleischner) poderá complementar a rotina nos casos\nem que há dúvidas na interpretação das bases\npulmonares."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-343224","number":"343224","sourceNumber":"343224","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"As alterações radiográficas da Tuberculose Pulmonar:","options":{"A":"Podem ser abordadas considerando as seguintes situações: tuberculose primária e tuberculose\nsecundária ou de reinfecção.","B":"Podem ser abordadas considerando as seguintes situações: tuberculose primária e tuberculose\nsecundária, mas não de reinfecção.","C":"Podem ser abordadas considerando apenas tuberculose secundária.","D":"Podem ser abordadas considerando apenas a tuberculose primária."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-314194","number":"314194","sourceNumber":"314194","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A atuação dos medicamentos anti-TB difere conforme o metabolismo bacilar. Sendo\ncorreto o item:","options":{"A":"Na população intramacrofágica, agem os fármacos que melhor se difundem no meio intracelular\ne em pH alcalino: rifampicina, pirazinamida e\netambutol.","B":"Na população intramacrofágica, agem os fármacos que melhor se difundem no meio intracelular\ne em pH ácido: rifampicina, pirazinamida e\netambutol.","C":"Na população intramacrofágica, agem os fármacos que pior se difundem no meio intracelular e\nem pH ácido: rifampicina, pirazinamida e etambutol.","D":"Na população intramacrofágica, não agem os fármacos que melhor se difundem no meio\nintracelular e em pH ácido: rifampicina, pirazinamida e etambutol."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-314197","number":"314197","sourceNumber":"314197","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Nas lesões caseosas fechadas da tuberculose, podemos indicar como correto o item:","options":{"A":"O fármaco menos efetivo é a rifampicina, sendo a ação da isoniazida mais lenta e demorada.","B":"O fármaco mais efetivo é a rifampicina, sendo a ação da isoniazida mais lenta e demorada.","C":"O fármaco mais efetivo é a rifampicina, sendo a ação da isoniazida mais rápida.","D":"O fármaco não é a rifampicina, sendo a ação da isoniazida mais lenta e demorada."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-314232","number":"314232","sourceNumber":"314232","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Considerando então a necessidade de intensificar a busca de pessoas com Infecção\nLatente pelo Mycobacterium tuberculosis (ILTB),\nampliando a solicitação de exames diagnósticos e\ndo tratamento nos serviços de saúde, podemos concordar que:","options":{"A":"Reduzindo o conhecimento do perfil epidemiológico da Infecção Latente pelo Mycobacterium\ntuberculosis (ILTB) no país, apresentar as\nestratégias de fortalecimento e ampliação da vigilância\nda ILTB no Brasil.","B":"Aumentando o conhecimento do perfil epidemiológico da Infecção Latente pelo Mycobacterium\ntuberculosis (ILTB) no país, apresentar as\nestratégias de fortalecimento e redução da vigilância da\nILTB no Brasil.","C":"Aumentando o conhecimento do perfil epidemiológico da Infecção Latente pelo Mycobacterium\ntuberculosis (ILTB) no país, apresentar as estratégias de fortalecimento e ampliação da vigilância\nda ILTB no Brasil.","D":"Aumentando o conhecimento do perfil epidemiológico da Infecção Latente pelo Mycobacterium\ntuberculosis (ILTB) no país, e não apresentar as estratégias de fortalecimento e ampliação da\nvigilância da ILTB no Brasil."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-315210","number":"315210","sourceNumber":"315210","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O esquema de tratamento da tuberculose pulmonar é adotado em duas fases distintas:\num fase de ataque seguida por uma fase de\nmanutenção. Qual dentre os tratamentos abaixo é\npadronizado pelo ministério da saúde para tratamento da tuberculose pulmonar no Brasil?\n\nRifanpicina ? R. Isoniazida ? H. Pirazidamida ? P. Etambutol ? E.","options":{"A":"R, H ( 2 meses) e P,E ( 2 meses)","B":"R,H,P ( 3 meses) e P,E ( 2 meses)","C":"R,H,P,E (2 meses) e R,H ( 4 meses)","D":"R,H,P,E (4 meses) e R,H ( 2 meses)","E":"Nenhuma das alternativas"},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-275973","number":"275973","sourceNumber":"275973","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O principal agente etiológico das pneumonias comunitárias é:","options":{"A":"Staphylococcus aureus.","B":"Streptococcus pneumoniae.","C":"Haemophilus influenzae.","D":"Mycoplasma pneumoniae.","E":"Bacillus anthracis."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-283718","number":"283718","sourceNumber":"283718","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem, 45 anos de idade, morador de zona rural, procurou atendimento médico por\nqueixa de úlcera dolorosa em dorso do pé\nesquerdo há seis meses. No interrogatório sistemático,\nqueixou-se também de astenia e tosse seca. Tabagista de 25 anos/maço, sem outras\ncomorbidades. Ao exame físico, regular estado geral, afebril. Apresentava úlcera com 20mm de\ndiâmetro, com bordas elevadas, eritematosas e fundo com pontilhado hemático. Realizada biópsia\nda lesão, evidenciou processo granulomatoso, com presença de células leveduriformes com\nbrotamento em roda de leme. Radiografia de tórax com infiltrado reticulo-nodular difuso. Paciente\nperdeu seguimento e, três meses depois, voltou a procurar atendimento médico com quadro de\nhipotensão, apresentando exames laboratoriais com Na: 119mEq/L e K: 6,1mEq/L, necessitando de\ninternação hospitalar. Diante do caso. Identifique a hipótese diagnóstica principal no atendimento\ninicial.","options":{"A":"Paracoccidioidomicose.","B":"Leishmaniose.","C":"Esporotricose.","D":"Tuberculose."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-283719","number":"283719","sourceNumber":"283719","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem, 45 anos de idade, morador de zona rural, procurou atendimento médico por\nqueixa de úlcera dolorosa em dorso do pé\nesquerdo há seis meses. No interrogatório sistemático,\nqueixou-se também de astenia e tosse seca. Tabagista de 25 anos/maço, sem outras\ncomorbidades. Ao exame físico, regular estado geral, afebril. Apresentava úlcera com 20mm de\ndiâmetro, com bordas elevadas, eritematosas e fundo com pontilhado hemático. Realizada biópsia\nda lesão, evidenciou processo granulomatoso, com presença de células leveduriformes com\nbrotamento em roda de leme. Radiografia de tórax com infiltrado reticulo-nodular difuso. Paciente\nperdeu seguimento e, três meses depois, voltou a procurar atendimento médico com quadro de\nhipotensão, apresentando exames laboratoriais com Na: 119mEq/L e K: 6,1mEq/L, necessitando de\ninternação hospitalar. Diante do caso. Indique o tratamento de primeira escolha da principal\nhipótese diagnóstica no atendimento inicial.","options":{"A":"Fluconazol.","B":"Itraconazol.","C":"Rifampicina, Isoniazida, Pirazinamida e Etambutol.","D":"Glucantime."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-283720","number":"283720","sourceNumber":"283720","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem, 45 anos de idade, morador de zona rural, procurou atendimento médico por\nqueixa de úlcera dolorosa em dorso do pé\nesquerdo há seis meses. No interrogatório sistemático,\nqueixou-se também de astenia e tosse seca. Tabagista de 25 anos/maço, sem outras\ncomorbidades. Ao exame físico, regular estado geral, afebril. Apresentava úlcera com 20mm de\ndiâmetro, com bordas elevadas, eritematosas e fundo com pontilhado hemático. Realizada biópsia\nda lesão, evidenciou processo granulomatoso, com presença de células leveduriformes com\nbrotamento em roda de leme. Radiografia de tórax com infiltrado reticulo-nodular difuso. Paciente\nperdeu seguimento e, três meses depois, voltou a procurar atendimento médico com quadro de\nhipotensão, apresentando exames laboratoriais com Na: 119mEq/L e K: 6,1mEq/L, necessitando de\ninternação hospitalar. Diante do caso. Indique a hipótese diagnóstica principal diante da\ncomplicação apresentada posteriormente.","options":{"A":"Doença de Addison.","B":"Síndrome de Cushing.","C":"Síndrome perdedora de sal.","D":"Síndrome de secreção inapropriada de hormônio antidiurético."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-278630","number":"278630","sourceNumber":"278630","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Sobre as características gerais da imunoparalisia na sepse assinale a alternativa\nincorreta.","options":{"A":"A imunoparalisia é um preditor independente de mortalidade em pacientes sépticos.","B":"A imunoparalisia representa uma forma de imunodeficiência primária latente, desencadeada por\ninsultos, como a sepse.","C":"O diagnóstico de imunoparalisia pode ser sugerido por meio da dosagem da expressão\nmonocitária do HLA-DR e da capacidade de\nprodução de citocinas (TNF-alfa) em resposta a LPS.","D":"Apesar das causas especificas da imunoparalisia não serem totalmente conhecidas, tem se\ntornado clara a influência de medicações usadas em UTI, além do papel de fatores genéticos e\nepigenéticos."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-280460","number":"280460","sourceNumber":"280460","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A associação do nódulo de Ghon e linfonodomegalias hilares na tuberculose é\ndenominada Complexo de Ranke. Sobre isso, está correto que:","options":{"A":"Esses nódulos são potencialmente focos de bacilos, que nunca podem evoluir para a cura, com\nfibrose e calcificação, ou para a doença.","B":"Esses nódulos são potencialmente focos de bacilos, que podem evoluir para a cura, com fibrose\ne calcificação, e não para a doença.","C":"Esses nódulos são potencialmente focos de bacilos, que jamais podem evoluir para a cura, com\nfibrose e calcificação, e sempre para a doença.","D":"Esses nódulos são potencialmente focos de bacilos, que podem evoluir para a cura, com fibrose\ne calcificação, ou para a doença."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-278671","number":"278671","sourceNumber":"278671","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Intervenções direcionadas aos determinantes socioeconômicos podem contribuir na\nmelhoria do controle da TB no Brasil, sendo adequado o item:","options":{"A":"Erradicar a pobreza, em todas as suas formas e dimensões, excluindo a pobreza extrema,\naparece como requisito indispensável para o\ndesenvolvimento sustentável.","B":"Erradicar a pobreza, em todas as suas formas e dimensões, incluindo a pobreza extrema,\naparece como requisito indispensável para o\ndesenvolvimento não sustentável.","C":"Erradicar a pobreza, em todas as suas formas e dimensões, incluindo a pobreza extrema,\naparece como requisito dispensável para o\ndesenvolvimento sustentável.","D":"Erradicar a pobreza, em todas as suas formas e dimensões, incluindo a pobreza extrema,\naparece como requisito indispensável para o\ndesenvolvimento sustentável."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-280461","number":"280461","sourceNumber":"280461","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A obstrução brônquica total ou parcial na tuberculose pode ocasionar atelectasias, que\nsão visualizadas na radiografia e na TC de tórax.\nPodemos assim concordar com o item:","options":{"A":"O aumento de linfonodos mediastinais não pode ocasionar compressão dos brônquios e lesão\nda parede brônquica com drenagem do material necrótico para dentro da luz brônquica (TB\nendobrônquica).","B":"O aumento de linfonodos mediastinais pode ocasionar compressão dos brônquios e lesão da\nparede brônquica com drenagem do material necrótico para fora da luz brônquica (TB\nendobrônquica).","C":"O aumento de linfonodos mediastinais pode ocasionar compressão dos brônquios e lesão da\nparede brônquica com drenagem do material necrótico para dentro da luz brônquica (TB\nendobrônquica).","D":"O aumento de linfonodos mediastinais não pode ocasionar compressão dos brônquios e lesão\nda parede brônquica sem drenagem do material necrótico para dentro da luz brônquica (TB\nendobrônquica)."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-280465","number":"280465","sourceNumber":"280465","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Para idosos com tuberculose, podemos determinar como correto o item:","options":{"A":"É raro o acometimento dos segmentos inferiores, assim como menor ocorrência de cavidades,\ndificultando ainda mais o diagnóstico nessa faixa etária.","B":"É comum o acometimento dos segmentos inferiores, assim como menor ocorrência de\ncavidades, facilitando o diagnóstico nessa faixa etária.","C":"É comum o acometimento dos segmentos inferiores, assim como menor ocorrência de\ncavidades, dificultando ainda mais o diagnóstico nessa faixa etária.","D":"É comum o acometimento dos segmentos inferiores, assim como maior ocorrência de\ncavidades, dificultando ainda mais o diagnóstico nessa faixa etária."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-280466","number":"280466","sourceNumber":"280466","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A presença de bacilos ou proteínas do bacilo decorrente de disseminação\nhematogênica e/ou linfática ou contato\nanatômico do bacilo da tuberculose, pode levar a situação\ndescrita corretamente no item:","options":{"A":"Pode acometer a pleura e/ou o pericárdio, com consequente derrame pleural e, menos\nfrequentemente, derrame pericárdico.","B":"Pode acometer a pleura, mas não o pericárdio, com consequente derrame pleural e, menos\nfrequentemente, derrame pericárdico.","C":"Pode acometer a pleura e/ou o pericárdio, com consequente derrame pleural e, nunca com\nderrame pericárdico.","D":"Pode acometer a pleura e/ou o pericárdio, com consequente derrame pleural e, menos\nfrequentemente, miocardite."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-279097","number":"279097","sourceNumber":"279097","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A cintilografia pulmonar ventilação-perfusão pode ser útil na avaliação pré-operatória de\npacientes com indicação de cirurgia para tratamento da tuberculose, sendo adequado o item:","options":{"A":"Porém, não identificando áreas com déficit ventilatório e/ou perfusional.","B":"Identificando áreas com déficit ventilatório e não do perfusional.","C":"Identificando áreas com déficit apenas perfusional.","D":"Identificando áreas com déficit ventilatório e/ou perfusional."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-278678","number":"278678","sourceNumber":"278678","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"No Brasil, observou-se uma expansão em ações relacionadas à educação, saúde,\nemprego, habitação, seguridade social e\ndesenvolvimento social durante os últimos 40 anos. Desse\nmodo, os progressos nos determinantes sociais da saúde têm tido um efeito na saúde dos\nbrasileiros. Podemos concordar que:","options":{"A":"A transmissão e adoecimento por TB são influenciados por fatores demográficos, sociais e\neconômicos.","B":"A transmissão e adoecimento por TB não são influenciados por fatores demográficos, sociais e\neconômicos.","C":"A transmissão e não o adoecimento por TB são influenciados por fatores demográficos, sociais e\neconômicos.","D":"A transmissão e adoecimento por TB não são influenciados por fatores demográficos, sociais,\nsomente por econômicos."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-279099","number":"279099","sourceNumber":"279099","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Podemos indicar como inadequado a respeito de Tuberculose TB óssea o seguinte\nitem:","options":{"A":"Na TB óssea, a destruição da porção anterior dos corpos vertebrais e áreas de osteólise,\nprincipalmente em epífise de ossos longos, sugere doença em atividade.","B":"O acometimento de tecidos moles adjacentes, como abscessos para vertebrais visualizados na\nRNM, também sugere doença ativa.","C":"A involução desses achados adjacentes às alterações ósseas na RNM é útil no\nacompanhamento da doença e pode, em conjunto\ncom critérios clínicos, definir a alta do tratamento\ndas formas ósseas.","D":"Na TB óssea, a destruição da porção anterior dos corpos vertebrais e áreas de osteólise,\nprincipalmente em epífise de ossos longos, sugere doença em regressão."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-279102","number":"279102","sourceNumber":"279102","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Determinado a partir desse foco inicial, pode ocorrer a progressão para necrose\ncaseosa, eliminação do material necrótico e\ndisseminação broncogênica da tuberculose. As\napresentações radiológicas dessa fase são as cavidades, consolidações, nódulos, massas ou\nopacidades retículo-nodulares. Podemos indicar que:","options":{"A":"O acometimento das cadeias ganglionares depende da localização do processo inflamatório no\nparênquima pulmonar.","B":"O acometimento das cadeias ganglionares independe da localização do processo inflamatório no\nparênquima pulmonar.","C":"O acometimento das cadeias ganglionares depende da localização do processo inflamatório na\npleura.","D":"O acometimento das cadeias neuronais depende da localização do processo inflamatório no\nparênquima pulmonar."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-249391","number":"249391","sourceNumber":"249391","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Considerando que a proteína C reativa é secretada pelas células hepáticas em\nresposta à elevação das interleucinas 6,1? e TNF-?. Apenas não podemos aceitar o seguinte:","options":{"A":"A proteína C reativa se eleva em qualquer processo inflamatório.","B":"Outras fontes da proteína C reativa reconhecidas são os linfócitos, monócitos, neurônios e\nplacas ateroscleróticas.","C":"O pico da proteína C reativa ocorre ao redor de 48h após o estímulo agressor.","D":"Sua meia vida plasmática é ao redor de 19h somente em situação de saúde."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-249326","number":"249326","sourceNumber":"249326","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A vacina influenza é constituída por vírus inativados existindo comprovação de que não\npodem causar a doença excelente níveis de\ntolerância. Não podemos aceitar que:","options":{"A":"Processos agudos respiratórios (gripe e resfriado) após a administração da vacina significam\nprocessos coincidentes e não estão relacionados com a vacina.","B":"Os eventos adversos pós-vacinação (EAPV) podem ser relacionados à composição da vacina,\naos indivíduos vacinados, à técnica usada em sua\nadministração, ou a coincidências com outros\nagravos.","C":"De acordo com sua localização, podem ser locais ou sistêmicos e, de acordo com sua\ngravidade, podem ser leves, moderados ou graves.","D":"Os abscessos, normalmente, encontram-se associados com infecção primaria e nunca erros na\ntécnica de aplicação."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-249445","number":"249445","sourceNumber":"249445","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A respeito de medidas de controle ambiental, grupo de medidas inclui adaptação de\nconsultórios que precisam ser arejados, com entrada de luz solar e janelas abertas. Sendo incorreto\nque:","options":{"A":"ventiladores direcionados para janelas podem contribuir para criar um direcionamento do fluxo\nde ar para área externa.","B":"exaustores exercem essa função de forma mais eficaz. Quando adquiridos, devem levar em\nconsideração a capacidade do equipamento e o volume de ar da sala que deve ser trocado cerca\nde seis a 15 vezes por hora.","C":"a instalação de aparelhos de ar condicionado em consultórios facilita a obtenção de exaustão\nadequada.","D":"em locais muito quentes, cuja utilização de aparelhos de ar condicionado proporciona conforto\nadicional, estudo de fluxo e adequação do\nexaustor, com trocas adequadas ao condicionador de ar,\npode ser feito por profissionais qualificados."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-252942","number":"252942","sourceNumber":"252942","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"\"Estima-se que ¼ da população mundial esteja infectada pelo Mycobacterium\ntuberculosis, agente causador da tuberculose\n(TB). Em 2015, a Organização Mundial da Saúde\n(OMS) publicou a Estratégia pelo Fim da Tuberculose (End TB Strategy), que estabelece metas\narrojadas para o fim da TB como problema de saúde pública até 2035. De acordo com a OMS, para\no alcance dessas metas, é imprescindível aumentar o rastreio, diagnóstico e o tratamento da\ninfecção latente pelo Mycobacterium tuberculosis, reduzindo o risco de adoecimento e,\nconsequentemente, evitando a contaminação. Quanto maior o número de Unidades Básicas de\nSaúde (UBS) e de profissionais capacitados desenvolvendo ações de controle da TB, mais\nabrangente serão as atividades voltadas ao alcance das metas.\" BRASIL, Ministério da Saúde.\n\nSecretário de Vigilância em Saúde, Departamento de Vigilância das Doenças Transmissíveis,\nProtocolo de vigilância da infecção pelo\nMycobacterium tuberculosis no Brasil/Ministério da Saúde,\nBrasília 2018. Adolescente, 17 anos de idade, contactante de paciente com tuberculose pulmonar\nbacilífera, apresenta teste tuberculínico com induração de 5mm. O adolescente fez uso de BCG na\ninfância e é HIV negativo. Está assintomático e tem RX de tórax normal. Esse paciente deve ser\nconsiderado:","options":{"A":"Portador de imunidade conferida pelo BCG, com menos risco de contágio, sem indicação para\nseguimento.","B":"Indeterminado do ponto de vista clínico/epidemiológico, com indicação para seguimento clínico\nsem tratamento.","C":"Portador de tuberculose latente com risco de desenvolver tuberculose ativa nos próximos dois\nanos.","D":"Portador de tuberculose latente e com indicação para tratamento prioritário com rifampicina."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-252943","number":"252943","sourceNumber":"252943","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"\"Estima-se que ¼ da população mundial esteja infectada pelo Mycobacterium\ntuberculosis, agente causador da tuberculose\n(TB). Em 2015, a Organização Mundial da Saúde\n(OMS) publicou a Estratégia pelo Fim da Tuberculose (End TB Strategy), que estabelece metas\narrojadas para o fim da TB como problema de saúde pública até 2035. De acordo com a OMS, para\no alcance dessas metas, é imprescindível aumentar o rastreio, diagnóstico e o tratamento da\ninfecção latente pelo Mycobacterium tuberculosis, reduzindo o risco de adoecimento e,\nconsequentemente, evitando a contaminação. Quanto maior o número de Unidades Básicas de\nSaúde (UBS) e de profissionais capacitados desenvolvendo ações de controle da TB, mais\nabrangente serão as atividades voltadas ao alcance das metas.\" BRASIL, Ministério da Saúde.\n\nSecretário de Vigilância em Saúde, Departamento de Vigilância das Doenças Transmissíveis,\nProtocolo de vigilância da infecção pelo\nMycobacterium tuberculosis no Brasil/Ministério da Saúde,\nBrasília 2018. No diagnóstico de tuberculose latente, têm sido usados testes alternativos. A\ncomparação entre os Testes de Expressão de Interferon Gama (IGRAM) e o Teste Tuberculínico\npermite a seguinte conclusão:","options":{"A":"A acurácia e os valores preditivos dos dois testes são semelhantes.","B":"Ambos os testes são afetados pela vacinação prévia pelo BCG.","C":"A interferência de micobactérias atípicas é semelhante nos dois testes.","D":"Ambos os testes estão disponíveis nos Centros de Referência para TB do SUS."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-252944","number":"252944","sourceNumber":"252944","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"\"Estima-se que ¼ da população mundial esteja infectada pelo Mycobacterium\ntuberculosis, agente causador da tuberculose\n(TB). Em 2015, a Organização Mundial da Saúde\n(OMS) publicou a Estratégia pelo Fim da Tuberculose (End TB Strategy), que estabelece metas\narrojadas para o fim da TB como problema de saúde pública até 2035. De acordo com a OMS, para\no alcance dessas metas, é imprescindível aumentar o rastreio, diagnóstico e o tratamento da\ninfecção latente pelo Mycobacterium tuberculosis, reduzindo o risco de adoecimento e,\nconsequentemente, evitando a contaminação. Quanto maior o número de Unidades Básicas de\nSaúde (UBS) e de profissionais capacitados desenvolvendo ações de controle da TB, mais\nabrangente serão as atividades voltadas ao alcance das metas.\" BRASIL, Ministério da Saúde.\n\nSecretário de Vigilância em Saúde, Departamento de Vigilância das Doenças Transmissíveis,\nProtocolo de vigilância da infecção pelo\nMycobacterium tuberculosis no Brasil/Ministério da Saúde,\nBrasília 2018. A investigação para tuberculose latente está indicada em várias condições de\nexposição. Entre os indivíduos listados, identifique o paciente no qual os testes para investigação\nda TB latente são dispensáveis, passando-se diretamente para a quimioprofilaxia.","options":{"A":"Paciente portador de HIV.","B":"Profissional de saúde exposto.","C":"Paciente com imunossupressão.","D":"Recém-nascido de mãe com TB ativa."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-249455","number":"249455","sourceNumber":"249455","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Fortalecer a articulação intra e intersetorial para garantia dos direitos humanos e\ncidadania nas ações de controle da doença, para pautar a tuberculose nas seguintes agendas de\ntrabalho da assistência social, educação, justiça e de direitos humanos. Nesse contexto, não\npodemos assumir o item:","options":{"A":"Implementar as recomendações das políticas vigentes de articulação intra e intersetorial.","B":"Implementar as recomendações da Instrução Operacional conjunta entre Secretaria de Vigilância\nem Saúde (SVS) e Secretaria Nacional de\nAssistência Social (SNAS).","C":"Fomentar a elaboração de legislações que contribuam para proteção social da pessoa com\ntuberculose.","D":"Não permitir a exposição da tuberculose nos meios de comunicação disponíveis."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-249456","number":"249456","sourceNumber":"249456","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Fortalecer a participação da sociedade civil nas estratégias de enfrentamento da\ndoença, para articulação entre gestão e\nsociedade civil para o controle da tuberculose; podemos\napenas aceitar que:","options":{"A":"Inibir ações de comunicação e mobilização social desenvolvidas pela sociedade civil.","B":"Excluir a participação da sociedade civil na elaboração de campanhas de comunicação de\ntuberculose.","C":"Fomentar ações comunitárias de mobilização social para o enfrentamento da doença.","D":"Desarticulação entre gestão e sociedade civil para o controle da tuberculose."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-249457","number":"249457","sourceNumber":"249457","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Assinale a alternativa que não se caracteriza como um dos Princípios da Estratégia\npelo Fim da Tuberculose:","options":{"A":"Proteção e promoção dos direitos humanos, éticos e de equidade.","B":"Adaptação da estratégia sem metas nos países, com colaboração no âmbito global.","C":"Forte envolvimento das organizações da sociedade civil e de base comunitária.","D":"Gestão e responsabilização do governo, com componentes de monitoramento e avaliação."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-249276","number":"249276","sourceNumber":"249276","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Todo ambiente onde os pacientes com TB circulam, produz aerossóis contendo\nMycobacterium tuberculosis (bacilo da tuberculose), e oferece algum risco de transmissão. Para\ndiminuí-lo é preciso considerar alguns pressupostos, estando errado apenas que:","options":{"A":"a transmissão da tuberculose se faz por via respiratória, pela inalação de aerossóis produzidos\npela tosse, fala ou espirro de um doente com TB\nativa de vias aéreas, salvo raríssimas exceções.","B":"quanto maior a ventilação desse ambiente, maior será a probabilidade de infectar os\ncircunstantes.","C":"quanto maior a intensidade da tosse é a concentração de bacilos no ambiente.","D":"com o início do tratamento adequado e o uso correto de medicamentos antiTB, a\ntransmissibilidade diminui rapidamente em duas a três semanas."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-216271","number":"216271","sourceNumber":"216271","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Conceituando a fisiopatologia do choque séptico e disfunção miocárdica induzida pela\nsepse, podemos apenas concordar com o item que se mostra CORRETO:","options":{"A":"Resulta em lesão miocárdica direta e indireta, levando à diminuição na função cardíaca sistólica\ne diastólica.","B":"Resulta em lesão miocárdica somente indireta, levando à diminuição na função cardíaca sistólica\ne diastólica.","C":"Resulta em lesão miocárdica direta e indireta, não levando à diminuição na função cardíaca\nsistólica e diastólica.","D":"Resulta em lesão miocárdica direta e indireta, levando à diminuição na função cardíaca sistólica\nexclusivamente."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-212212","number":"212212","sourceNumber":"212212","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Mulher, 18 anos, nega alergia medicamentosa, nega comorbidades, nega uso recente\nde antibióticos. Veio ao ambulatório com queixa de\nastenia, tosse seca, febre e cefaleia. No exame\nfísico, ausculta pulmonar apresentava estertores inspiratórios bilaterais no terço inferior dos\npulmões. Temperatura 38°C e frequência respiratória de 24 incursões por minuto. Qual tratamento\ndeveria ser indicado?","options":{"A":"Azitromicina por 10 dias.","B":"Claritromicina por 3 dias.","C":"Levofloxacino por 5-7 dias.","D":"Betalactâmico associado a macrolídeo por 5-7 dias.","E":"Amoxicilina ou amoxicilina + ácido clavulânico por 7 dias."},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-215473","number":"215473","sourceNumber":"215473","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Nas alternativas a seguir, assinale a CORRETA em relação ao acesso venoso em um\npaciente com diagnóstico de sepse.","options":{"A":"Não perder tempo com acesso venoso e administrar todas as drogas pela cânula orotraqueal.","B":"Tentar passar um acesso venoso central em primeiro lugar.","C":"O acesso venoso periférico é uma alternativa prática para se iniciar reposição volêmica e drogas\nvasoativas, se necessário.","D":"O acesso intraósseo não deve ser utilizado pela dificuldade técnica."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-215482","number":"215482","sourceNumber":"215482","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Nas alternativas a seguir, assinale a INCORRETA em relação à lavagem das mãos no\nambiente hospitalar.","options":{"A":"O álcool gel substitui a lavagem das mãos em praticamente todas as situações.","B":"Deve ser realizada antes e após qualquer contato com o paciente.","C":"Requer, obrigatoriamente, a retirada de anéis e relógios.","D":"A lavagem das mãos com água e sabão utilizando a técnica correta, leva menos de 1 minuto."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-215250","number":"215250","sourceNumber":"215250","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Quais são as três fases do Empiema Pleural?","options":{"A":"Edematosa, catarral e crônica.","B":"Eritematosa, purulenta e cavitária.","C":"Exsudativa, fibrinopurulenta e organização.","D":"Piogênica, fibrinosa e necrótica."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-216225","number":"216225","sourceNumber":"216225","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Sobre o Abscesso Pulmonar é INCORRETO que","options":{"A":"o abscesso primário do pulmão resulta de pneumonia por Streptococcus hemoliticus,\nStafilococcus aureus, Klebsiella Pneumoniae e Haemophilus influenza.","B":"Broncofibroendoscopia é de indicação absoluta.","C":"Quando o abscesso pulmonar drena espontaneamente para a via aérea principal, o tratamento\nde escolha é clínico.","D":"A taxa de mortalidade é alta alcançando até 60% nos pacientes tratados com cirurgia."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-219891","number":"219891","sourceNumber":"219891","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Qual dos achados abaixo não se espera encontrar na radiografia de tórax de paciente\ncom tuberculose primária?","options":{"A":"Adenopatia hilar.","B":"Derrame pleural.","C":"Infiltrado pulmonar.","D":"Lesão cavitária."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-215562","number":"215562","sourceNumber":"215562","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A vacina influenza é constituída por vírus inativados, o que significa que contém\nsomente vírus mortos ? existindo comprovação de\nque não podem causar a doença ? além de\npossuir um perfil de segurança excelente e bons níveis de tolerância. Podemos, apenas,\nCONCORDAR que:","options":{"A":"Processos agudos respiratórios (gripe e resfriado) após a administração da vacina significam\nprocessos coincidentes e estão relacionados com a vacina.","B":"Processos agudos respiratórios (gripe e resfriado) após a administração da vacina significam\nprocessos coincidentes e não estão relacionados com a vacina.","C":"Processos agudos respiratórios (gripe e resfriado) antes da administração da vacina significam\nprocessos coincidentes e estão relacionados com a vacina.","D":"Processos agudos respiratórios (gripe e resfriado) após a administração da vacina significam\nprocessos não coincidentes e estão relacionados com a vacina."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-215563","number":"215563","sourceNumber":"215563","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A vacina influenza é constituída por vírus inativados, o que significa que contém\nsomente vírus mortos que não podem causar a\ndoença. As manifestações locais, como dor e\nsensibilidade no local da injeção, eritema e enduração, ocorrem em 10 a 64% dos pacientes, NÃO\npodemos concordar que:","options":{"A":"São malignas e não autolimitadas.","B":"Geralmente, resolvidas em 48 horas.","C":"Em quase todos os casos, há uma recuperação espontânea e não se requer atenção médica.","D":"Os abscessos, normalmente, encontram-se associados com infecção secundária ou erros na\ntécnica de aplicação."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-180149","number":"180149","sourceNumber":"180149","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em relação a tuberculose . Assinale a alternativa correta:","options":{"A":"Os corticosteroides devem ser utilizados como\nadjuvantes no tratamento","B":"A forma meníngea geralmente apresenta evolução\nbenigna","C":"O diagnostico de tuberculose ativa na infância sugere fortemente o contato com adulto bacilifero\nno domicilio","D":"O PPD maior que 5 mm em crianças vacinadas há\nmais de 2 anos significa doença ativa","E":"A pesquisa direta do bacilo álcool acido resistente no liquor é altamente sensível , podendo ser\ndescartada a meningite tuberculosa se negativa."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-182731","number":"182731","sourceNumber":"182731","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente de 6 anos de idade encontra-se internado na UTI Pediátrica com diagnóstico\nde choque séptico de origem pulmonar. Está em\nventilação pulmonar mecânica com os seguintes\nparâmetros: FiO2= 60% PIP= 24 PEEP= 8 FR= 18irpm. Apresenta a seguinte gasometria arterial:\npH= 7,3 PaCO2= 40mmHg PaO2= 60mmHg BE= -7,0 SatO2= 95%. A saturação do sangue venoso\nmisto foi de 55% e o índice cardíaco foi de 3,5L/min. Dosagem de hemoglobina de 8,0g/dl. Das\nalternativas apresentadas abaixo, assinale aquela que seria a melhor conduta para aumentar a\noferta global de oxigênio:","options":{"A":"Aumentar a PEEP para 10mmHg.","B":"Realizar transfusão de concentrado de hemácias de 10ml/Kg a 20ml/Kg.","C":"Aumentar a FiO2 para 100%.","D":"Iniciar ECMO imediatamente."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-183614","number":"183614","sourceNumber":"183614","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Qual dos exames laboratoriais do líquido pleural é o mais sugestivo de empiema\npleural?","options":{"A":"DHL acima de 500 U/L.","B":"Amilase acima de 200 U/L.","C":"Triglicerídeos acima de 110 mg/dl.","D":"pH abaixo de 7,2."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-183074","number":"183074","sourceNumber":"183074","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A toracostomia com drenagem fechada do espaço pleural, sob selo d?agua, não é\nefetiva no tratamento de qual das patologias citadas a seguir?","options":{"A":"Pneumotórax traumático.","B":"Hemotórax traumático simples.","C":"Pneumotórax simples.","D":"Empiema pleural com encarceramento pulmonar (fase III)."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-183096","number":"183096","sourceNumber":"183096","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente de 50 anos, masculino, branco, foi admitido no hospital com queixa de dor\ntorácica em hemitórax esquerdo e febre há 10 dias. Ao exame clínico, apresentava-se em bom\nestado geral. Temperatura axilar 38,6°C. Mucosas levemente descoradas. Exame físico\napresentando murmúrio vesicular diminuído no hemitórax esquerdo. Hemograma leucocitose com\ndesvio para esquerda. Na radiografia de tórax, derrame pleural septado na região posterior do\nhemitórax esquerdo. Qual é a principal hipótese diagnóstica para o caso?","options":{"A":"Infecção de vias aéreas superiores.","B":"Pneumonia.","C":"Empiema pleural.","D":"Pneumotórax."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-161191","number":"161191","sourceNumber":"161191","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente acamado por sequela de Acidente Vascular Cerebral evolui com dispneia e\ntosse purulenta. Sua radiografia demonstra condensação basal direita do pulmão. Esse achado\ntípico deve-se:","options":{"A":"A sequela do AVC.","B":"A anatomia.","C":"O agente etiológico.","D":"À dificuldades de locomoção."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-158806","number":"158806","sourceNumber":"158806","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente, 67 anos, iniciou quadro de tosse produtiva e febre há 5 dias. Durante\navaliação na emergência observou-se na\nausculta crepitações nas bases pulmonares, PA = 85 x 50\nmmHg, FR 32 ipm, saturação 88%, ureia 65 mg/dL, creatinina 1,03 mg/dL. Radiografia de tórax\nevidencia infiltrados multilobulares. Diante do caso, qual a alternativa CORRETA?","options":{"A":"O paciente deverá receber tratamento ambulatorial com macrolídeo.","B":"O paciente deverá ser internado em enfermaria com beta-lactâmico venoso.","C":"Nesse caso, deve ser considerado tratamento hospitalar em enfermaria, com quinolona ou\nbeta-lactâmico e macrolídeo.","D":"Internar em unidade de terapia intensiva, solicitar coleta de culturas, hemograma, glicemia,\neletrólitos e transaminases. Iniciar beta-lactâmico associado à quinolona ou macrolídeo.","E":"O paciente apresenta risco de mortalidade de 9,2%, com indicação de tratamento no domicilio,\ndevendo ser assegurada a possibilidade de reavaliação do tratamento em caso de piora clínica."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-161321","number":"161321","sourceNumber":"161321","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Jovem de 23 anos de idade procurou o hospital com febre, tosse produtiva purulenta há\ndois dias. Seu exame físico demonstrava estertores do lado direito do tórax. Radiografia\ndemonstrava importante bronca pneumonia. Foi optado por antimicrobiano oral e reavaliação em 24\nhoras. O tratamento proposto foi com Quinolona Respiratória, que:","options":{"A":"Não atua bem contra patógenos sem parede celular.","B":"Não atua bem contra bactérias produtoras de betalactamase.","C":"Atua de maneira a destruir a parede celular bacteriana primordialmente.","D":"Atua por interação com DNA bacteriano."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-161129","number":"161129","sourceNumber":"161129","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O choque séptico frio pode ser reconhecido nas crianças por:","options":{"A":"Má perfusão periférica com enchimento capilar lento (superior a dois segundos).","B":"Rubor de extremidades.","C":"Enchimento capilar rápido (inferior a dois segundos).","D":"Pulsos cheios ou oscilantes."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-161131","number":"161131","sourceNumber":"161131","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Assinale a alternativa CORRETA quanto aos medicamentos vasoativos.","options":{"A":"Em condições normais, a vasopressina não participa de homeostase cardiovascular.","B":"A adrenalina não oferece efeito inotrópico.","C":"A noradrenalina não age em receptores beta 2.","D":"O nitroprussiato é um fármaco inotrópico."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-161135","number":"161135","sourceNumber":"161135","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Considerando os medicamentos vasopressores, aponte a alternativa INCORRETA.","options":{"A":"Quando comparada com a noradrenalina, a dopamina foi capaz de melhorar o débito urinário e\nmostrou ausência de efeitos deletérios sobre a circulação esplâncnica.","B":"Pacientes que apresentam baixa resistência vascular sistêmica e baixo débito cardíaco podem\nse beneficiar da associação de noradrenalina com\ndobutamina.","C":"A administração exógena de vasopressina em pacientes com diagnóstico de choque séptico\nproduz aumento da pressão arterial e melhora da diurese.","D":"Em pacientes que não estão gravemente doentes, a vasopressina exógena não exerce atividade\npressora."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-161139","number":"161139","sourceNumber":"161139","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Os objetivos terapêuticos no tratamento do choque séptico, principalmente após a\nprimeira hora (golden hour), são os seguintes, com EXCEÇÃO de:","options":{"A":"Pulsos normais.","B":"Extremidades quentes.","C":"Débito urinário superior a 1 ml/kg/h.","D":"Tempo de enchimento capilar de até 4 segundos."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-158779","number":"158779","sourceNumber":"158779","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"No manuseio de neonato de mãe com tuberculose, é correto afirmar:","options":{"A":"Em casos de mães com qualquer tuberculose cuja infectividade não pode ser afastada e sem\ncondições de afastamento dos recém-nascidos, deve ser mantida a amamentação com máscara,\niniciado ou continuado tratamento materno, iniciado isoniazida por três meses para o neonato e, em\nseguida, realizado teste tuberculínico.","B":"Em casos de mães com tuberculose extrapulmonar ou pulmonar não tratada (considerada\nbacilífera), devem ser mantidos os neonatos junto à\nmãe e, somente após o teste tuberculínico,\niniciado isoniazida.","C":"Em casos de mães com diagnóstico recente de tuberculose, com doença mínima não tratada ou\ntratamento de menos de duas semanas, mas não bacilífera, não há risco para o recém-nascido.","D":"Em casos de mãe com tratamento completo e adequado, pela remota possibilidade de haver\nexacerbação na gestação, não deve ser realizado teste tuberculínico no neonato.","E":"Em casos de mães apenas com teste tuberculínico positivo, Rx normal, não bacilífera e sem\ndoença ativa, deverá ser realizado teste\ntuberculínico também no neonato."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-161145","number":"161145","sourceNumber":"161145","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Assinale a alternativa em que a afirmativa esteja INCORRETA.","options":{"A":"Os sinais clínicos mais típicos de sepse são precoces, principalmente em crianças.","B":"Os sinais e sintomas de sepse não são específicos e, algumas vezes, levam a erros de\ndiagnóstico.","C":"O atraso no diagnóstico de sepse associa-se à manutenção, à demora na retirada e a uma maior\nutilização de antibióticos.","D":"Os critérios diagnósticos de SIRS são muito sensíveis."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-134838","number":"134838","sourceNumber":"134838","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Indique a alternativa que apresente as características do acometimento por\nTuberculose, no Sistema Nervoso Central.","options":{"A":"Preferência por base de crânio, baixos níveis de glicose no liquor e aumento da proteína\nliquórica.","B":"Preferência por base de crânio, elevados níveis de glicose no liquor e redução da proteína\nliquórica.","C":"Xantocromia e sangramentos.","D":"Sangramentos com hemácias crenadas e redução da proteína liquórica."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-134332","number":"134332","sourceNumber":"134332","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente com HIV, evoluindo com deterioração neurológica, realiza tomografia de\ncrânio, que não contraindica punção lombar. Ao realizar punção lombar, é então diagnosticada\nmeningite por tuberculose. Para esse diagnóstico, o liquor NÃO tem como característica:","options":{"A":"A formação de retículo sobrenadante.","B":"A glicose de 50 mg/dl.","C":"O aspecto opaco.","D":"A presença de células brancas."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-134868","number":"134868","sourceNumber":"134868","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em relação ao tratamento da infecção latente em comunicantes de casos de\ntuberculose pulmonar, é CORRETO afirmar que:","options":{"A":"Deve ser instituído em todos os comunicantes; a droga de escolha é a isoniazida e o tempo de\ntratamento é de três meses.","B":"Deve ser instituído em menores de 13 anos sem antecedente de vacina BCG; a droga de\nescolha é a rifampicina e o tempo de tratamento é de seis meses.","C":"Não deve ser instituído em adultos independentemente do resultado da prova tuberculínica.","D":"Poderá ser instituída em comunicantes na dependência do resultado da prova tuberculínica; a\ndroga de escolha é a isoniazida e o tempo de tratamento é 270 doses que deverão ser tomadas de\n9 a 12 meses."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-110599","number":"110599","sourceNumber":"110599","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Pré-escolar de cinco anos de idade, assintomático, foi levado ao ambulatório com\ndiagnóstico de AIDS firmado há dois meses\ndurante internação hospitalar por pneumonia. Além de\numa radiografia de tórax normal realizada há uma semana e do cartão da criança atualizado, a mãe\nmostrou resultado de teste de PPD reator forte feito no seu filho há um ano. Segundo o manual\nde controle e tratamento da Tuberculose no Brasil, a conduta mais adequada seria:","options":{"A":"Quimioprofilaxia.","B":"Esquema tríplice.","C":"Observação clínica.","D":"Repetir o teste PPD.","E":"Revacinação com BCG."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-86811","number":"86811","sourceNumber":"86811","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Adulta, 41 anos, HIV-negativa, contato domiciliar de paciente com TB pulmonar\nbacilífera. Encontra-se assintomática, pesando 52Kg,\napresenta PPD de 13 mm, radiografia de\ntórax normal e cicatriz de BCG presente. Qual a melhor conduta para a paciente acima?","options":{"A":"Solicitar cultura de escarro para BAAR;","B":"Repetir o PPD dentro de 03 meses;","C":"Iniciar Esquema Básico;","D":"Prescrever Isoniazida 300 mg/dia por 06 meses;","E":"Prescrever Etambutol 1200 mg/dia por 06 meses."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-158390","number":"158390","sourceNumber":"158390","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Quais as drogas que compõem a primeira fase do Esquema básico do tratamento da\ntuberculose pulmonar em adultos?","options":{"A":"Rifampicina + isoniazida.","B":"Rifampicina + Isoniazida + Pirazinamida + Etambutol.","C":"Rifampicina + Claritromicina + Etambutol.","D":"Rifampicina + Isoniazida + Estreptomicina.","E":"Rifampicina + Isoniazida + Etambutol."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-158387","number":"158387","sourceNumber":"158387","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Feminino, 19 anos, está internada há 11 dias por fratura de tíbia esquerda, após\nacidente automobilístico. Em uso de ciprofloxacino\nEV + clindamicina EV. Está evoluindo, há 2 dias,\ncom febre e sudorese. Ao exame, apresenta-se sonolenta, extremidades sudoreicas, hipocorada e\nhipo-hidratada. Temperatura axilar de 38,4°C; pressão arterial = 76 x 42 mmHg; frequência\ncardíaca = 128 bpm; frequência respiratória = 32 irpm; saturação arterial de oxigênio = 96%. Ferida\noperatória com áreas de necrose e secreção piogênica em membro inferior esquerdo. Qual deve\nser a conduta imediata?","options":{"A":"Encaminhar para o centro cirúrgico para a realização de amputação de membro inferior\nesquerdo.","B":"Desbridamento de ferida operatória.","C":"Realização de tomografia de crânio.","D":"Início de noradrenalina EV + desbridamento + encaminhamento à UTI.","E":"Hidratação EV + coleta de culturas + ampliação de esquema antimicrobiano + encaminhamento\nà UTI."},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-108581","number":"108581","sourceNumber":"108581","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O esquema básico para tuberculose que compreende 2RHZE/4RH está indicado:","options":{"A":"Para todos os casos novos de todas as formas de TB pulmonar e extrapulmonar (exceto\nmeningoencefalite), bem como para todos os casos de recidiva e retorno após abandono;","B":"Apenas para tuberculose pulmonar primária;","C":"Para os casos de meningoencefalite;","D":"Para os casos de retorno após abandono;","E":"NDA."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-13155","number":"13155","sourceNumber":"13155","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Escolar com 7 anos de idade, há uma semana iniciou tratamento para tuberculose\npulmonar com isoniazida, rifampicina e\npirazinamida. Há 2 dias vem apresentando dor epigástrica e\nvômitos, sem melhora com antieméticos. Ao exame físico, a criança anictérica e sem alterações de\npropedêutica abdominal. Os exames complementares mostraram transaminases normais. A\nconduta adequada é:","options":{"A":"Suspender a pirazinamida.","B":"Suspender a isoniazida.","C":"Suspender as três drogas por 24 horas e reintroduzi-las junto às refeições.","D":"Substituir a pirazinamida por etambutol.","E":"Substituir a isoniazida por etambutol e estreptomicina."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-362418","number":"362418","sourceNumber":"362418","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente de 38 anos, do sexo masculino relata febre, odinofagia tontura e mialgia há 2\ndias. Está em tratamento de LMA há 7 dias. Sem outras comorbidades. Sinais vitais: PA 70x50\nmmHg, FC: 128 bpm, FR: 26rpm, TAx: 36,1ºC, satO2: 98% ar ambiente. Exame físico: enantema\ndifuso em pilares amigdalianos sem abscessos com raras placas esbranquiçadas em área lateral\nda língua. Esplenomegalia não dolorosa. Exames complementares em andamento. Iniciada\nressuscitação volêmica com ringer 1000ml. A conduta imediata é:","options":{"A":"Cefepime e fluconazol.","B":"Meropenem e vancomicina.","C":"Aguardar resultado da hemocultura.","D":"Paciente sem critérios para antibioticoterapia."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-362472","number":"362472","sourceNumber":"362472","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Marta tem 39 anos e há 5 dias iniciou quadro de febre alta, associada a dor em\nhemitórax direito e tosse produtiva. Ao exame\nfísico encontra-se consciente e orientada no tempo e\nno espaço. Apresenta frêmito toracovocal aumentado em base direita e ausculta de crepitações\nfinas em terço inferior de hemitórax direito. FC 85 bpm. FR 19 irpm. Pressão arterial 110x80 mmHg\ne Sp02 96% a.a. Radiografia de tórax evidenciando opacidades acinares em lobo inferior direito\ncom presença de broncograma aéreo. Paciente sem comorbidades clínicas conhecidas.\n\nLaboratório: Ureia 22, Leucócitos 16563 com 85% de segmentados. Qual a conduta mais\napropriada para o caso?","options":{"A":"Solicito hemocultura em 2 sítios, início fase rápida com cristalóide, início antibioticoterapia\nde\namplo espectro enquanto aguardo resultado de hemocultura.","B":"Início empiricamente tratamento para tuberculose pulmonar com esquema básico de acordo com\no peso e solicito exame de escarro para\nposterior confirmação diagnóstica.","C":"Início betalactâmico oral para tratamento ambulatorial, orientado a procurar novamente\natendimento médico caso a febre não ceda em até 72 horas.","D":"Solicito internação hospitalar, prescrevo quinolona respiratória endovenosa associada a\ncorticoide oral."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-362429","number":"362429","sourceNumber":"362429","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Gestante adquiriu tuberculose pulmonar durante a gestação. Persiste bacilífera mesmo\napós o nascimento do bebê. Em relação ao\nrecém-nascido dessa mãe, é CORRETO afirmar que:","options":{"A":"Deve-se realizar vacina da BCG e contraindicar o aleitamento materno.","B":"Não há risco de tuberculose congênita, e o aleitamento materno está contraindicado até a mãe\nnão ser mais bacilífera.","C":"A vacina da BCG está indicada ao nascimento, não sendo necessária a quimioprofilaxia.","D":"Deve-se iniciar quimioprofilaxia com isoniazida ou rifampicina e, após 3 meses, se teste\ntuberculínico for negativo, vacinar com BCG."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-362455","number":"362455","sourceNumber":"362455","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"J.B.S, 23 anos iniciou o tratamento com esquema básico para tuberculose pulmonar\nconfirmada por meio do teste rápido\nmolecular (TRM-TB) há 7 dias. A enfermeira da equipe de\nsaúde solicitou que os contatos de J.B.S. viessem até a UBS para serem avaliados. Dentre os\ncontatos intradomiciliares está L.B.S, irmã de J.B.S, de 17 anos, que está com 11 semanas de uma\ngestação sem intercorrências até aqui. L.B.S demonstrou bastante preocupação quanto a\nmanifestar a doença do irmão, embora não tenha nenhum sintoma respiratório no momento.\n\nPosteriormente, a mesma retorna com o exame de PPD que acusa o resultado de 5mm. Diante\ndesse resultado, a enfermeira da equipe deve:","options":{"A":"Solicitar radiografia de tórax e TRM-TB para excluir tuberculose ativa.","B":"Iniciar tratamento para infecção latente da tuberculose com o esquema 3HP (Rifapentina 150mg\n\n(P) e Isoniazida (H) 300mg) em doses semanais durante 3 meses.","C":"Postergar tratamento infecção da latente da tuberculose para 13 semanas de gestação.","D":"Postergar tratamento da infecção latente da tuberculose para após o parto."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-362448","number":"362448","sourceNumber":"362448","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A cidade de Manaus tem sofrido, nos últimos meses, efeitos do fenômeno \"El Niño\". A\nescassez de chuvas e o tempo seco tem\nfavorecido a proliferação de queimadas, estando a cidade\ncoberta de fumaça durante vários dias. Este fenômeno climático tem intensificado a ocorrência de\nproblemas respiratórios, como a tosse. Em uma manhã de atendimento em sua UBS você atendeu\nvários pacientes com queixa de tosse, listados nas alternativas abaixo, entretanto apenas UM\ndestes pacientes possui tosse com SINAL DE ALERTA para causas subjacentes de maior\ngravidade que deve ser encaminhado ao especialista focal para cuidado compartilhado. Qual?","options":{"A":"Paciente com tosse há três dias associada a coriza.","B":"Paciente com tosse seca persistente, com sensação de bola na garganta e \"\"queimação no\nestômago\"\", sem perda ponderal.","C":"Paciente tabagista, apresentando tosse produtiva com secreção purulenta e síndrome\nconsumptiva.","D":"Paciente com tosse seca após início do uso de enalapril para HAS."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-327233","number":"327233","sourceNumber":"327233","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Maurício tem 37 anos, é um paciente com transtorno de adição por substâncias ilícitas,\nconsome cocaína e inala crack. Adoeceu por tuberculose pulmonar confirmada por exame de\nescarro e imagem 2 anos atrás, entretanto abandonou o tratamento ainda no quarto mês. A equipe\nde saúde não conseguiu contato na busca ativa na época do abandono e agora retorna com queixa\nde tosse produtiva, perda ponderal, febre vespertina e astenia. Qual das alternativas a seguir\ndiscrimina a conduta mais apropriada para Maurício nesse momento?","options":{"A":"Solicito TRM-TB pois já avalia se há resistência a rifampicina e radiografia de tórax em PA e\nperfil.","B":"Reinicio tratamento, prescrevendo RH por mais 3 meses para completar os 2 meses de\ntratamento faltantes, com dose ajustada de acordo com o peso atual.","C":"Por tratar-se de abandono, encaminho o paciente para internação em uma unidade terciária com\nisolamento respiratório. Pela alta probabilidade de tratar- se de tuberculose multirresistente.","D":"Solicito radiografia de tórax em PA e perfil, baciloscopia do escarro e cultura para\nmicobactérias\nno escarro com tipificação e teste de\nsensibilidade, pois o abandono pode ter gerado alguma\nresistência. Se a baciloscopia vier positiva inicio tratamento com RHZE e aguardo resultado da\ncultura."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-327234","number":"327234","sourceNumber":"327234","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Você está atendendo Cleide no serviço de emergência, ela tem 23 anos e vem trazida\npela mãe, a qual relata que Cleide iniciou um\nquadro de dor em região de arcos costais à direita, há\n3 dias, associada a febre e tosse produtiva com expectoração mucopurulenta. Ao exame físico\nencontra-se desorientada no tempo e no espaço, taquidispneica (fr 35 irpm) e taquicardica, com fc\n124irpm. PA 100x70mmhg. Presença de estertores crepitantes em terço inferior de pulmão direito.\nFTV aumentado a direita. Exames laboratoriais revelam ureia de 100. Leucócitos 23.000 com\nbastões 10% e PCR 125. A seguir segue a imagem da radiografia de tórax realizada nesse\natendimento. Considerando história clínica, tempo de evolução, achados no exame físico e em\nexames complementares, qual o diagnóstico da paciente, onde o tratamento deve ser realizado e\nqual a proposta terapeutica inicial?","options":{"A":"Pneumonia adquirida na comunidade, classifico como grave avaliando pelo escore CURB-65,\ndecidindo então pela internação hospitalar.\nInicio antibioticoterapia com Betalactamico associado a\nMacrolídeos ou Quinolona respiratória, mantenho monitorização inicial pelos sinais de gravidade da\npaciente.","B":"Tuberculose pulmonar. Inicio esquema com COXIP empiricamente pela gravidade em paralelo a\ncoleta de exames de escarro. Mantenho em observação por 24 horas para avaliar se evolui com\nestabilidade clínica com início do tratamento. Na alta direciono para UBS e solicito que seja\nreavaliada mensalmente com novo exame de escarro.","C":"Derrame Pleural. Mantenho a paciente em internação hospitalar e realizo Toracocentese\ndiagnóstica para avaliar se é um Transudato ou\nExsudato direcionando de forma mais apropriada a\ninvestigação e o tratamento. Pela alta probabilidade de tratar-se de TB Pleural (por Manaus ser\nárea endêmica), inicio COXIP enquanto aguardo resultados da análise do líquido pleural.","D":"Paciente com quadro sugestivo de pneumonia adquirida na comunidade. Em decorrência da\navaliação guiada pelo CURB 65bpm, deve ser tratada ambulatorialmente, com prescrição\nBetalactamico associado a Macrolídeos ou Quinolona respiratória para uso oral, orientando retorno\nem 48 horas em caso de persistência de febre ou piora clínica."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-298205","number":"298205","sourceNumber":"298205","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"H.T.S., 33 anos, procedente de Itacoatiara, católico, ensino médio completo, pedreiro,\ncasado, com 2 filhos. Relata que se\nencontrava em bom estado de saúde até 5 semanas atrás,\nquando começou a apresentar quadro de tosse produtiva com expectoração amarelada. Há cerca\nde 2 semanas houve piora do quadro, evoluindo com febre vespertina, astenia e a tosse evoluiu\ncom hemoptoicos. Observou ainda que perdeu 5 kg no período. Relata contato com tuberculose há\ncerca de 3 anos atrás (irmã). Nega doenças crônicas, nega etilismo, nega tabagismo. Você solicita\nradiografia de tórax em PA e perfil e baciloscopia do escarro em 2 amostras para investigação\ndiagnóstica. O paciente retorna uma semana depois com a radiografia de tórax evidenciando\nopacidades acinares heterogêneas em lobo superior direito e baciloscopia do escarro positiva\n(2+/4+). Qual a conduta mais apropriada em relação aos contatos desse paciente?","options":{"A":"Solicitar que todos venham à unidade, avaliar a presença de sintomas sugestivos de\ntuberculose, investigando os sintomáticos com\nradiografia de tórax em PA e perfil e baciloscopia do\nescarro em 2 amostras. Os assintomáticos com menos de 10 anos devem ser investigados com\nrealização de PPD e radiografia de tórax em PA e perfil e os maiores de 10 anos com PPD.","B":"Solicitar que venham à unidade apenas os contatos que estiverem apresentando algum sintoma\nrespiratório, investigando com baciloscopia do escarro em 2 amostras.","C":"Solicitar que todos venham à unidade e investigar apenas os sintomáticos com radiografia de\ntórax em PA e perfil e baciloscopia do escarro em 2 amostras.","D":"Tratar imediatamente os sintomáticos respiratórios, pois não há necessidade de investigação\ncom exames quando já há um doente confirmado na\ncasa."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-298275","number":"298275","sourceNumber":"298275","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A tuberculose pulmonar é uma condição de saúde pública que deve ser conduzida na\nAtenção Primária à Saúde de forma resolutiva e, para isso, o médico deve conhecer alguns\nmétodos diagnósticos da doença. Normalmente são utilizadas a baciloscopia de escarro, o teste\nrápido molecular para TB com teste de sensibilidade à rifampicina e a cultura. Sobre métodos\ndiagnósticos e de seguimento de tuberculose pulmonar, considere as afirmativas a seguir e\nassinale a CORRETA:","options":{"A":"A baciloscopia do escarro em duas amostras é o padrão-ouro para o diagnóstico de tuberculose\npulmonar.","B":"O teste rápido molecular para M. tuberculosis é indicado para o 9 seguimento terapêutico mensal\nde controle do tratamento.","C":"Dada a dificuldade em se obter uma amostra adequada de escarro em crianças, deve-se\nsolicitar cultura do material obtido quando o\nmesmo for coletado para a realização de teste rápido\nmolecular para M. tuberculosis.","D":"Casos suspeitos de falência do tratamento com esquema básico dispensam a realização do\nteste de sensibilidade à rifampicina."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-286775","number":"286775","sourceNumber":"286775","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um paciente de 7 anos, recebeu BCG ao nascer, é contactante intradomiciliar de\ntuberculoso bacilífero, apresenta-se assintomático, Rx de tórax normal e prova tuberculínica de 8\nmm, deve receber a orientação de:","options":{"A":"Repetir o PPD em 8 semanas","B":"Realizar lavado gástrico","C":"Tratar infecção latente","D":"Revacinar"},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-286776","number":"286776","sourceNumber":"286776","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Logo após o parto, a parturiente informa que o marido acabou de fazer diagnóstico de\nTB pulmonar bacilífera. Nesse caso, a conduta\nCORRETA é:","options":{"A":"Suspender a amamentação.","B":"Iniciar isoniazida logo ao nascimento.","C":"Iniciar esquema RIP logo ao nascimento.","D":"Realizar lavado gástrico, RX tórax e realizar BCG."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-256580","number":"256580","sourceNumber":"256580","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Adolescente de 13 anos é encaminhado por tosse produtiva, febre e perda de peso há\n2 meses. Mãe com tuberculose bacilífera em\ntratamento há 10 dias. Ao exame, encontra-se\nemagrecido e apresenta estertoração grossa esparsa em campos pleuropulmonares. Prova\ntuberculínica não reatora; radiografia de tórax com infiltrado peri-hilar, bacterioscopia de escarro\ncom BAAR positivo. De acordo com as diretrizes para tratamento da tuberculose no Brasil, o\nesquema terapêutico e o tempo de tratamento preconizado para o caso é:","options":{"A":"Rifampicina (6 meses), isoniazida (6 meses), pirazinamida (2 meses) e etambutol (2 meses).","B":"Rifampicina (6 meses), isoniazida (6 meses) e pirazinamida (2 meses).","C":"Rifampicina (4 meses), estreptomicina (2 meses), isoniazida (6 meses) e pirazinamida (2\nmeses).","D":"Rifampicina (4 meses), isoniazida (6 meses), pirimetamina (6 meses) e etambutol (2 meses)."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-252222","number":"252222","sourceNumber":"252222","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A pneumonia nosocomial ou adquirida no hospital (PAH) é a segunda infecção\nhospitalar mais comum, com alta\nmorbimortalidade. Quanto ao assunto, assinale a alternativa\nCORRETA:","options":{"A":"Febre, leucocitose e secreção purulenta são suficientes para o diagnóstico.","B":"A disseminação hematogênica e a translocação de bactérias do trato digestivo são as principais\nvias para seu desenvolvimento.","C":"A tomografia de tórax é imprescindível como exame complementar.","D":"É a pneumonia que ocorre pelo menos após 48 horas de internação (em média 5 a 7 dias)."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-252306","number":"252306","sourceNumber":"252306","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Rui, 45 anos, tem tosse há 2 meses e perdeu 7 kg nesse período. Veio para consulta\nmédica na UBS entregar o resultado do\nBAAR, que foi positivo. Você inicia o tratamento e pergunta\nsobre os seus contactantes. Rui mora com a esposa Patrícia, de 38 anos. Você agenda então\nconsulta para Patrícia. Durante a consulta, Patrícia encontra-se assintomática e tem ausculta\nnormal. Você deve, num primeiro momento para Patrícia:","options":{"A":"Solicitar BAAR.","B":"Solicitar Prova tuberculínica (PT).","C":"Solicitar Raio X de tórax.","D":"Iniciar tratamento para Infecção latente pelo M. tuberculosis (ILTB)."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-208391","number":"208391","sourceNumber":"208391","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Como se apresenta a análise do líquido cefalorraquidiano compatível com\nneurotuberculose?","options":{"A":"Pleocitose com predomínio de linfomononucleares; concentrações de proteína e glicose normais.","B":"Pleocitose com predomínio de linfomononucleares; elevação da concentração de proteínas e\nredução da glicose.","C":"Pleocitose com predomínio de neutrófilos; redução da concentração de proteína e redução da\nglicose.","D":"Pleocitose com predomínio de neutrófilos; concentrações de proteína e glicose normais."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-176050","number":"176050","sourceNumber":"176050","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente do sexo feminino, 45 anos, foi admitida na emergência com relato de há cinco\ndias apresentar febre alta, calafrios, tosse e dor torácica direita. Apresentava diante do exame\nclínico e radiológico, características de síndrome de derrame pleural direita, com derrame\nvolumoso. Foi submetida à toracocentese que evidenciou aspecto serofibrinoso, presença de\npolimorfonucleares com predomínio de neutrófilos, proteína do líquido pleural de 4,5 g/dl; LDH =\n\n1.020 U/L; pH = 7,9; glicose de 40 mg/dl. Qual o diagnóstico mais provável e a conduta mais\nacertada no momento?","options":{"A":"Tuberculose ? iniciar RIP.","B":"Artrite reumatoide ? iniciar corticoide.","C":"Empiema ? drenagem fechada em selo d'água imediata.","D":"Pneumonia comunitária ? somente antibioticoterapia."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-176073","number":"176073","sourceNumber":"176073","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"De acordo com o Plano nacional de Controle da Tuberculose (PNCT), o objetivo do\ncomponente da vigilância epidemiológica da tuberculose é monitorar a situação e a tendência da\ndoença para recomendar, executar e avaliar as atividades de controle. Qual das seguintes ações\nnão se enquadra nesses objetivos?","options":{"A":"Reforçar a investigação de casos como uma ação de acolhimento, atitude que deve perpassar\npor toda a equipe.","B":"Intensificar a identificação de sintomáticos respiratórios, examiná-los com baciloscopia e\nimplementar o registro dos mesmos na rede laboratorial do SUS.","C":"Monitorar os eventos adversos temporalmente associados à vacina BCG, em conjunto com os\ntécnicos do PNI municipal/estadual/regional.","D":"Implantar a procura de sintomáticos respiratórios nos ambulatórios de hospitais e emergências\ndos grandes centros urbanos e criar facilidades\npara examiná-los."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-176056","number":"176056","sourceNumber":"176056","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Kuriatã, indígena, um ano de idade, está há 2 dias apresentando febre de início súbito,\nnão aferida, tosse seca, coriza e obstrução\nnasal. Há 24h, evoluiu com dispneia e saturação de\noxigênio de 93% em ar ambiente. Qual a conduta recomendada, com base no organograma do\nMinistério da Saúde, para Síndrome Respiratória Aguda Grave (SRAG)?","options":{"A":"Iniciar antiviral, antibiótico, hidratação venosa, oxigenoterapia sob monitorização e solicitar\nexames laboratoriais e radiológicos.","B":"Iniciar antiviral, hidratação venosa, oxigenoterapia sob monitorização e solicitar exames\nlaboratoriais e radiológicos.","C":"Iniciar antibiótico, hidratação venosa, oxigenoterapia sob monitorização e solicitar exames\nlaboratoriais e radiológicos.","D":"Iniciar hidratação venosa, oxigenoterapia sob monitorização e solicitar exames laboratoriais e\nradiológicos."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-152028","number":"152028","sourceNumber":"152028","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A tuberculose apresenta taxa de incidência ainda muito elevada em nosso Estado (66,7\nno Amazonas, enquanto no Brasil é de 33,8 ?\ndados de 2014, Boletim Epidemiológico nº 13 ? 2016,\nMinistério da Saúde, disponível em www.saude.gov.br). No ano de 2014, foi aprovada, pela\nAssembleia Mundial de Saúde, a Estratégia pelo Fim da Tuberculose, com objetivo de um mundo\nlivre desta doença e que se propõe a traçar estratégias para o fim da epidemia global da doença.\n\nEm relação a esta enfermidade e as estratégias desenvolvidas para seu controle, NÃO podemos\nafirmar que:","options":{"A":"Enfatiza a necessidade de realização de cultura do escarro e teste de sensibilidade,\nprincipalmente nos casos de retratamento onde há\nmaior risco de resistência aos fármacos e nos\ncasos de baciloscopia positiva ao final do 2º mês de tratamento.","B":"Dentre as metas do programa estão a redução dos coeficientes de incidência (< 10 casos por\n100.000 habitantes) e de mortalidade (95%) da doença até 2035. Esta redução representa, para a\nOrganização Mundial da Saúde, o fim da tuberculose como problema de saúde pública.","C":"Seus indicadores epidemiológicos (coeficiente de incidência, coeficiente de mortalidade,\nproporção de casos de retratamento, proporção\nde cura, proporção de multirresistência, dentre\noutros) refletem a qualidade dos serviços prestados, servindo de apoio para tomada/mudança de\ndecisões.","D":"No Brasil, o esquema padronizado para tratamento desta doença é com 4 drogas (rifampicina,\nisoniazida, pirazinamida e etambutol), priorizando o tratamento diretamente observado (quando o\npaciente toma as medicações quinzenalmente no centro de saúde) e por no mínimo 9 meses."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-151975","number":"151975","sourceNumber":"151975","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Sobre tuberculose é CORRETO afirrmar:","options":{"A":"A amamentação é contraindicada em pacientes que estejam em tratamento de tuberculose.","B":"A tuberculose na criança (menores de 10 anos) costuma ser bacilífera, assim como no adulto.","C":"Quando a reação adversa corresponde a uma reação de hipersensibilidade grave como\nplaquetopenia, anemia hemolítica, insuficiência renal etc, o medicamento suspeito pode ser\nreiniciado após a suspensão.","D":"Os casos bacilíferos são a principal fonte de disseminação da doença, a descoberta precoce por\nmeio da busca ativa do sintomático respiratório é importante medida para interromper a cadeia de\ntransmissão, desde que acompanhada pelo tratamento oportuno."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-139130","number":"139130","sourceNumber":"139130","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"João, de 63 anos, foi recentemente diagnosticado com Tuberculose pleural. Ele é\ndiabético e vive com a esposa e seus 7 filhos, 4 noras e 5 netos (um deles de apenas 1 ano de\nidade), numa área carente da cidade de Manaus. Em relação a este caso, podemos afirmar:","options":{"A":"João deve ser tratado com o esquema básico (rifampicina, isoniazida, pirazinamida e etambutol)\nnos dois primeiros meses (fase intensiva).","B":"Todos os seus familiares intra-domiciliares (17 pessoas) devem ser avaliados e investigados\npara possível infecção por M.tuberculosis\natravés da pesquisa de BAAR no escarro, duas amostras.","C":"Os familiares que sejam sintomático-respiratório devem receber a quimioprofilaxia para\ntuberculose, independente da idade e esquema vacinal prévio.","D":"O acompanhamento de João deve ser feito inteiramente na atenção primária à saúde durante os\nseis meses de tratamento recomendado e com testes mensais para pesquisa de M.tuberculosis."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-139146","number":"139146","sourceNumber":"139146","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em 2006, a Organização Mundial da Saúde lançou a estratégia Stop-TB/OMS visando\nalcançar algumas metas em relação ao controle da Tuberculose. Sobre esta estratégia, podemos\nafirmar:","options":{"A":"Os pacientes que estejam fazendo o TDO devem usar um esquema especial de drogas contra a\ntuverculose e não o esquema Coxip.","B":"Busca a expansão e aperfeiçoamento da estratégia TDO (tratamento diretamente observado).","C":"Recomenda-se a observação pela equipe de saúde da tomada da medicação uma vez por\nsemana.","D":"O TDO pode ser feito em domicílio pelo agente comunitário de saúde ou familiar do paciente\ncom a mesma eficácia terapêutica e para\nnotificação."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-129753","number":"129753","sourceNumber":"129753","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em relação à vacina BCG, podemos afirmar que:","options":{"A":"Pode ser feita em qualquer idade, mesmo em crianças HIV-positivas sintomáticas e filhos de\nmães HIV-positivas.","B":"A via de administração é subcutânea e a evolução da reação vacinal ocorre em até 6 meses,\nnão sendo recomendado revacinação na ausência\nde cicatriz após os seis meses.","C":"É uma vacina atenuada do Mycobacterium bovis que destina-se a prevenir as formas graves de\ntuberculose e cuja aplicação deve ser feita ainda na maternidade.","D":"Os contactantes intradomiciliares de portadores de hanseníase devem receber mais duas doses\nda vacina BCG, se menores de um ano de idade,\ne com esquema vacinal comprovadamente\ncompleto."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-129758","number":"129758","sourceNumber":"129758","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Quanto ao controle de contatos de pacientes com tuberculose, podemos afirmar:","options":{"A":"Tem como objetivo o diagnóstico tardio de formas graves de tuberculose não pulmonar.","B":"Todos os contatos peri-domiciliares do caso índice devem ser avaliados caso o paciente não\nseja bacilífero.","C":"É recomendada quimioprofilaxia secundária a todo recém-nascido contactante de paciente\nbacilífero após vacinação com BCG.","D":"Esta ação é fundamentalmente executada pela atenção básica de saúde."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-107890","number":"107890","sourceNumber":"107890","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Marque V (Verdadeiro) ou F (Falso) sobre tuberculose: ( ) Quando a equipe de saúde\nda família tem uma criança diagnosticada com\ntuberculose, deverá buscar o possível caso-fonte,\nexaminando todos os contatos adultos. ( ) As crianças, quando são contatos de tuberculose, devem\ntambém fazer o tratamento e imediatamente ser vacinadas com BCG se tiverem de 0 a 4 anos. ( )\nNo adulto sintomático com exame de escarro positivo, a conduta inicial é orientação e, caso positivo\no RX sugestivo de tuberculose, se inicia o tratamento. ( ) Nas grávidas a quimioprofilaxia da\ntuberculose deve ser adiada para após o parto. Marque a alternativa CORRETA:","options":{"A":"V - V - F - F.","B":"F - F - V - V.","C":"V - F - F - V.","D":"F - V - V - F."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-80998","number":"80998","sourceNumber":"80998","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente do sexo F. 23 anos, queixa-se de astenia, inapetência e febre vespertina há 3\nsemanas. Procurou PS devido dor torâcica em base direita ventilatônica dependente. Fez,\nradiografia de tórax que evidenciou velamento do seio costofrênico direito, sendo encaminhado ao\nambulatório de Pneumologia para investigação do Derrame Pleural. Teve contato com o pai\ntuberculose há 2 anos. Qual a sua conduta com relação a propedêutica de investigação no caso\nacima?","options":{"A":"Solicitar TT (PPD), pesquisa do BAAR no escarro e iniciar esquema básico.","B":"Solicitar biópsia de pleura e iniciar esquema bási co.","C":"Pesquisa de BAAR no líquido sinoval, sendo esta negativa, não deve ser tuberculose e não fica\nindica tratamento.","D":"Toracocentesa diagnóstica, se análise do líquido pleural revelar linfocitose = 75%, ADA\n(adenosína dearminase) = 45 U/l e o DHL (desidrogenase lática) = 200 U/l, configurando-se\nexsuadato, e deve-se iniciar esquema básico.","E":"Iniciar tratamento com claritromicina."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-61500","number":"61500","sourceNumber":"61500","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"São considerados eventos adversos menores decorrentes do uso do esquema básico\npara o Tratamento da Tuberculose:","options":{"A":"urticária e hepatite.","B":"trombocitopenia e convulsões.","C":"insuficiência renal e nistagmo.","D":"vômitos, artralgia e urina avermelhada.","E":"hepatite medicamentosa e nefrite intersticial."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-34244","number":"34244","sourceNumber":"34244","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Tuberculose (TB) representa nos dias atuais, ainda, um dos principais desafios à saúde\npública mundial. Referente à sua operacionalização no Brasil, assinale a alternativa correta:","options":{"A":"A BCG exerce notável poder protetor contra as manifestações graves da primoinfecção, como as\ndisseminações hematogênicas e a meningoencefalite, evitando também a infecção tuberculosa.","B":"Ao profissional médico, espera-se que o mesmo identifique o sintomático respiratório, que o\nexamine e que solicite os exames complementares. A visita domiciliar não é de responsabilidade\ndeste profissional.","C":"A alta por abandono de tratamento acontece quando o paciente não comparece à Unidade de\nSaúde por mais de 60 dias consecutivos, após\na data prevista para o seu retorno.","D":"Por ser considerada TB pulmonar positiva, dentre outros critérios, a mesma pode ter uma\nbaciloscopia direta positiva e imagem radiológica sugestiva de TB.","E":"O exame radiológico do tórax é útil não só para diagnosticar e fazer o diferencial de outros\nagravos pulmonares, como também é o exame padrão-ouro em diagnóstico da TB."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-26450","number":"26450","sourceNumber":"26450","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em relação aos tuberculostáticos, é correto afirmar:","options":{"A":"o aparecimento de dores articulares na vigência do tratamento de tuberculose pulmonar\ngeralmente é decorrente do etambutol","B":"o aparecimento de náuseas e vômitos no início do tratamento obriga a suspensão da hidrazida e\nrifampicina","C":"a estreptomicina pode causar perda da discriminação do verde-vermelho","D":"a hepatotoxicidade causada pela hidrazida pode ser precoce ou tardia","E":"a pirazinamida pode causar alopécia"},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-26609","number":"26609","sourceNumber":"26609","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Quando o PPD se positiva ( viragem tuberculínica ) após uma criança se infectar com\nBK?","options":{"A":"Depois 1 a 2 semanas, mas pode levar 2 anos","B":"Depois 10 dias a 15 dias , mas pode levar 1 mês","C":"Depois 10 semanas, mas pode levar 2 anos","D":"Depois de 3 a 6 semanas , mas pode levar 3 meses","E":"Depois 10 semanas, pode levar 1 ano"},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-26630","number":"26630","sourceNumber":"26630","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Referente a Tuberculose (TB), assinale a INCORRETA :","options":{"A":"Pacientes que apresentam imagem radiológica compatível com TB pulmonar, por mais suspeita\nque seja, não devem iniciar a quimioterapia\nantes de realizar a baciloscopia de escarro.","B":"As unidades de Saúde da Família , como unidades tipo 1, devem responsabilizar-se por executar\nas ações para o controle da tuberculose no\nmunicípio.","C":"As medidas ambientais e de proteção individual são: local separado para atendimento, ventilado\ne bem iluminado para exame do sintomático\nrespiratório: horário especial para as consultas\nregulares: uso de máscaras pelos profissionais.","D":"No diagnóstico de TB, somente na criança é aceitável o diagnóstico de TB pulmonar sem\ninvestigação de agente causal pela baciloscopia de escarro.","E":"Deve-se fazer busca de casos em todas as pessoas que apresentem tosse e expectoração por\nduas semanas ou mais, utilizando o exame radiológico de tórax como exame padrão ouro em\ndiagnóstico."},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-13266","number":"13266","sourceNumber":"13266","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Criança com 4 anos de idade, não vacinada com BCG, apresenta-se com teste de PPD\n\n= reator forte 12mm, assintomática, Rx do tórax sem anormalidades. Pai e mãe são tuberculosos,\nbaciliferos e iniciaram uso do Esquema I há\ndez dias. A conduta correta em relação à criança é:","options":{"A":"Apenas observar, se vier a apresentar sinais/sintomas entrar com Esquema I.","B":"Quimioprofilaxia secundária, com isoniazida por seis meses.","C":"Quimioprofilaxia primária, com isoniazida por três meses.","D":"Tratamento com Esquema I por seis meses.","E":"Repetir o teste PPD e Rx do tórax em três meses."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-10038","number":"10038","sourceNumber":"10038","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Você vai visitar em casa Sr. José de 94 anos. Ele vem apresentando tosse e\nemagrecimento há 1 mês. É hipertenso e está\nem uso regular de captopril com bom controle\npressórico. Tabagista há 10 anos de meio maço/dia. Seus últimos exames de sangue demonstram\numa elevação da creatinina sérica para 2,0mg/dl (valor máximo = 1,4). Seu exame clínico não\napresenta anormalidades. I- Você solicita raio-x de tórax e pesquisa de BAAR no escarro e PPD,\npara investigar uma provável tuberculose; II- Avalia se a tosse pode ser pelo uso do I-ECA e o\nsubstitui por outra classe de anti-hipertensivo; III- No diagnóstico diferencial com tuberculose,\nsuspeita de pneumonia, paracoccicidioidomicose e carcinoma pulmonar; IV- Solicita avaliação da\ndepuração da creatinina. Estão corretas as afirmativas:","options":{"A":"Apenas I e II.","B":"Apenas I e III.","C":"Apenas I e IV.","D":"I, II e III.","E":"Todas as afirmativas."},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-10039","number":"10039","sourceNumber":"10039","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Sr. José manteve o quadro de tosse sem expectoração e emagrecimento, apesar de ter\nseguido suas orientações. Seu raio-x evidenciou um pequeno derrame pleural à direita. A pesquisa\nde BAAR no escarro foi negativa e o PPD não reator. A família traz, então, o resultado da cultura de\nescarro pedida pelo Centro de Referência para onde o encaminhou. A cultura foi positiva para\nM.tuberculosis. Foi-lhe prescrito o esquema I. Você, enquanto médico desta família, orienta-os a:","options":{"A":"Vacinar a bisneta de Sr. José de 05 meses que não apresenta cicatriz de vacina BCG, apesar de\nter recebido a dose ao nascer.","B":"Explica que o Sr. José deverá fazer uso de três drogas - Rifampicina, Hidrazina, Etambutol - por\num período de 6 meses.","C":"Pede exames para familiares para investigar outros possíveis casos na família raio-x de tórax,\npesquisa de BAAR no escarro PPD e cultura de escarro.","D":"Indica a quimioprofilaxia para a esposa de Sr. José, D. Ana,de 90 anos e em tratamento para\nneoplasia de mama e cujo teste tuberculínico foi forte reator.","E":"A quimioprofilaxia deve ser feita com hidrazida por três meses."},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-10042","number":"10042","sourceNumber":"10042","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Sr. José está em uso de esquema I para tuberculose há 2 semanas e a filha lhe pede\numa consulta domiciliar pois o pai está com\npouco apetite, sonolento e vomitando. Ao exame, ele\nestá emagrecido, ictérico (+2/4+), eupneico, normotenso, sonolento, mas o reconhece e refere\nmuito mal estar. Seus últimos exames, feitos há 1 mês, demonstram enzimas hepáticas normais e\nelevação da creatinina sérica. Você, então:","options":{"A":"Suspeita de reação adversa ao esquema I e prescreve antiácido e antiemético.","B":"Suspende o esquema I e solicita dosagem de enzimas hepáticas urgente.","C":"Suspende o esquema I já que este é contraindicado com nível elevado da creatinina sérica.","D":"Ajusta a dose da medicação de acordo com a depuração da creatinina e mantém o esquema I.","E":"Mantém o esquema I mas fraciona a dose."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-62837","number":"62837","sourceNumber":"62837","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente, 13 anos de idade, portadora de LES em uso de corticosteroide 60 mg/dia, é\ninternada com queixa de perda de peso, tosse persistente há mais de 20 dias, febre moderada.\n\nHemograma com 5.600 leucócitos, 69% linfócitos, 1% bastões, 26% segmentados, O RX de tórax\nrevelou imagem em lóbulo superior direito circular com bordas definidas sem trama pulmonar no\nseu interior. Ao exame físico, peso: 11 kg, temperatura axilar de 37°C, taquipneico, com leve\ntiragem intercostal. Ausculta pulmonar com roncos e sibilos disseminados, murmúrio diminuído em\nápice do pulmão direito. Abdome flácido, fígado palpável no RCD, baço não palpável. Exame\nneurológico normal, reação de Mantoux: 10 mm. O diagnóstico mais provável é:","options":{"A":"infiltração pulmonar inflamatória do LES.","B":"tuberculose pulmonar.","C":"pneumonia estafilocócica.","D":"abcesso pulmonar por Pneumococcus.","E":"pneumonia por Mycoplasma."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-49286","number":"49286","sourceNumber":"49286","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente, 12 anos de idade, sexo feminino, apresenta febre persistente há 30 dias e\naumento de volume abdominal, amenorreia e perda ponderal (10 kg no período). Ao exame físico,\napresenta REG, emagrecida, abdome semigloboso, pouco tenso, doloroso à palpação profunda,\nsem visceromegalias ou massas palpáveis. Sinal de Piparote, radiografia de tórax: normal, USG de\nabdome total: presença de líquido ascítico em abdome e pelve, TC: dilatação de alças colônicas,\nretardo no trânsito intestinal. Moderada ascite. Realizada videolaparoscopia exploradora, já que\noutros exames não foram elucidativos como hemoculturas seriadas: negativas, função renal,\ntransaminases hepáticas, HIVI/II, AGHBs, Anti-HCV, reação de Widal, VDRL, FAN, beta-hCG,\nbaciloscopia do escarro: 3 amostras negativas, PPD não reator. Laudo cirúrgico: peritôneo\nespessado com múltiplas formações grumosas. A biópsia de peritônio revelou processo inflamatório\ncrônico granulomatoso com necrose caseosa. O diagnóstico mais provável é:","options":{"A":"Tuberculose peritoneal.","B":"Escarlatina.","C":"Mononucleose infecciosa crônica.","D":"Doença de Crohn.","E":"Pseudocolite membranosa."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-13348","number":"13348","sourceNumber":"13348","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente, dois anos de idade, é encaminhado ao ambulatório devido ao diagnóstico de\ntuberculose na tia paterna. A criança recebeu a vacina BCG ao nascer. Na investigação, foi\nsolicitado raio X de tórax, que foi normal e PPD, cujo resultado foi de 3 mm. Com relação à\ninterpretação do teste tuberculínico, é incorreto afirmar:","options":{"A":"O teste deve ser interpretado como sinal de alergia aos componentes dos bacilos tuberculínicos.","B":"Um teste positivo pode significar contato prévio com o bacilo virulento ou atenuado (vacinal).","C":"Um resultado positivo de 3 mm já indica tratamento para tuberculose em atividade.","D":"Devido à idade e ao contágio familiar, a paciente deve ser acompanhada periodicamente.","E":"é universalmente aceito, o efeito protetor da isoniazida como medicação profilática."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-13357","number":"13357","sourceNumber":"13357","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente, três anos de idade, é internado com história de tosse há 2 semanas, tendo\npiorado nos últimos dias com febre alta,\nanorexia e crises convulsivas. O exame físico mostra que o\nestado geral é precário, toxemiado, gemente, dispneico com tiragem IC. O RX de tórax mostra\nimagem de condensação bilateral. O PPD foi forte reator e o LCR: hipercelularidade,\nhiperproteinorraquia e hipoglicemia. O diagnóstico mais provável é:","options":{"A":"septicemia com choque tóxico infeccioso.","B":"HIV/SIDA.","C":"envolvimento neurológico pelo Micobacterium tuberculosis.","D":"histiocitose X.","E":"neurocísticercose."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-18048","number":"18048","sourceNumber":"18048","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente, sexo masculino, 47 anos de idade, etilista, atendido em posto de saúde, com\ntosse não produtiva há 3 semanas. O Rx de tórax mostra infiltrado apical em pulmão direito.\n\nApresentou perda ponderal de 6 kg nos últimos 3 meses. Tem sorologia HIV negativa e 3\nbaciloscopiais de escarro espontâneo\nnegativas. Iniciou teste terapêutico com isoniazida,\nrifampicina e pirazinamida e começou a apresentar na terceira semana de tratamento sensação de\nqueimação bilateral nos membros inferiores. A melhor conduta no caso é:","options":{"A":"Suspender o teste terapêutico e fazer baciloscopia em material obtido por broncoscopia.","B":"Suspender o teste terapêutico e aguardar resultado da cultura para BK do escarro.","C":"Suspender o teste terapêutico e fazer tomografia de alta resolução de tórax para confirmação\ndiagnóstica.","D":"Trocar o teste terapêutico para etambutol, estreptomicina, etionamida e pirazinamida.","E":"Manter o teste terapêutico."},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-18049","number":"18049","sourceNumber":"18049","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente, sexo masculino, 47 anos de idade, etilista, atendido em posto de saúde, com\ntosse não produtiva há 3 semanas. O Rx de tórax mostra infiltrado apical em pulmão direito.\n\nApresentou perda ponderal de 6 kg nos últimos 3 meses. Tem sorologia HIV negativa e 3\nbaciloscopiais de escarro espontâneo\nnegativas. Iniciou teste terapêutico com isoniazida,\nrifampicina e pirazinamida e começou a apresentar na terceira semana de tratamento sensação de\nqueimação bilateral nos membros inferiores. Nas circunstâncias desse paciente, o efeito colateral\nprovável e a medicação que o produz são, respectivamente:","options":{"A":"Interferência com a absorção de vitamina B12 e isoniazida.","B":"Competição com a vitamina B6 e pirazinamida.","C":"Interferência com a absorção de vitamina B6 e rifampicina.","D":"Competição com a vitamina B6 e isoniazida.","E":"Neurotoxicidade direta e isoniazida."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-13892","number":"13892","sourceNumber":"13892","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Jovem, 22 anos de idade, sexo masculino, com história de tosse produtiva há quatro\nsemanas, com febre, sudorese noturna e perda de peso. Evoluiu com hemoptise. O diagnóstico\nmais provável dessa condição será dado:","options":{"A":"Pelo Rx de tórax.","B":"Pelo PPD.","C":"Pela cultura para piogênicos do escarro.","D":"Pela baciloscopia do escarro.","E":"Pelo gram de escarro."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-343342","number":"343342","sourceNumber":"343342","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Outra forma de TB do sistema nervoso central é a forma localizada (tuberculomas).\nPodemos indicar como correto o item:","options":{"A":"Nessa apresentação, o quadro clínico é o de um processo expansivo intracraniano de\ncrescimento rápido , com sinais e sintomas de\nhipertensão intracraniana, sendo que a febre pode\nnão estar presente.","B":"Nessa apresentação, o quadro clínico é o de um processo expansivo intracraniano de\ncrescimento lento, com sinais e sintomas de\nhipertensão intracraniana, sendo que a febre sempre\ndeve estar presente.","C":"Nessa apresentação, o quadro clínico é o de um processo expansivo intracraniano de\ncrescimento lento, com sinais e sintomas de\nhipertensão intracraniana, sendo que a febre pode não\nestar presente.","D":"Nessa apresentação, o quadro clínico não é o de um processo expansivo intracraniano de\ncrescimento lento, com sinais e sintomas de\nhipertensão intracraniana, sendo que a febre pode não\nestar presente."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-314295","number":"314295","sourceNumber":"314295","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"\"Pela variedade de suas manifestações clínicas, recomenda-se que o diagnóstico de\ntuberculose (TB) pulmonar, em crianças e em adolescentes com baciloscopia negativa ou TRM-TB\nnão detectado, seja realizado com base em um sistema de escores [...]\" (BRASIL, 2021, p.467).\n\nEste escore varia com o quadro clínico-radiológico, o contato, a prova tuberculínica e o estado\nnutricional. Considerando esse sistema de escores para diagnóstico da tuberculose pulmonar em\ncrianças e adolescentes, é corretor afirmar que","options":{"A":"se o somatório de pontos for ?40 (diagnóstico muito provável), recomenda-se iniciar o tratamento\nda tuberculose.","B":"se o somatório de pontos for <25 (diagnóstico muito provável), recomenda-se iniciar o\ntratamento da tuberculose.","C":"se o somatório de pontos for entre 10 e 24 (diagnóstico provável), é indicativo de tuberculose, e\norienta-se iniciar o tratamento a critério médico.","D":"se o somatório de pontos for entre 05 e 15 (diagnóstico possível), é indicativo de tuberculose, e\norienta-se iniciar o tratamento a critério médico.","E":"se o somatório de pontos for entre 5 a 25 (diagnóstico muito provável), é indicativo de\ntuberculose, e orienta-se iniciar o tratamento a critério médico."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-281860","number":"281860","sourceNumber":"281860","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O diagnóstico e o tratamento da Infecção Latente da Tuberculose (ILTB) em pessoa\nvivendo com HIV PVHIV são fundamentais para minimizar o risco de adoecimento. Sendo correto\nque:","options":{"A":"O tratamento preventivo não reduziu esse risco em diversos estudos, quando orientado ou não\npela prova tuberculínica, respectivamente.","B":"O tratamento preventivo reduziu esse risco em diversos estudos, somente quando orientado pela\nprova tuberculínica, respectivamente.","C":"O tratamento preventivo aumentou esse risco em diversos estudos, quando orientado ou não\npela prova tuberculínica, respectivamente.","D":"O tratamento preventivo reduziu em 62% e 32% esse risco em diversos estudos, quando\norientado ou não pela prova tuberculínica, respectivamente."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-249720","number":"249720","sourceNumber":"249720","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O sistema esquelético alberga até 35% dos casos de tuberculose extrapulmonar. A\nalternativa que contém o sítio esquelético mais frequentemente afetado pela tuberculose é","options":{"A":"Fêmur.","B":"Escápula.","C":"Osso ilíaco.","D":"Coluna vertebral.","E":"Articulações interfalangianas distais."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-250020","number":"250020","sourceNumber":"250020","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Fomentar ações para garantir a realização das atividades de cuidado e prevenção da\ndoença com recursos adequados, somente sendo\ninadequado o item:","options":{"A":"Inserir ações de controle da tuberculose nos Planos Plurianuais.","B":"Pautar a tuberculose nas instâncias de pactuação e controle social.","C":"Implementar ações de comunicação e mobilização social para diminuir a visibilidade da doença.","D":"Disponibilizar insumos para o diagnóstico e medicamentos para o tratamento de todas as formas\nde tubérculos."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-250021","number":"250021","sourceNumber":"250021","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Os progressos nos determinantes sociais da saúde têm tido um efeito na saúde dos\nbrasileiros e isso provavelmente contribuiu também para a redução de doenças infecciosas, como a\nTB, no país. Somente não podemos aceitar que:","options":{"A":"Intervenções direcionadas aos determinantes socioeconômicos podem contribuir na melhoria do\ncontrole da TB no Brasil, a redução da pobreza não aparece como tema central","B":"Erradicar a pobreza, em todas as suas formas e dimensões, incluindo a pobreza extrema,\naparece como requisito indispensável para o\ndesenvolvimento sustentável.","C":"Assegurar uma vida saudável e promover o bem-estar para todas e todos, devendo-se acabar\ncom a epidemia global de tuberculose.","D":"A Estratégia pelo Fim da Tuberculose propõe a inclusão de intervenções socioeconômicas para\nprevenir e controlar a doença e também recomenda estratégias de proteção social para os\npacientes."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-250023","number":"250023","sourceNumber":"250023","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Nos casos clínicos, de TB pulmonar pós-primária ou secundária a tosse é produtiva, a\nexpectoração pode ser purulenta ou mucoide, com ou sem sangue. Indique o item inadequado:","options":{"A":"A febre vespertina, sem calafrios, não costuma ultrapassar os 38,5ºC.","B":"A sudorese noturna e a anorexia são raras.","C":"O exame físico geralmente mostra fácies de doença crônica e emagrecimento, embora\nindivíduos com bom estado geral e sem perda do apetite também possam ter TB pulmonar.","D":"A ausculta pulmonar pode apresentar diminuição do murmúrio vesicular, sopro anfórico ou\nmesmo ser normal."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-215600","number":"215600","sourceNumber":"215600","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O tratamento diretamente observado (TDO) é uma estratégia recomendada para todas\nas pessoas com diagnóstico de tuberculose.\nSendo INCORRETO que:","options":{"A":"Define-se como TDO a ingestão diária dos medicamentos antituberculose pelo paciente sob a\nobservação direta de um profissional de saúde.","B":"O TDO deve ser realizado diariamente (de segunda a sexta-feira) ou, excepcionalmente, uma\nvez na semana.","C":"O local e o horário devem estar acordados com o paciente.","D":"Os medicamentos deverão ser ingeridos preferencialmente em jejum, uma vez ao dia, inclusive\nnos finais de semana e feriados."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-215584","number":"215584","sourceNumber":"215584","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O tratamento da tuberculose sensível dura no mínimo 6 meses, desde o diagnóstico até\nsua alta. O estabelecimento de vínculo entre profissional de saúde e usuário auxilia tanto no\ndiagnóstico como na adesão ao tratamento, sendo que o paciente deve ser orientado, de forma\nclara, quanto às características clínicas da tuberculose, bem como acerca de eventos adversos.\n\nSomente se mostrando INADEQUADO que:","options":{"A":"No regime de tratamento com isoniazida, o mais importante é somente o tempo de tratamento.","B":"Recomenda-se a utilização de, no mínimo, 270 doses com isoniazida, que poderão ser tomadas\nde 9 a 12 meses.","C":"Deve-se considerar a utilização de 180 doses com isoniazida, a serem tomadas entre 6 a 9\nmeses em casos individuais, após avaliação da adesão.","D":"Há evidências de que o uso de 270 doses com isoniazida protege mais do que o uso de 180\ndoses. Esforços devem ser feitos para que o paciente complete o total de doses programadas."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-215604","number":"215604","sourceNumber":"215604","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em um paciente com diagnóstico de sepse, qual é o momento ideal de se iniciar a\nantibioticoterapia?","options":{"A":"Após realizar 3 expansões com 25 ml/Kg.","B":"Após realizar a primeira dose de corticoide.","C":"Na primeira hora do diagnóstico.","D":"Após afastar uma infecção viral."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-215611","number":"215611","sourceNumber":"215611","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação aos abscessos pulmonares.","options":{"A":"O abscesso pulmonar é uma coleção de pus localizada e causada pela destruição do\nparênquima pulmonar por substâncias proteolíticas produzidas por bactérias patogênicas ou\ninfecção bacteriana secundária em cavidade pulmonar preexistente.","B":"O abscesso primário de pulmão ocorre como resultado de infecção bacteriana produtora de\nnecrose no parênquima pulmonar de paciente previamente saudável.","C":"A aspiração da secreção orofaríngea infectada é a causa mais comum de abscesso pulmonar\nsecundário.","D":"A infecção secundária por cavidade pulmonar preexistente e a necrose por neoplasia, pós-infarto\nou tuberculose pulmonar também são definidas como\nabscessos."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-157679","number":"157679","sourceNumber":"157679","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A incidência concomitante de Tuberculose e Diabetes, coexistindo simultaneamente no\nmesmo indivíduo, ocorre frequentemente em nosso\nmeio, dentro da nossa realidade de país em\ndesenvolvimento. Das características clínicas e epidemiológicas descritas a seguir, aponte aquela\nque é considerada INADEQUADA.","options":{"A":"O risco de um paciente com DM desenvolver tuberculose é 2,44 a 8,33 vezes maior que da\npopulação geral.","B":"A frequência de tuberculose multirresistente não apresenta diferença nesse grupo.","C":"A radiografia de tórax pode apresentar alterações consideradas típicas (predominância nos\nlobos superiores) e também atípicas, acometendo predominantemente os lobos inferiores,\ngeralmente associadas a cavidades.","D":"A mortalidade e o risco de recidiva são superiores aos da população geral."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-139797","number":"139797","sourceNumber":"139797","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Dona Regina, 48 anos, procurou a Equipe de Saúde da Família da USF do Jardim\nGuanabara com queixas de tosse seca há seis semanas, além de perda de peso, dor torácica,\nrouquidão, febre diária, dispneia e mal-estar geral. Pensando em tuberculose pulmonar, o médico\nde família solicitou pesquisa de BAAR no escarro e Raios X de tórax. Considerando-se esse\nquadro, é CORRETO afirmar que:","options":{"A":"Não se trata de um sintomático respiratório, porque a Dona Regina não apresentou tosse\nprodutiva.","B":"Sobre o tratamento da tuberculose, houve a introdução do Etambutol como quarta droga para\nadolescentes e criança até 10 anos.","C":"Dentre as mudanças no tratamento, os esquemas até então denominados IR e III foram extintos.","D":"Outra mudança no tratamento foi a introdução de comprimidos formulados com quatro fármacos\ne doses fixas, combinados na fase de\nmanutenção."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-134733","number":"134733","sourceNumber":"134733","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em relação ao controle da tuberculose, as afirmações abaixo estão corretas, EXCETO\numa. Indique-a.","options":{"A":"Considerando a História natural da Tuberculose, as condições de habitação (ventilação,\numidade, aglomeração domiciliar) favorecem o aparecimento da doença.","B":"Do ponto de vista de um Programa de Controle da Tuberculose, a identificação e o tratamento\ndas fontes de infecção podem ser\n\nconsiderados como uma importante estratégia para reduzir a incidência da doença.","C":"A vacinação BCG intradérmica em massa, no primeiro ano de vida, reduz significativamente a\nincidência da meningite\n\ntuberculosa na população.","D":"O aparecimento de mais de um caso de tuberculose em um domicílio é consequência da\nexposição destes indivíduos à\n\ndesnutrição, que acarreta diminuição da resistência imunológica à tuberculose."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-111878","number":"111878","sourceNumber":"111878","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Mulher de 33 anos chega à unidade básica de saúde encaminhada por unidade de\nurgência. Entrega um receituário com prescrição do início de tratamento de Tuberculose. A\nradiografia de tórax mostra cavitação de 2 cm de diâmetro em ápice de hemitórax direito e exame\nde pesquisa do bacilo álcool-ácido resistente positivo (BAAR +++). O peso da paciente não está\nanotado. A conduta CORRETA, segundo o Programa Nacional de Controle da Tuberculose é:","options":{"A":"reiniciar a investigação com a realização de uma cultura de escarro.","B":"encaminhá-la para a farmácia para a dispensação da medicação (autoadministrado), agendar\nretorno em 30 dias e buscar todos os\ncontatos domiciliares.","C":"reinvestigar o caso, buscando confirmação clínica epidemiológica, realizar a notificação\ncompulsória na suspeita da doença e investigar os contatos domiciliares.","D":"realizar acolhimento e avaliação clínica adequada, iniciar o uso do tratamento diretamente\nobservado (supervisionado), notificar o caso e investigar os contatos."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-350898","number":"350898","sourceNumber":"350898","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente de 68 anos, masculino, deu entrada na UPA da Praia do Futuro com quadro\nde tosse cheia há 4 dias, associado a febre\ne queda importante do estado geral associado a\nepisódios de agitação psicomotora alternando com sonolência excessiva. Histórico de hipertensão\narterial em uso de enalapril e Diabetes Mellitus em uso de metformina e glibenclamida. Estado geral\ncomprometido, sonolento (Escala de Coma de Glasgow = 13 - AO3RV4RM6), FC = 120bpm, FR =\n28irpm, PA 80x50 mmHg, SpO? 94% com cateter nasal 2L/min. Ausculta cardíaca normal. Ausculta\npulmonar com crepitações em terço médio e base direita. Abdome flácido. Tempo de enchimento\ncapilar de 5 segundos. Realizada expansão volêmica com 1000ml de Ringer lactato, sem melhora\nda FC e PA, com surgimento de linhas B pulmonares em bases após realização de USG pulmonar.\nDe acordo com o exposto, qual a conduta mais adequada em relação ao controle hemodinâmico?","options":{"A":"Infusão de 1000ml de soro glicofisiológico.","B":"Infusão de noradrenalina em acesso venoso periférico.","C":"Infusão de dopamina somente após punção de acesso venoso central.","D":"Infusão de vasopressina e hidrocortisona em acesso venoso periférico."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-350815","number":"350815","sourceNumber":"350815","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Tales, de 17 anos, procura atendimento médico referindo tosse diária há quatro meses,\nevoluindo há 1 semana com expectoração esbranquiçada e com episódios de expectoração com\nraias de sangue. Relata que o quadro iniciou enquanto cumpria pena de privação provisória de\nliberdade em instituição socioeducativa. Refere perda ponderal não-intencional nos últimos dois\nmeses, com ?febre interna? diária. Refere uso diário de cigarro por tabaco e por cannabis.\n\nConsiderando o conceito de Sintomático Respiratório (SR), assinale a alternativa correta.","options":{"A":"Tales não pode ser considerado SR ainda, pois seus sintomas podem ser de natureza associada\nao fumo. É preciso reavaliar o quadro clínico\napós a cessação do fumo. Caso permaneça com\nsintomas respiratórios, afastadas as causas externas, ele deve ser considerado SR e deve ser\niniciada a investigação clínica apropriada.","B":"Tales não pode ser considerado SR ainda, pois seu quadro de tosse produtiva só tem duração\nde uma semana.","C":"Tales passou a ser considerado SR a partir do momento em que permaneceu sintomático por\npelo menos três semanas.","D":"Tales poderia ser considerado SR a qualquer momento de duração enquanto estava em\nprivação provisória de liberdade (PPL)."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-350814","number":"350814","sourceNumber":"350814","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Lana, de 3 anos, é trazida para atendimento na UBS por sua avó, dona Benzarina. A\navó relata que a criança falta\nrecorrentemente à escola por ?estar sempre gripada?. Queixa-se de\nque ?a menina está sempre com nariz escorrendo e tossindo?, que ?toda noite ela dorme mal, com\ncrises de tosse?, que ?a menina está tossindo todos os dias, há pelo menos um mês, uma tosse\nseca horrível?, que ?o tempo não pode mudar, que a criança começa a espirrar e tossir?, e que ?só\nesse ano ela já precisou tomar antibiótico três vezes, tudo de tipo diferente, passado pelo médico\ndo posto de saúde, por gripe mal curada?. Por fim, relata que o quadro piorou desde que Tales, tio\nde Lana, voltou a morar com elas, há 6 meses, depois de cumprir pena de privação provisória de\nliberdade. Tales apresenta sintomas semelhantes e fuma todos os dias. A investigação\ncomplementar para esclarecer os diagnósticos diferenciais do quadro respiratório de Lana deve ser\ncomposta, fundamentalmente, de quais exames?","options":{"A":"Prova tuberculínica (PPD) e radiografia de tórax.","B":"Prova tuberculínica (PPD), radiografia de tórax e espirometria.","C":"Baciloscopia de escarro ou teste rápido molecular para tuberculose (TRM-TB) e radiografia de\ntórax.","D":"Baciloscopia de escarro ou teste rápido molecular para tuberculose (TRM-TB), radiografia de\ntórax e espirometria."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-350813","number":"350813","sourceNumber":"350813","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Lana, de 3 anos, é trazida para atendimento na UBS por sua avó, dona Benzarina. A\navó relata que a criança falta\nrecorrentemente à escola por ?estar sempre gripada?. Queixa-se de\nque ?a menina está sempre com nariz escorrendo e tossindo?, que ?toda noite ela dorme mal, com\ncrises de tosse?, que ?a menina está tossindo todos o dias há pelo menos um mês uma tosse seca\nhorrível?, que ?o tempo não pode mudar que a criança começa a espirrar e tossir? e que ?só esse\nano ela já precisou ficar internada três vezes por gripe mal curada?. Por fim, relata que o quadro\npiorou desde que Tales, tio de Lana, voltou a morar com elas depois de cumprir pena de privação\nprovisória de liberdade. Tales apresenta sintomas semelhantes e fuma todos os dias. A\ninvestigação clínico-laboratorial de Lana descartou tuberculose ativa, mas indicou infecção latente\n(ILTB). Assinale a alternativa que traz o esquema terapêutico vigente e recomendado.","options":{"A":"Regime de tratamento com Isoniazida (H) por seis a nove meses - (6H).","B":"Regime de tratamento com Isoniazida (H) e Rifapentina (P) por três meses - (3HP).","C":"Regime de tratamento com Isoniazida (H) e Rifapentina (P) por seis meses - (6HP).","D":"Regime de tratamento com Isoniazida (H) e Rifampicina (R) por quatro meses - (4RH)."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-321304","number":"321304","sourceNumber":"321304","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente, de 68 anos, foi trazido por seus familiares para UPA, para avaliação devido\nquadro de confusão mental e sonolência nos\núltimos três dias, que piorou hoje, associado a\nsurgimento de tosse com escarro esverdeado, além de episódio de vômitos. Refere histórico de\nacompanhamento com urologista por hiperplasia prostática benigna, em uso de finasterida. Nega\noutras comorbidades e nega uso de antibióticos nos últimos meses. No momento, paciente\napresentando PA 80 x 40 e sonolência (escala de coma de Glasgow 13 ? abertura ocular 3 pontos;\nresposta verbal 4 pontos; resposta motora 6 pontos). FC = 110 bpm, em ritmo sinusal. FR = 32\nirpm. Ausculta cardíaca normal. Ausculta pulmonar com crepitações em base direita. Abdome\nflácido, indolor. Tempo de enchimento capilar de 5 segundos. Sem edema em membros inferiores.\nQual das opções abaixo descreve a conduta mais CORRETA para essa situação clínica?","options":{"A":"Iniciar tratamento por via intravenosa com levofloxacino com necessidade de internação\nhospitalar em ambiente de enfermaria.","B":"Iniciar expansão volêmica com cristaloides e prescrever ceftriaxona, após confirmação de\nresultado em culturas, e internação em leito de UTI.","C":"Iniciar expansão volêmica com cristaloides, coleta de culturas e lactato, associar ceftriaxona e\nazitromicina empíricos e internação em leito de UTI.","D":"Iniciar tratamento ambulatorial com antibioticoterapia via oral com amoxicilina e azitromicina\ncom\nacompanhamento na unidade básica de saúde."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-321341","number":"321341","sourceNumber":"321341","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Durante a reunião estratégica da sua equipe na UBS, foi relatado que não constavam\npessoas em tratamento para tuberculose em\nnenhuma das microáreas sob sua responsabilidade. A\nbase de dados do seu município indicava uma prevalência de tuberculose pulmonar bacilífera de 80\ncasos a cada 100.000 habitantes e a população adscrita nas suas microáreas era de 10.000\nhabitantes. Diante disso, os agentes comunitários foram capacitados para realizar busca ativa,\natravés da aplicação de questionário para identificação de Sintomáticos Respiratórios (SR),\ndetectando a presença de 100 SR. Sobre busca ativa do Sintomático Respiratório (SR), assinale a\nalternativa correta.","options":{"A":"Em população geral, corresponde à pessoa com presença de tosse seca por mais de três\nsemanas.","B":"Em população geral, corresponde à pessoa com presença de tosse produtiva por mais de três\nsemanas.","C":"Em algumas populações específicas de alto risco de adoecimento por tuberculose, pode\ncorresponder à pessoa com presença de tosse de qualquer duração.","D":"A investigação de Sintomáticos Respiratórios encaminhados à UBS, oriundos de busca ativa na\npopulação geral, consiste na coleta de escarro para baciloscopia e radiografia de tórax."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-321350","number":"321350","sourceNumber":"321350","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Isadora, de oito anos, vem acompanhada da avó para a consulta. A avó relata\ninapetência, perda ponderal progressiva, tosse\nseca, palidez e febre não aferida há quatro meses.\nRefere ainda que não trouxe a neta antes por dificuldade de locomoção à UBS. Quando\nquestionada a respeito dos pais de Isadora, relata que o pai está preso e que a mãe faleceu há um\nano por tuberculose. Ao exame físico, você nota quadro de desnutrição grave e ausculta pulmonar\nabolida em ápice à esquerda. Assinale a alternativa com a conduta a ser tomada.","options":{"A":"Solicitar baciloscopia de escarro e radiografia de tórax para diagnóstico de tuberculose por\nsistema de escore.","B":"Solicitar baciloscopia de escarro e prova tuberculínica para diagnóstico de tuberculose por\nsistema de escore.","C":"Solicitar baciloscopia de escarro, radiografia de tórax e prova tuberculínica para diagnóstico de\ntuberculose por sistema de escore.","D":"Estabelecer o possível diagnóstico clínico-epidemiológico de tuberculose pelo sistema de escore\ne iniciar tratamento para tuberculose\ncorrigido para o peso da paciente."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-292812","number":"292812","sourceNumber":"292812","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem de 35 anos apresenta quadro de tosse produtiva com expectoração amarelada,\nhá 2 dias, associada a febre. Ao exame\nfísico, apresenta crepitações em base direita, estado\nconfusional, pressão arterial 80 x 50 mmHg e frequência respiratória de 26 irpm. Radiografia de\ntórax evidencia infiltrado alveolar em base direita. Qual o tratamento inicial mais adequado para\nesse caso clínico?","options":{"A":"Expansão volêmica e antibioticoterapia.","B":"Hidrocortisona e expansão volêmica.","C":"Noradrenalina e antibioticoterapia.","D":"Noradrenalina e hidrocortisona."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-292819","number":"292819","sourceNumber":"292819","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Mulher, 70 anos, é trazida por familiares à emergência com história de cinco dias de\ntosse seca e três dias de queda do apetite e\napatia intensa. Tem história de insuficiência cardíaca\ncongestiva. Apresenta-se alerta, sem taquidispneia e SpO?: 96% em ar ambiente. Normotensa e\nafebril. Ausculta cardíaca com ritmo regular em 2 tempos e FC: 90 bpm. Ausculta respiratória com\ncrepitações bibasais mais intensas, à direita. O hemograma não mostra anemia nem plaquetopenia,\ne leucograma com 12.000/mm³ sem desvios. Proteína C reativa = 6,0 (normal até 0,5), glicemia =\n110 mg/dl, ureia = 40 mg/dl , creatinina = 0,8 mg/dl, sódio = 133 mEq/L, potássio = 3,9 mEq/L.\nSwab nasal com painel viral negativo (SARS-Cov 2, Influenza, VSR e Rinovírus). A radiografia de\ntórax em PA é mostrada na figura a seguir. Neste contexto, e considerando o diagnóstico mais\nprovável, a abordagem de escolha para essa paciente seria:","options":{"A":"Cefepime + Azitromicina.","B":"Ceftriaxona + Claritromicina.","C":"Moxifloxacina + Azitromicina.","D":"Amoxicilina/Clavulanato + Claritromicina."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-292857","number":"292857","sourceNumber":"292857","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Durante seu acompanhamento com Edmilson, você nota que a baciloscopia antes de\nreiniciar a RHZE foi positiva (3+), que a baciloscopia com 15 dias após reinício de tratamento\npersistiu positiva (1+), mas que ele ficou assintomático. A baciloscopia realizada após o primeiro\nmês de tratamento permaneceu positiva (1+). Em sua consulta, ao término do segundo mês de\ntratamento, você atende Edmilson, que está assintomático e com baciloscopia negativa. Assinale a\nalternativa correta em relação ao seguimento clínico.","options":{"A":"Considerando a persistência de baciloscopia positiva até o término do primeiro mês de\ntratamento, estender a fase de ataque (RHZE) por um terceiro mês e solicitar baciloscopias\nquinzenais.","B":"Considerando que o paciente evoluiu assintomático e a baciloscopia está negativa, iniciar a fase\nde manutenção (RH) por quatro meses e solicitar\nbaciloscopia de escarro em periodicidade mensal.","C":"Considerando que o paciente evoluiu assintomático e a baciloscopia está negativa, mas que o\npaciente tem histórico de abandono de tratamento prévio, estender a fase de ataque (RHZE) por\num terceiro mês e solicitar baciloscopia mensal.","D":"Considerando que o paciente evoluiu assintomático e a baciloscopia está negativa, mas que o\npaciente tem histórico de abandono de tratamento prévio, estender a fase de manutenção (RH) por\ntrês meses adicionais, totalizando sete meses de fase RH."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-259716","number":"259716","sourceNumber":"259716","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem de 70 anos, hipertenso e diabético compensado, procura o pronto atendimento\ncom queixa de tosse produtiva e febre há 2\ndias. Ao exame encontra-se consciente e orientado,\napresenta crepitações em base de hemitórax esquerdo na ausculta pulmonar, frequência\nrespiratória de 22 incursões/minuto, frequência cardíaca de 85 batimentos/minuto, saturação de\noxigênio de 94% em ar ambiente e pressão arterial 130 x 80 mmHg. Exames laboratoriais: Proteína\nC-Reativa (PCR) de 9,41 ng/dl (valor de referência < 0,5 mg/dl). Qual a melhor conduta nesse\ncaso?","options":{"A":"Internação em enfermaria ? iniciar ampicilina + sulbactam e azitromicina por via endovenosa.","B":"Internação em unidade de terapia intensiva ? iniciar ceftriaxona e azitromicina por via\nendovenosa.","C":"Tratamento ambulatorial ? iniciar amoxicilina + ácido clavulânico por via oral, com retorno\nprecoce para reavaliação.","D":"Tratamento ambulatorial ? iniciar amoxicilina + ácido clavulânico e azitromicina por via oral,\ncom\nretorno precoce para reavaliação."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-259720","number":"259720","sourceNumber":"259720","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Mulher de 52 anos tem história de 3 dias de febre elevada com calafrios, lombalgia à\nesquerda, vômitos e mal-estar geral. Na manhã de hoje, associaram-se sonolência, palidez\ncutâneo-mucosa acentuada e sudorese. Dá entrada no Pronto-Socorro (PS) com Glasgow 10,\nextremidades frias e pele de aspecto mosqueado. Pressão Arterial (PA) = 70 x 40 mmHg,\nfrequência cardíaca = 130 bpm, frequência respiratória = 28 irpm, pulso filiforme e má perfusão\nperiférica. Soro fisiológico 30 ml/kg é rapidamente administrado por dois acessos periféricos. Após\n20 minutos, a PA se encontra em 74 x 40 mmHg. Qual o principal parâmetro a ser monitorado,\nprioritariamente, na primeira hora da chegada desta paciente ao PS?","options":{"A":"Lactato arterial.","B":"Débito urinário.","C":"Glicemia plasmática.","D":"Pressão venosa central."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-259763","number":"259763","sourceNumber":"259763","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem de 62 anos recebe diagnóstico de tuberculose pulmonar bacilífera na Unidade\nBásica de Saúde. Seus contactantes são convocados à consulta médica, cujos dados constam na\ntabela a seguir: Qual dos contactantes tem indicação, neste momento, de terapia para infecção\nlatente com rifampicina?","options":{"A":"Neta.","B":"Nora.","C":"Filho.","D":"Esposa."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-234030","number":"234030","sourceNumber":"234030","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente masculino, 26 anos, internado há 3 dias com quadro de tosse produtiva, febre\ne dor torácica à esquerda iniciado uma\nsemana antes da admissão. Na admissão, constatadas\nfebre, pressão arterial e frequência respiratória normais. Ausculta pulmonar apresentava-se com\nmurmúrio vesicular reduzido em 2/3 inferiores de hemitórax esquerdo e frêmito toracovocal\nreduzido na mesma localização. Encontra-se em uso de ceftriaxona e azitromicina, hoje mantendo\nquadro clínico e exame físico semelhantes aos da admissão. Ultrassonografia mostrou derrame\npleural ocupando os 2/3 inferiores do hemitórax esquerdo, sendo submetido a toracocentese com\nretirada de 60 ml de líquido citrino cujo estudo evidenciou pH = 7,16, glicose = 35 mg/dl,\ncelularidade aumentada às custas de neutrófilos, com características de exsudato. Cultura do\nlíquido pleural ainda está em andamento. Qual das opções abaixo descreve a conduta adequada a\nser realizada no contexto clínico descrito?","options":{"A":"Ampliar esquema antimicrobiano para piperacilina + sulbactam.","B":"Manter conduta atual até resultado de cultura obtida do líquido pleural.","C":"Realizar tomografia de tórax e indicar decorticação se derrame pleural estiver livre.","D":"Realizar drenagem pleural com posicionamento de dreno na cavidade acometida."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-234069","number":"234069","sourceNumber":"234069","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Mulher de 24 anos procura a Unidade Básica de Saúde (UBS) com queixas de febre\nvespertina, tosse produtiva com expectoração amarelada, hemoptoicos e perda de peso há 1 mês.\nNo retorno, traz raio X de tórax mostrando cavitação em lobo superior do pulmão direito. Após ter\nsido feito o diagnóstico da principal hipótese para o caso, qual a conduta a ser tomada, ainda na\nUBS, no momento da consulta?","options":{"A":"Teste rápido para HIV.","B":"Exame dos contactantes.","C":"Teste urinário de gravidez.","D":"Administração da primeira dose dos medicamentos."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-199670","number":"199670","sourceNumber":"199670","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Adulto jovem, brasileiro, com história de tosse produtiva, febre irregular e astenia há 1\nmês. Fez uso de amoxicilina no início do quadro sem melhora clínica. Realizou três baciloscopias,\ntodas negativas para BAAR. Sua radiografia de tórax em PA é mostrada abaixo. Legenda: BAAR:\nBacilo Álcool-Ácido Resistente. Considerando que o paciente permanece com os mesmos\nsintomas, o exame mais indicado para confirmar o diagnóstico mais provável, neste momento seria:","options":{"A":"Broncoscopia.","B":"Escarro induzido.","C":"Cultura do escarro.","D":"Teste tuberculínico."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-172956","number":"172956","sourceNumber":"172956","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Menino de 4 anos de idade iniciou quadro de tosse produtiva que evoluiu com febre e\nhiporexia. Foi atendido em uma Unidade Básica de Saúde (UBS), após 3 dias do início do quadro,\nsendo prescrito antibiótico oral. Após 48 horas, não apresentou melhora, evoluindo com dispneia\nprogressiva, tiragem intercostal e piora da tosse e da febre. Foi, então, internado em unidade\nterciária, sendo identificado pneumonia com derrame pleural à direita. Iniciada antibioticoterapia\nvenosa e realizado toracocentese seguida de drenagem pleural sob selo d?água. Líquido pleural\nera de aspecto purulento, com bioquímica mostrando relação entre dosagem de desidrogenase\nláctica do líquido e sérica de 0,9. Após 72 horas, a criança não apresentou melhora do quadro\nclínico. Dreno de tórax encontrava-se oscilante, mas sem débito significativo, sendo realizado um\nraio X de tórax (ver imagem) e uma ultrassonografia de tórax que revelou derrame pleural com\nseptações espessas à direita. A conduta mais apropriada para esta criança é:","options":{"A":"Troca do dreno e deixando-o em aspiração contínua.","B":"Videotoracoscopia para limpeza da cavidade pleural.","C":"Toracotomia com ligadura do ducto torácico anterior.","D":"Descorticação pulmonar com pleurodese mecânica ou química."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-172971","number":"172971","sourceNumber":"172971","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente feminina, 56 anos e peso estimado em 50 kg, tem diagnóstico de pielonefrite,\nem serviço de emergência. Está confusa,\nletárgica e os sinais vitais são: T = 39,2°C; PA = 62 x 40\nmmHg; FC = 144 bpm; FR = 42 irpm; SpO? = 95%. Ausculta cardiopulmonar sem alterações e\ntempo de enchimento capilar normal. Apresenta lactato arterial de 3,2 mEq/L (VR: até 2,0 mEq/L) e\nHb de 8,7 g/dl (VR: 11,5-16 g/dl). É submetida à expansão volêmica com soro fisiológico evoluindo\nconforme registro a seguir. São colhidas culturas, é administrada primeira dose de antibiótico\nadequado e a paciente é transferida para UTI mantendo os dados do último registro. Legenda: T ?\nTemperatura; PA ? Pressão Arterial; FC ? Frequência Cardíaca; bpm ? batimentos por minuto; FR ?\nFrequência Respiratória; irpm ? incursões respiratórias por minuto; SpO? ? Saturação de Oxigênio;\nUTI ? Unidade de Terapia Intensiva; VR ? Valor de Referência. Qual terapêutica deve ser instituída\nnesse momento?","options":{"A":"Infusão de noradrenalina.","B":"Administração de hidrocortisona.","C":"Expansão com soro fisiológico 0,9%.","D":"Transfusão de concentrado de hemácias filtrado."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-173005","number":"173005","sourceNumber":"173005","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Mulher de 32 anos, usuária de crack e moradora de rua, em Fortaleza, é admitida para\ninvestigação de quadro de febre intermitente, perda de peso, tosse produtiva com hemoptoicos e\ndor torácica ventilatório-dependente à direita. Vinha em uso de levofloxacino há 1 semana. Ao\nexame, encontra-se emagrecida, pálida 2+/4+; ausculta: sopro tubário e roncos em terço superior\ndo hemitórax direito; restante normal. Exames iniciais: Hb = 9,5 g/dl (VR = 11,5-15,5 g/dl); Ht =\n25%\n(VR = 36-48%); leucócitos = 5.200 (VR = 4.000-10.000); plaquetas = 400.000 (VR =\n\n150.000-450.000); anti-HIV: não reagente; radiografia de tórax: cavitação em terço superior do\ncampo pulmonar direito e velamento do seio\ncostofrênico direito. Baciloscopia do escarro (2\namostras): negativas. Legenda: VR: Valor de Referência; Hb: Hemoglobina; Ht: Hematócrito.\nConsiderando a indisponibilidade de teste molecular e broncoscopia no seu hospital, qual a\nrecomendação CORRETA?","options":{"A":"Internar em isolamento para aerossóis e iniciar terapia empírica para tuberculose.","B":"Internar em leito convencional e iniciar terapia empírica para tuberculose.","C":"Internar em isolamento para aerossóis e aguardar cultura do escarro.","D":"Internar em leito convencional e aguardar cultura do escarro."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-173013","number":"173013","sourceNumber":"173013","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em reunião de equipe em uma unidade de atenção básica, o agente de saúde (ACS) é\ndemandado a realizar busca ativa de paciente faltoso à consulta do 3º mês de retratamento de\ntuberculose pulmonar. Na semana seguinte, o ACS relata que o paciente em questão, que é\ndependente de substâncias psicoativas, por estar se sentindo melhor, havia voltado às ruas\n(mesmo motivo do abandono anterior) e há 15 dias estava evadido do domicílio. Em relação ao\ntratamento diretamente observado, qual deve ser a proposta adotada pela equipe?","options":{"A":"Administrar tratamento na UBS quando o paciente retornar ao domicílio.","B":"Reiniciar tratamento na UBS após cessar o uso de substâncias psicoativas.","C":"Compartilhar supervisão do tratamento com a rede de atenção psicossocial.","D":"Indicar o tratamento e encaminhar para serviço de referência em infectologia."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-150841","number":"150841","sourceNumber":"150841","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente masculino, médico de família, 28 anos, apresentando febre com calafrios e\ntosse produtiva há 3 dias, procurou\natendimento, hoje, na emergência. Ao exame, encontra-se\norientado, FC = 100 bpm; FR = 31 irpm; PA = 80 x 60 mmHg; sem resposta à ressuscitação\nvolêmica, ausculta pulmonar com roncos em base direita. PaO2 = 60 mmHg; saturação O2 = 89%\nem ar ambiente. Radiografia de tórax abaixo. Hemograma com HB = 13 g/dl; leucócitos = 13.000\ncéls/mm3; creatinina = 1,0 mg/dl; ureia = 55 mg/dl. (VER IMAGEM) Considerando o quadro clínico,\nqual a conduta mais adequada?","options":{"A":"Internar em UTI e iniciar ceftriaxona e claritromicina.","B":"Iniciar piperacilina/tazobactam e internar na UTI.","C":"Iniciar levofloxacino e internar em enfermaria.","D":"Internar em enfermaria e iniciar azitromicina."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-150811","number":"150811","sourceNumber":"150811","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Criança de 3 anos mora com a avó, que recebeu diagnóstico de tuberculose pulmonar\nhá 1 mês e já iniciou tratamento. A família\nrealizou o protocolo solicitado e a criança não apresenta\nalterações clínicas e nem radiológicas, e o PPD é negativo. Não apresenta cicatriz de BCG e não\ntem caderneta de saúde. A mãe não lembra de ter aplicado a vacina. Como está classificado e qual\na conduta a ser adotada com essa criança?","options":{"A":"Contato com infecção ? quimioprofilaxia secundária com isoniazida por 6 meses.","B":"Contato sem infecção ? observação e repetição do teste tuberculínico em dois meses.","C":"Doente ? tratamento com esquema de curta duração com rifampicina, isoniazida e pirazinamida.","D":"Contato sem infecção ? quimioprofilaxia primária com isoniazida por 3 meses e repetição da\nprova tuberculínica."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-102145","number":"102145","sourceNumber":"102145","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Mãe, portadora de tuberculose pulmonar, está em tratamento há 30 dias. Ela traz seu\nfilho de 2 meses, pois está preocupada com a transmissão da doença para o mesmo, que está\nassintomático. A criança não foi vacinada com a BCG. Qual conduta o médico deve tomar com\nrelação a esta criança?","options":{"A":"Solicitar PPD e decidir vacinação com a BCG após seu resultado.","B":"Solicitar PPD e Raio-X de tórax e decidir vacinação com a BCG, após seu resultado.","C":"Iniciar quimioprofilaxia primária com Isoniazida e vacinar o bebê com a BCG após 3 meses, se\no PPD for menor ou igual a 5 mm.","D":"Solicitar Raio-X de tórax e iniciar quimioprofilaxia primária com Isoniazida e vacinar o bebê com\na\n\nBCG, após 3 meses, se o PPD for menor ou igual a 5 mm."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-81227","number":"81227","sourceNumber":"81227","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente masculino, 32 anos, é atendido na emergência com história de que há 3 dias\niniciou quadro de febre alta, coriza e odinofagia. Nas últimas 24h evoluiu com tosse, hemoptoicos e\ndispneia. Tabagista 5 anos-maço. Asmático controlado com beclometasona inalatória. Ao exame:\nconsciente, taquipneico com saturação de pulso de oxigênio de 91% em ar ambiente, frequência\ncardíaca de 116 bpm e pressão arterial 130 x 80 mmHg. Ausculta respiratória evidencia sibilos\ndifusos. A radiografia de tórax é apresentada abaixo. (VER IMAGEM). A conduta que mais\nprovavelmente barrará a progressão da doença será:","options":{"A":"Oseltamivir oral.","B":"Heparina subcutânea.","C":"Corticoide endovenoso.","D":"Ceftriaxona endovenosa."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-81295","number":"81295","sourceNumber":"81295","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Carlos, 23 anos de idade, usuário de crack e álcool, foi diagnosticado com tuberculose\ne iniciou seu tratamento. A equipe de saúde da\nfamília decidiu realizar uma visita domiciliar para\navaliar os contatos domiciliares. Na casa, moravam seus irmãos José, com 12 anos de idade,\nassintomático, e Clarisse, com 15 anos, que apresentava coriza, tosse não produtiva e febre há 5\ndias. Ambos apresentavam cartão de situação vacinal adequada para a idade. Foram solicitados\nexames complementares com os seguintes resultados: José: radiografia de tórax normal e teste\ntuberculínico igual a 8 mm; Clarisse: radiografia de tórax normal e teste tuberculínico igual a 12\n\nmm. De acordo com as orientações do Ministério da Saúde, qual o plano terapêutico mais\nadequado a ser adotado pelo médico em relação aos irmãos de Carlos?","options":{"A":"Iniciar isoniazida para Clarisse e José.","B":"Administração de BCG para ambos e iniciar isoniazida para Clarisse.","C":"Repetir teste tuberculínico para José, em 60 dias, e iniciar isoniazida para Clarisse.","D":"Iniciar isoniazida, rifampicina, pirazinamida e etambutol para Clarisse e isoniazida para José."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-65724","number":"65724","sourceNumber":"65724","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um homem de 27 anos sem tratamento antirretroviral para HIV apresenta tosse seca e\nfebre vespertina há 1 mês. Há uma semana apresenta letargia, cefaleia, irritabilidade. A ausculta\npulmonar é normal, e há rigidez de nuca. O exame do liquor mostra 200 leucócitos/mm³ (normal:\n\n0-5 mononucleares); com 90% de linfócitos; proteínas 4 g/L (normal: 0,15-0,5); glicose 15 mg/dl\n(normal: 40-70). O exame de raio X de tórax está reproduzido na figura abaixo (VER IMAGEM).\nConsiderando que R-rifampicina, H-isoniazida, Z-pirazinamida, E-etambutol e que o número logo\nantes das siglas indica a duração do tratamento em meses, assinale a alternativa que indica\nCORRETAMENTE o tratamento recomendado pelo Ministério da Saúde/Brasil.","options":{"A":"Fase intensiva: 2RHZ; fase de manutenção: 4RH.","B":"Fase intensiva: 2RHZE; fase de manutenção: 4RH.","C":"Fase intensiva: 2RHZE; fase de manutenção: 7RH.","D":"Fase intensiva: 2RHZ; fase de manutenção: 7RH; corticoide.","E":"Fase intensiva: 2RHZE; fase de manutenção: 7RH; corticoide."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-51221","number":"51221","sourceNumber":"51221","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em quais situações da prática clínica está indicada a quimioprofilaxia secundária da\ntuberculose?","options":{"A":"Em crianças imunodeprimidas por doenças imunossupressoras.","B":"Em crianças infectadas pelo HIV, com PPD \"igual ou superior\" a 10 mm.","C":"Em crianças com viragem tuberculínica recente, ou seja, aumento de, no mínimo, 5 mm na\nreação ao PPD nos últimos 12 meses.","D":"Em crianças menores de 15 anos de idade, sem sinais de Tb ativa, contactante com pessoa com\ntuberculose bacilífera, não vacinadas com reação ao PPD \"maior que\"10 mm."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-51260","number":"51260","sourceNumber":"51260","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"É objetivo da busca ativa de sintomáticos respiratórios na comunidade:","options":{"A":"reduzir a incidência de asmáticos em longo prazo.","B":"interromper a cadeia de transmissão da tuberculose.","C":"identificar precocemente pacientes com enfisema pulmonar.","D":"prevenir desenvolvimento de tuberculose com resistência primária."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-141583","number":"141583","sourceNumber":"141583","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Qual é a melhor opção para o tratamento de paciente com pneumonia grave, adquirida\nna comunidade, com indicação de internamento em\nunidade de terapia intensiva?","options":{"A":"Ceftriaxona.","B":"Moxifloxacino.","C":"Ampicilina + sulbactam.","D":"Ceftriaxona + azitromicina."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-29463","number":"29463","sourceNumber":"29463","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em relação ao exame bacteriológico para o diagnóstico da tuberculose pulmonar,\ndeverá ser considerado como tuberculose\npulmonar positiva o caso que apresente:","options":{"A":"Duas baciloscopias diretas positivas;","B":"Uma baciloscopia direta positiva e cultura positiva;","C":"Uma baciloscopia direta positiva e imagem radiológica sugestiva de tuberculose pulmonar;","D":"Todas as alternativas anteriores estão corretas."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-24360","number":"24360","sourceNumber":"24360","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Os primeiros indícios da existência da tuberculose na humanidade remontam:","options":{"A":"a escrito no terceiro milênio a.C., reportado no livro chinês Huang Ti Mei-Ching.","B":"à análise de ossos da dinastia Shang, cerca de 1650-1027 a.C.","C":"ao relato de Heródoto que constatou a doença no Egito cerca de 800 a 900 a.C.","D":"à descrição da doença na Ilíada por Homero."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-7280","number":"7280","sourceNumber":"7280","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"?Os benefícios do tratamento de um caso de tuberculose trazem vantagens\nexclusivamente para o paciente PORQUE os serviços de saúde não apresentam grandes\nexternalidades.? Com respeito ao enunciado acima, tem-se:","options":{"A":"a assertiva e a razão são corretas e relacionadas.","B":"a assertiva e a razão são corretas, mas não relacionadas.","C":"a assertiva é correta e a razão, errada.","D":"a assertiva é errada e a razão, correta.","E":"a assertiva e a razão são erradas."},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-9015","number":"9015","sourceNumber":"9015","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem de 52 anos, desempregado, etilista pesado queixando-se de lombalgia, febre\nvespertina, anorexia e perda de peso. Ao exame, encontra-se apenas emagrecido. US abdominal\nrevelou calcificações esparsas no parênquima renal direito e o sumário de urina evidencia\nhematúria microscópica, piúria microscópica e ausência de bactérias. Qual a PRINCIPAL hipótese\ndiagnóstica para o caso?","options":{"A":"Amiloidose renal","B":"Infecção urinária por anaeróbios","C":"Tuberculose renal","D":"Carcinoma de células renais"},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-9116","number":"9116","sourceNumber":"9116","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em relação à etiologia, transmissão e patogênese da tuberculose, assinale a alternativa\nINCORRETA:","options":{"A":"A tuberculose (TB) é uma doença infecciosa e contagiosa, causada por um microorganismo\ndenominado Mycobacterium tuberculosis, que se propaga\natravés do ar, por meio de gotículas\ncontendo os bacilos expelidos por um doente com TB pulmonar ao tossir, espirrar ou falar em voz\nalta.","B":"A propagação da tuberculose está intimamente ligada às condições de vida da população; a sua\nincidência é maior nas periferias das grandes cidades, podendo porém, acometer qualquer pessoa\nmesmo em áreas rurais.","C":"A infecção pelo bacilo da tuberculose pode ocorrer em qualquer idade, mas no Brasil geralmente\nacontece no adulto.","D":"Todos os órgãos podem ser acometidos pelo bacilo da tuberculose, porém ocorre mais\nfrequentemente nos pulmões, gânglios, pleura, rins, cérebro e ossos."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-9118","number":"9118","sourceNumber":"9118","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Já em relação ao exame bacteriológico para o diagnóstico da tuberculose pulmonar,\nmarque a alternativa INCORRETA:","options":{"A":"A baciloscopia direta do escarro é um método fundamental, porque permite descobrir as fontes\nmais importantes de infecção - os casos bacilíferos.","B":"A baciloscopia direta do escarro deve ser sempre solicitada para os pacientes adultos que\nprocurem o serviço de saúde por apresentarem\nqueixas respiratórias ou qualquer outro motivo, mas\nque espontaneamente, ou em resposta ao pessoal de saúde, informem ter tosse e expectoração\npor duas semanas.","C":"A baciloscopia direta do escarro também deve ser sempre solicitada para os contatos de casos\nde tuberculose pulmonar bacilíferos que\napresentem queixas respiratórias.","D":"Recomenda-se, para o diagnóstico, a coleta de duas amostras de escarro, uma por ocasião da\nprimeira consulta e a segunda, independente do resultado da primeira, na manhã do dia seguinte\nao despertar."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-13445","number":"13445","sourceNumber":"13445","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"As drogas usadas no tratamento inicial da tuberculose pulmonar são:","options":{"A":"Rifampicina+izoniazida+pirazinamida.","B":"Rifampicina+izoniazida+estreptomicina.","C":"Izoniazida+etionamida+estreptomicina.","D":"Ciproflozacina+etionamida+etambutol.","E":"Amoxicilina+claritromicina+izoniazida."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-6969","number":"6969","sourceNumber":"6969","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem, 50 anos, branco, após reforma de aviário foi internado com febre, dispneia e\ntosse. Foi diagnosticado pneumonia, não apresentando melhora com antibióticos. Refere que um\ncolega de trabalho que o auxiliou na limpeza do aviário também apresentou sintomas semelhantes\nlogo após o serviço. Nega emagrecimento, etilismo, tabagismo ou uso de medicamentos. A\ngasometria revela hipoxemia e o Raio-X de tórax mostra opacidades alveolares bilaterais de\npredomínio cortical e com micronódulos difusos. Qual a hipótese diagnóstica mais provável?","options":{"A":"Histoplasmose.","B":"Coccidiodomicose.","C":"Tuberculose.","D":"Neoplasia.","E":"Pneumonia atípica."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-17853","number":"17853","sourceNumber":"17853","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O pai de uma criança de quatro anos de idade é portador bacilífero de tuberculose, e\nacabou de iniciar o tratamento. A criança é\nvacinada com a BCG, e é assintomática. A conduta\nmais adequada para a criança é:","options":{"A":"iniciar profilaxia com isoniazida","B":"iniciar tratamento para tuberculose com esquema tríplice","C":"solicitar raios X de tórax, e, caso normal, iniciar profilaxia com isoniazida","D":"colher o PPD e, caso reator forte, iniciar tratamento para tuberculose com esquema tríplice","E":"acompanhar regularmente em regime ambulatorial, sem profilaxia ou tratamento"},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-349744","number":"349744","sourceNumber":"349744","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um médico, trabalhando em uma unidade de pronto atendimento, atende um paciente\nde 70 anos com queixa de febre de início há\n4 dias, acompanhada de tosse produtiva e astenia. O\npaciente é diabético e hipertenso, encontra-se consciente e orientado, porém, no momento, está\ncom a visão prejudicada, devido à cirurgia recente de correção de catarata. Ele não tem tomado as\nmedicações de uso contínuo por não estar conseguindo identificá-las. Seu filho, que mora há 450\nKm de distância, chegará em 2 dias para poder acompanhá-lo. Ao exame físico, apresenta\nfrequência respiratória de 24 irpm, pressão arterial de 100x64 mmHg, exame laboratorial: ureia 45\nmg/dl e creatinina 0,6 mg/dL. Diante do exposto, qual seria a conduta adequada?","options":{"A":"Internar o paciente para início do tratamento, por possuir 4 pontos no escore de prognóstico\n\"\"CURB-65\"\".","B":"O paciente pode realizar o tratamento ambulatorial por possuir apenas 1 ponto no escore de\nprognóstico \"\"CURB-65\"\".","C":"Apesar de o paciente ter somente 1 ponto no escore de prognóstico \"\"CURB-65\"\", devido às\ncomorbidades e ao seu contexto social, a conduta mais adequada é interná-lo para o tratamento.","D":"O paciente pode realizar o tratamento ambulatorial por possuir apenas 2 pontos no escore de\nprognóstico \"\"CURB-65\"\".","E":"Internar o paciente para início do tratamento, por possuir 3 pontos no escore de prognóstico\n\"\"CURB-65\"\"."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-349735","number":"349735","sourceNumber":"349735","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Dentre as alternativas a seguir, qual apresenta o agente infeccioso bacteriano mais\ncomum na pneumonia adquirida na comunidade?","options":{"A":"Streptococcus pneumoniae.","B":"Mycoplasma pneumoniae.","C":"Streptococcus aureus.","D":"Chlamydia pneumoniae.","E":"Pseudomonas aeruginosa."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-349753","number":"349753","sourceNumber":"349753","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Uma menina de cinco anos está em investigação por apresentar febre de origem não\nesclarecida há um mês, associada à perda de peso nas últimas semanas, sem outras queixas. Seu\npai, que morava na mesma casa, teve uma doença de pulmão, tratada por longo período, segundo\na pessoa que acompanha a menina. A radiografia de tórax apresenta imagens micronodulares\ndisseminadas. Ao exame físico: eupneica, ausculta pulmonar rude, com queixa de tosse eventual.\nA principal hipótese diagnóstica e orientação nesse caso serão:","options":{"A":"Histoplasmose pulmonar aguda / Fazer desinfecção do ambiente.","B":"Pneumonia atípica por vírus sincicial respiratório / Isolar por 15 dias.","C":"Tuberculose miliar pulmonar / Iniciar esquema preconizado.","D":"Pneumonia linfocítica intersticial / Broncoscopia.","E":"Pneumonia por Pneumocystis Carinii / Descolonizar com antibiótico via oral."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-365610","number":"365610","sourceNumber":"365610","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O diagnóstico da tuberculose na infância é um desafio. Ele baseia-se em uma\ncombinação de critérios clínicos,\nepidemiológicos, associados a teste imunológico não específico\nde infecção tuberculosa e à radiografia de tórax. Até o momento, não existe um método\nconsiderado padrão-ouro. De acordo com as recomendações do Ministério da Saúde para o\ncontrole da tuberculose no Brasil, assinale a alternativa correta.","options":{"A":"O diagnóstico de infecção latente pelo M. tuberculosis é feito por meio de dados\nclínico-radiológicos.","B":"A dosagem sanguínea de interferon gama (IGRA) possui acurácia e valores preditivos\nsemelhantes à prova tuberculínica, mas não está\nindicada em crianças menores de 2 anos de\nidade.","C":"Na infância, as formas extrapulmonares são mais frequentes do que as formas pulmonares.","D":"Nos adolescentes, os aspectos radiológicos mais encontrados são infiltrados ou consolidações\nnos terços inferiores dos pulmões."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-284280","number":"284280","sourceNumber":"284280","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A tuberculose é endêmica no Brasil e o aumento da sua incidência nas últimas décadas\nestá relacionado à epidemia do vírus HIV. A\nrespeito dessas patologias, julgue o item a seguir. O\nteste cutâneo com tuberculina (PPD) pode ser falso-positivo em pacientes com hanseníase e\n\nfalso-negativo em pacientes em uso de imunossupressores.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-274369","number":"274369","sourceNumber":"274369","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente, 70 anos, masculino, previamente hígido, foi admitido no pronto atendimento\ndevido a quadro de pneumonia bacteriana\ncomunitária, com sintomas de início há 2 dias. Evoluiu\ncom hipotensão severa, insuficiência respiratória e necessidade de intubação endotraqueal.\n\nApresentava PA: 80/40mmHg, FC: 115bpm, FR: 30ipm, SO2: 90% com máscara de alto fluxo de\nO2, sendo iniciados antibiótico de amplo\nespectro e medidas de ressuscitação volêmica. O paciente\nfoi encaminhado para a UTI, onde fez exames dentro das primeiras 6h de admissão que estão\nlistados a seguir. (Hemoglobina: 12,6mg/dL, hematócrito: 35,9%, bastões: 18%, ureia: 80 mg/dL,\ncreatinina: 1,5mg/dL, sódio: 138mEq/dL, cloro: 108mEq/dL, potássio: 4,7mEq/dL, ph:7,18, pCO2:\n50mmHg, pO2: 86mmHg, HCO3: 23mmol/L, BE:-3, lactato: 1,2mmol/dL, depuração de lactato: 8%,\nSvcO2:45). Sobre o caso apresentado, assinale a alternativa correta.","options":{"A":"O tratamento do quadro, após análise dos exames, é iniciar bicarbonato de sódio.","B":"Deve-se realizar ajuste dos parâmetros ventilatórios do paciente para aumentar a oferta de\noxigênio.","C":"Na estratégia guiada por objetivos, pode-se considerar o uso de dobutamina.","D":"A acidose metabólica do paciente é sinal de disfunção de múltiplos órgãos.","E":"Deve-se suspender a hidratação, já que os exames mostram provável acidose hiperclorêmica\ndecorrente da hiper- hidratação."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-284308","number":"284308","sourceNumber":"284308","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Uma menina de um ano e oito meses de idade foi internada para tratamento de\npneumonia adquirida na comunidade, evoluindo de\nforma grave e permanecendo na UTI por quinze\ndias. Após retorno para a enfermaria, mantinha tosse, cansaço e imagem radiológica pulmonar\ninalterada. Foi realizado o PPD, que demonstrou valor de 12 mm. Na história familiar, o pai\napresentava tosse e emagrecimento há um mês e iniciara tratamento especifico há duas semanas\ne o irmão de quatro anos de idade era assintomático respiratório, com radiografia de tórax normal e\nPPD com valor de 5 mm. Com base nessa situação hipotética, julgue o item a seguir. Deve-se\niniciar isoniazida para o irmão da paciente, visando a tratar uma tuberculose latente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-284310","number":"284310","sourceNumber":"284310","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Uma menina de um ano e oito meses de idade foi internada para tratamento de\npneumonia adquirida na comunidade, evoluindo de\nforma grave e permanecendo na UTI por quinze\ndias. Após retorno para a enfermaria, mantinha tosse, cansaço e imagem radiológica pulmonar\ninalterada. Foi realizado o PPD, que demonstrou valor de 12 mm. Na história familiar, o pai\napresentava tosse e emagrecimento há um mês e iniciara tratamento especifico há duas semanas\ne o irmão de quatro anos de idade era assintomático respiratório, com radiografia de tórax normal e\nPPD com valor de 5 mm. Com base nessa situação hipotética, julgue o item a seguir. Deve-se\nrepetir o PPD do irmão da paciente em quatro semanas, para verificar viragem tuberculínica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-250078","number":"250078","sourceNumber":"250078","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um paciente de 72 anos de idade, diabético, foi admitido no departamento de\nemergência, sonolento, hipoativo, taquipneico e\nfebril. Familiares informaram tosse produtiva e\nhiporexia há quatro dias. Os sinais vitais aferidos no atendimento inicial mostraram pressão\narterial\nde 70 x 40 mmHg; frequência cardíaca de 126 batimentos por minuto, frequência respiratória de 28\nincursões por minuto, saturação periférica de oxigênio de 81% em ar ambiente, temperatura axilar\nde 39,1ºC e glicemia de 168 mg/dl. Ao exame físico, o paciente pontuava 6 na escala de coma de\nGlasgow, suas pupilas estavam isocóricas e fotorreagentes e a ausculta pulmonar era rude, com\ncrepitações predominantes em base pulmonar direita. O hemograma evidenciou leucocitose\n(21.000 leucócitos), com 14% de bastões. Com base nesse caso hipotético e nos conceitos\nmédicos a ele associados, julgue o item a seguir. O paciente pontua 2 no escore quick SOFA, o\nque confirma o diagnóstico de sepse.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-239252","number":"239252","sourceNumber":"239252","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um paciente de 25 anos de idade, HIV positivo, queixa-se de tosse produtiva e febre há\ncinco dias, com piora nos últimos três dias, apresentando também desconforto respiratório e dor\npleurítica à esquerda. Foi avaliado no pronto-socorro, onde se apresentava sudoreico, taquipneico\n(FR = 44 irpm), FC = 102 bpm, Sp02 = 94%. Na ausculta, havia estertores em terço médio do\npulmão direito e redução importante dos murmúrios na base direita. Foi realizada a radiografia de\ntórax, conforme imagem. Acerca desse caso clínico e com base nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Derrames parapneumônicos não complicados podem ser tratados\nde maneira conservadora, sem drenagem de tórax.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-250082","number":"250082","sourceNumber":"250082","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um paciente de 72 anos de idade, diabético, foi admitido no departamento de\nemergência, sonolento, hipoativo, taquipneico e\nfebril. Familiares informaram tosse produtiva e\nhiporexia há quatro dias. Os sinais vitais aferidos no atendimento inicial mostraram pressão\narterial\nde 70 x 40 mmHg; frequência cardíaca de 126 batimentos por minuto, frequência respiratória de 28\nincursões por minuto, saturação periférica de oxigênio de 81% em ar ambiente, temperatura axilar\nde 39,1ºC e glicemia de 168 mg/dl. Ao exame físico, o paciente pontuava 6 na escala de coma de\nGlasgow, suas pupilas estavam isocóricas e fotorreagentes e a ausculta pulmonar era rude, com\ncrepitações predominantes em base pulmonar direita. O hemograma evidenciou leucocitose\n(21.000 leucócitos), com 14% de bastões. Com base nesse caso hipotético e nos conceitos\nmédicos a ele associados, julgue o item a seguir. A presença de choque hemorrágico concomitante\nou isquemia miocárdica ativa é indicativa de transfusão de hemácias, mesmo em vigência de nível\nde hemoglobina maior que 7 g/dl.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-239279","number":"239279","sourceNumber":"239279","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Uma paciente de 73 anos de idade, residente na cidade do Rio de Janeiro-RJ, é\ndiabética e hipertensa. Negou história de\ntabagismo ativo ou passivo. Procurou atendimento de\nemergência por dispneia, tosse produtiva, febre de 39°C e dor torácica ventilatório-dependente. Ao\nexame físico, apresentava-se em regular estado geral, alerta, PA = 80 mmHg X 50 mmHg, FC =\n115 bpm, SatO2 = 91% em ar ambiente, FR = 26 irpm; ausculta respiratória com crepitantes\npulmonares à direita. Exames complementares: Hb = 13,3g/dL, Ht = 39%, leucócitos = 19.000/mm3\ne 15% de bastões, 177 mil plaquetas, ureia = 108mg/dL, Cr = 1,6mg/dL, raio X de tórax com\nconsolidação em lobo inferior direito. Quanto ao caso clínico apresentado e tendo em vista os\nconhecimentos médicos correlatos, julgue o item a seguir. O germe Mycoplasma pneumoniae é o\nsegundo patógeno mais comumente isolado em casos como o citado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-239281","number":"239281","sourceNumber":"239281","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Uma paciente de 73 anos de idade, residente na cidade do Rio de Janeiro-RJ, é\ndiabética e hipertensa. Negou história de\ntabagismo ativo ou passivo. Procurou atendimento de\nemergência por dispneia, tosse produtiva, febre de 39°C e dor torácica ventilatório-dependente. Ao\nexame físico, apresentava-se em regular estado geral, alerta, PA = 80 mmHg X 50 mmHg, FC =\n115 bpm, SatO2 = 91% em ar ambiente, FR = 26 irpm; ausculta respiratória com crepitantes\npulmonares à direita. Exames complementares: Hb = 13,3g/dL, Ht = 39%, leucócitos = 19.000/mm3\ne 15% de bastões, 177 mil plaquetas, ureia = 108mg/dL, Cr = 1,6mg/dL, raio X de tórax com\nconsolidação em lobo inferior direito. Quanto ao caso clínico apresentado e tendo em vista os\nconhecimentos médicos correlatos, julgue o item a seguir. Com base no escore de gravidade\n(CURB-65), essa paciente possui mortalidade em torno de 31%.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-239282","number":"239282","sourceNumber":"239282","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Uma paciente de 73 anos de idade, residente na cidade do Rio de Janeiro-RJ, é\ndiabética e hipertensa. Negou história de\ntabagismo ativo ou passivo. Procurou atendimento de\nemergência por dispneia, tosse produtiva, febre de 39°C e dor torácica ventilatório-dependente. Ao\nexame físico, apresentava-se em regular estado geral, alerta, PA = 80 mmHg X 50 mmHg, FC =\n115 bpm, SatO2 = 91% em ar ambiente, FR = 26 irpm; ausculta respiratória com crepitantes\npulmonares à direita. Exames complementares: Hb = 13,3g/dL, Ht = 39%, leucócitos = 19.000/mm3\ne 15% de bastões, 177 mil plaquetas, ureia = 108mg/dL, Cr = 1,6mg/dL, raio X de tórax com\nconsolidação em lobo inferior direito. Quanto ao caso clínico apresentado e tendo em vista os\nconhecimentos médicos correlatos, julgue o item a seguir. O tratamento com antibiótico macrolídeo\né a escolha inicial para esse caso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-239368","number":"239368","sourceNumber":"239368","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Uma paciente de 58 anos de idade, hipertensa, com história de mau controle,\nobesidade grau 1, dislipidêmica, tabagista\n40 anos/maços, com histórico de participação sem\nsucesso em programa de abandono ao tabagismo, é atendida em consulta de acolhimento em\nUnidade de Saúde da Família, após dois anos da última consulta agendada. Alega que procura\natendimento em razão da dor de intensidade grau quatro em hemitórax anterior esquerdo há dois\ndias, contínua, sem irradiações, realizando \"sinal do apontamento\" para demonstrar local exato da\ndor, sem fator gatilho ou fator de piora notados. Além disso, relata que vem apresentando tosse\nnão produtiva frequente há um mês, sem febre, dispneia, emagrecimento ou demais\ncomemorativos. Não vem fazendo uso das respectivas medicações, alegando que se esquece de\nadministrá-las. Leva boletim de atendimento em consulta realizada há duas semanas em unidade\nde pronto atendimento em razão da dor lombar, mostrando receita de corticoide intramuscular\nfornecida na alta, medicação da qual admite fazer uso com certa frequência, afirmando que esta\nsempre lhe é prescrita quando consulta na UPA. Mostra também exames realizados, há dois\nmeses, solicitados em consulta médica em clínica popular, com os seguintes resultados: Hb = 13,2\ng/dl, Ht = 37,1%, leucócitos = 7,2 mil, plaquetas = 148 mil, Cr = 1,1 mg/dl, Ur = 42 mg/dl,\ncolesterol\ntotal = 270 mg/dl, HDL = 38 mg/dl, LDL =192 mg/dl, triglicerídeos = 198 mg/dl e glicemia de jejum =\n123 mg/dl. Com relação a esse caso clínico e tendo em vista os conhecimentos médicos correlatos,\njulgue o item a seguir. Há indicação de pesquisa de BAAR em pelo menos duas amostras de\nescarro, em razão de a paciente enquadrar-se nos critérios de sintomático respiratório.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-211974","number":"211974","sourceNumber":"211974","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"No pronto-socorro de clínica médica, um adolescente entra com quadro de asma grave.\nCom base nas evidências atuais, o médico\nexplica à mãe do paciente que as infecções virais são\ncomuns nesse tipo de exacerbação, mas, pela gravidade da situação, não pode ser descartada\numa infecção por bactérias atípicas. Considerando-se esse caso clínico e os conhecimentos\nmédicos correlatos, entre as bactérias atípicas referidas, é correto citar as duas mais comuns, que\nsão","options":{"A":"Mycoplasma sp. e Chlamydophila sp.","B":"Pseudomonas sp. e Acinetobacter sp.","C":"Morganella sp. e Haemophilus sp.","D":"Proteus sp. e E. Coli.","E":"Legionella sp. e Staphylococcus sp."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-211997","number":"211997","sourceNumber":"211997","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Determinado paciente de 28 anos de idade nega tabagismo, apresenta PA = 100\nmmHg x 60 mmHg, FC = 92 bpm, FR = 21 ipm e\nSatO? = 94%, e tem manifestado, ao longo de\nquatro a seis semanas, perda de peso e anemia, apresentando também fadiga, tosse produtiva\ncom escarro purulento, de odor pútrido, febre e pleurisia. A tomografia de tórax revelou áreas de\ncavitação com níveis hidroaéreos, com regiões de desenvolvimento de abscessos. Acerca desse\ncaso clínico, e considerando os conhecimentos médicos correlatos, assinale a alternativa correta.","options":{"A":"O tratamento do abscesso pulmonar, nesse caso, independentemente de continuidade da febre,\npode ser feito com antibioticoterapia por 7\ndias a 10 dias, por se tratar de pneumonia.","B":"Trata-se de um abscesso pulmonar agudo em paciente jovem previamente saudável, não sendo\nprovável o envolvimento de Staphylococcus aureus.","C":"É imunocomprometida pela história clínica; portanto, não há envolvimento de bacilos\nGram-negativos como Klebsiella pneumonia.","D":"Nesse caso de abscesso pulmonar, não é uma opção de tratamento de escolha o uso de\nclindamicina.","E":"É um caso de abscesso pulmonar inespecífico e, em sua maioria, é causado por bactérias\nanaeróbias."},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-211948","number":"211948","sourceNumber":"211948","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um paciente de 74 anos de idade queixa-se de dor abdominal em Fossa Ilíaca Direita\n(FID) há três dias; ontem procurou\natendimento na Unidade de Pronto Atendimento (UPA), próxima\nà respectiva casa, e recebeu alta após medicação. Hoje o paciente chegou ao hospital de\nreferência da cidade queixando-se de piora da dor abdominal e inapetência. Foi realizada TC de\nabdome total com contraste e identificada colecistite complicada com perfuração da vesícula biliar e\npresença de grande quantidade de líquido livre na cavidade. O bloco cirúrgico do hospital em\nquestão encontra-se em obras, e o paciente necessitou de ser transferido para realização de\nlaparotomia de urgência; entretanto, a transferência demorou cerca de 12 horas, fazendo com que\no paciente tivesse uma piora do estado geral e entrasse em um quadro de choque (PA = 80 mmHg\nx 40 mmHg; FC = 130 bpm; FR = 31 irpm; TAX = 38,5°C). Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, no que tange aos diversos tipos de choque, assinale a\nalternativa correta.","options":{"A":"Esse paciente apresenta um quadro de provável choque cardiogênico em consequência da\nperda volêmica importante.","B":"Esse paciente apresenta um quadro de provável choque séptico de foco abdominal.","C":"Esse paciente tem indicação absoluta de transfusão sanguínea.","D":"Mesmo que o paciente responda à ressuscitação volêmica, com aumento da PA e redução da\nFC, há indicação absoluta de utilização de medicação vasopressora.","E":"Infarto agudo do miocárdio (IAM) não pode ser considerado causa de choque cardiogênico."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-179199","number":"179199","sourceNumber":"179199","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Uma paciente de 88 anos de idade, em uso de 10 mg ao dia de prednisona devido à\nasma e bronquiectasia, está utilizando\nantibioticoterapia de largo espectro, há mais de dez dias, por\napresentar infecção do trato urinário (ITU). Encontra-se com quadro de queda do estado geral,\nconfusão mental, desnutrição, leve taquipneia, ausculta respiratória com roncos em base e\nausência de febre. Com base nessa situação hipotética, o diagnóstico provável da paciente será","options":{"A":"ITU por Escherichia coli resistente.","B":"ITU por Proteus ou klebsiella resistente.","C":"pneumonia por Pseudomonas aeruginosa.","D":"peneumonia por pneumococo.","E":"asma persistente e demência mista."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-177650","number":"177650","sourceNumber":"177650","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"J.A.S., sexo feminino, 24 anos de idade, teve diagnóstico de tuberculose durante o 3º\ntrimeste da gestação. Além desse fato, a gestação transcorreu sem intercorrências e o pré-natal\nocorreu com acompanhamento e exames normais. Nasceu C.A.S., com idade gestacional de 38\nsemanas e 3 dias, sem sinais clínicos de patologias. Considerando o caso clínico apresentado e os\nconhecimentos médicos correlatos, julgue o item a seguir. Para a prevenção de infecção latente no\nrecém-nascido, usa-se, como droga de escolha, a isoniazida.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-177655","number":"177655","sourceNumber":"177655","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"J.A.S., sexo feminino, 24 anos de idade, teve diagnóstico de tuberculose durante o 3º\ntrimestre da gestação. Além desse fato, a gestação transcorreu sem intercorrências e o pré-natal\nocorreu com acompanhamento e exames normais. Nasceu C.A.S., com idade gestacional de 38\nsemanas e 3 dias, sem sinais clínicos de patologias. Considerando o caso clínico apresentado e os\nconhecimentos médicos correlatos, julgue o item a seguir. O teste de Mantoux (PPD) deve ser\nrealizado por ocasião do nascimento, podendo-se vacinar a criança com BCG, se o PPD for menor\nque 5 mm.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-177660","number":"177660","sourceNumber":"177660","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"J.A.S., sexo feminino, 24 anos de idade, teve diagnóstico de tuberculose durante o 3º\ntrimeste da gestação. Além desse fato, a gestação transcorreu sem intercorrências e o pré-natal\nocorreu com acompanhamento e exames normais. Nasceu C.A.S., com idade gestacional de 38\nsemanas e 3 dias, sem sinais clínicos de patologias. Considerando o caso clínico apresentado e os\nconhecimentos médicos correlatos, julgue o item a seguir. O uso de isoniazida deve ser mantida\nsempre por 6 meses.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-177666","number":"177666","sourceNumber":"177666","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"J.A.S., sexo feminino, 24 anos de idade, teve diagnóstico de tuberculose durante o 3º\ntrimeste da gestação. Além desse fato, a gestação transcorreu sem intercorrências e o pré-natal\nocorreu com acompanhamento e exames normais. Nasceu C.A.S., com idade gestacional de 38\nsemanas e 3 dias, sem sinais clínicos de patologias. Considerando o caso clínico apresentado e os\nconhecimentos médicos correlatos, julgue o item a seguir. Caso haja uma pessoa vivendo com\nHIV/AIDS na moradia de J.A.S. e não haja disponibilidade de PPD, deve-se realizar o tratamento\nde infecção latente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-177593","number":"177593","sourceNumber":"177593","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"J.A.S., sexo feminino, 24 anos de idade, teve diagnóstico de tuberculose durante o 3º\ntrimestre da gestação. Além desse fato, a gestação transcorreu sem intercorrências e o pré-natal\nocorreu com acompanhamento e exames normais. Nasceu C.A.S., com idade gestacional de 38\nsemanas e 3 dias, sem sinais clínicos e patologias. Considerando o caso clínico apresentado e os\nconhecimentos médicos correlatados, julgo o item a seguir. Na ausência de PPD, C.A.S. deve\nreceber isoniazida por 12 meses.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-177601","number":"177601","sourceNumber":"177601","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"J.A.S., sexo feminino, 24 anos de idade, teve diagnóstico de tuberculose durante o 3º\ntrimestre da gestação. Além desse fato, a gestação transcorreu sem intercorrências e o pré-natal\nocorreu com acompanhamento e exames normais. Nasceu C.A.S., com idade gestacional de 38\nsemanas e 3 dias, sem sinais clínicos e patologias. Considerando o caso clínico apresentado e os\nconhecimentos médicos correlatados, julgue o item a seguir. A abordagem em relação à rede de\napoio da paciente e ao entendimento acerca da doença não são variáveis a serem consideradas na\navaliação da capacidade da paciente em aderir ao tratamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-152069","number":"152069","sourceNumber":"152069","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O paciente J. O. C., de 75 anos de idade, chega ao serviço de pronto atendimento com\ndor aguda, cansaço, fraqueza muscular e\nsensação de câimbra nos pés após caminhada de duas\nquadras, obrigando-o a parar, sem melhora após alguns minutos em repouso. Relata histórico\ncirúrgico por dissecção aguda da aorta torácica. Ao exame: REG, corado, hidratado, TAX = 37 °C,\nFC = 100 bpm, FR = 21 irpm, índice tornozelo-braquial (ITB) 0,26. Lesão ulcerosa em MID sem\nsinais de infecção. Exames indicam leucócitos 8.000 células/mm³ sem desvio. O paciente foi\nsubmetido a operação vascular, evoluindo com febre no POI e infecção do sítio cirúrgico (ISC),\nposteriormente. Com relação a esse caso clínico, julgue o item a seguir. O paciente em questão\ndeu entrada já em sepse, pois apresentava dois ou mais dos seguintes sinais: temperatura (central)\nacima de 38 °C ou abaixo de 36 °C; frequência cardíaca > 90 bpm; frequência respiratória > 20\nrespirações/min em pacientes ventilando espontaneamente ou PaCO2 < 32 mmHg; leucócitos >\n\n12.000 células/mm³ ou < 4.000 células/mm³ ou > 10% de células jovens (bastonetes) no sangue\nperiférico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-135075","number":"135075","sourceNumber":"135075","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A respeito de prevenção e tratamento das doenças infecciosas, julgue o item a seguir.\nA tuberculose peritoneal se manifesta mais\nfrequentemente em pessoas idosas, do sexo feminino,\nprovenientes de áreas endêmicas para essa doença e portadoras de HIV. Os pacientes com\ntuberculose que apresentam quadro de obstrução intestinal devem ser tratados com laparotomia\nexploradora, sendo importante, nesses casos, realizar enterectomia dos segmentos isolados\nestenosados.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-108146","number":"108146","sourceNumber":"108146","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A respeito das doenças infecciosas, julgue o item seguinte. Para o diagnóstico da\ntuberculose pleural, indica-se a realização de toracocentese. O líquido é considerado transudato\npor apresentar aumento tanto da atividade do ADA acima de 40 U/L quanto da celularidade, a\nglicose normal ou ligeiramente aumentada em relação à dosagem sérica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-79657","number":"79657","sourceNumber":"79657","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A Tomografia Computadorizada de Alta Resolução (TCAR) é uma ferramenta crítica\npara a avaliação das doenças pulmonares. Ao\nverificar o remodelamento do pulmão em favo de\nmel (faveolamento), reflete-se o estágio terminal de um número de doenças que causam destruição\ndo parênquima. Com base nos critérios de diagnóstico com TCAR e vendo imagens bem definidas\nde faveolamento, é possível sugerir Fibrose Pulmonar Idiopática, excluindo o seguinte critério\nepidemiológico:","options":{"A":"Idade < que 50 anos.","B":"Excesso de citocinas fibrogênicas.","C":"Resultado anormal em teste de função pulmonar.","D":"Doenças de colágeno vascular.","E":"Uso de drogas fibrogênicas."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-82052","number":"82052","sourceNumber":"82052","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A respeito das doenças infecciosas e de seus aspectos epidemiológicos, julgue o item a\nseguir: A taxa de incidência da tuberculose em 2012 apresentou uma queda de quase 20% em\nrelação a 2002, sendo as populações indígenas, os presidiários, os moradores de rua e os\nportadores do vírus HIV os mais vulneráveis à doença.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-88625","number":"88625","sourceNumber":"88625","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"No que se refere a doenças infecciosas, julgue o item a seguir. Na primoinfecção\ntuberculosa, não há manifestação clínica da\ndoença, visto que o sistema imunológico do indivíduo\nmantém controlada a infecção.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-64680","number":"64680","sourceNumber":"64680","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Uma doença que pode acometer a criança na infância é a tuberculose. Em relação às\ndrogas e dosagens que podem respectivamente ser usadas para o tratamento desta patologia em\ncrianças nesta faixa etária, analise as proposições abaixo: I. Isoniazida 5 a 10 mg/Kg/dia; II.\nRifampicina 10 a 20 mg/kg/dia; III. Pirazinamida 25 a 40 mg/kg/dia; IV. Etambutol 1.200 mg/kg/dia;\n\nV. Etionamida 10 a 20 mg/kg/dia. É correto o que se apresenta em:","options":{"A":"I, apenas.","B":"II e IV, apenas.","C":"III , IV e V, apenas.","D":"I, II, III e IV, apenas.","E":"I, II, III e V, apenas."},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-27531","number":"27531","sourceNumber":"27531","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A implantação do novo esquema de tratamento para Tuberculose (4 em 1) se\ncaracteriza pela introdução:","options":{"A":"do Etambutol no Esquema I, na fase de manutenção (4 meses).","B":"de derivados de Pleuromutilina no Esquema IR (Reforçado).","C":"do Etambutol no Esquema I, na fase intensiva (2 meses).","D":"da Rifampicina no Esquema III, no lugar da Etionamida.","E":"da Estreptomicina no Esquema I, por 6 meses."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-7534","number":"7534","sourceNumber":"7534","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"São medidas preventivas da Tuberculose a quimioprofilaxia e a Vacina BCG. Quanto a\nesse assunto, assinale a alternativa correta:","options":{"A":"A quimioprofilaxia é feita com isoniazida na dose máxima de 400 mg/dia durante 6 meses.","B":"A quimioprofilaxia está indicada para HIV positivos que apresentem PPD maior ou igual a 5 mm,\ndesde que descartada a tuberculose doença.","C":"A BCG está indicada para pacientes submetidos à quimioterapia antineoplásica.","D":"A BCG protege os indivíduos infectados e não infectados pelo M. tuberculosis.","E":"A BCG é feita em recém nascidos no Brasil com peso >2,5kg."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-7537","number":"7537","sourceNumber":"7537","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um pedreiro de 48 anos de idade, desempregado, apresentando tosse há mais de\nquatro semanas, fez exame de escarro e o\nresultado foi baciloscopia positiva (++/++++). Refere ter\ninterrompido tratamento para tuberculose há aproximadamente oito meses, por ter se sentido\nmelhor. Considerando as normas do Programa Nacional de Controle de Tuberculose, assinale a\nalternativa correta.","options":{"A":"O caso desse pedreiro deve ser considerado caso novo de tuberculose.","B":"Para confirmação diagnóstica, deve ser realizada radiografia de tórax.","C":"A suspeita de tuberculose baseou-se no fato de ser sintomático respiratório, ou seja, apresentar\ntosse há mais de dez dias.","D":"O abandono ao esquema de tratamento aumenta o risco de desenvolver casos de multidroga\nresistência-TB MDR.","E":"O tratamento deve ser feito em hospital para garantir acesso a exames complementares e\nmedicamentos tuberculostáticos."},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-366230","number":"366230","sourceNumber":"366230","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Uma mulher de 42 anos de idade apresenta queixa de \"\"anemia de longa data\"\". À\nrevisão de sistemas, relata episódios\nrecorrentes de epistaxe espontâneas desde a infância, com\nmúltiplas idas ao Pronto Atendimento, especialmente em dias de clima seco. A paciente informa ter\ntratado a anemia anteriormente com diferentes reposições de sulfato ferroso, mas sem alcançar a\ncura. Destaca que considera isso normal, pois seu pai, irmãos e sobrinha enfrentam quadros\nsemelhantes. Quanto aos antecedentes, não apresenta comorbidades prévias. No exame físico,\nobserva-se palidez cutaneomucosa e a presença de várias telangiectasias cutâneas, algumas\nlocalizadas nas palmas das mãos e plantas dos pés, além de afetar a mucosa oral conforme\nimagem acima. Considerando o quadro clínico apresentado, bem como os assuntos correlatos,\nJulgue o item a seguir. Embora seja rara Actinomicose do sistema nervoso central, abcessos\ncerebrais únicos ou múltiplos são os mais comuns e a condição clínica do paciente aumenta o risco\nde abcessos cerebrais por Actinomyces como potencial agente etiológico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-343388","number":"343388","sourceNumber":"343388","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Considerando os tipos dos aspectos do escarro e suas possíveis causas, é CORRETO\nafirmar:","options":{"A":"Mucopurulento: carcinoma de células alveolares.","B":"Geleia de framboesa: pneumonia estreptocócica.","C":"Róseo com bolhas de ar: edema pulmonar.","D":"Sanguíneo: infecção por Klebsiella Pneumoniae."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-334877","number":"334877","sourceNumber":"334877","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um paciente de 20 anos de idade, previamente saudável, procurou o pronto-socorro\ninformando apresentar, há dois dias, quadro clínico\nconstituído por febre de 38 ºC, associada a dor\ntorácica respiratório-dependente à esquerda e tosse com eliminação de secreção amarelada. A\nradiografia de tórax mostrou consolidação em língula. O exame físico revelou crepitações\ninspiratórias em região axilar esquerda, pressão arterial de 80 mmHg x 40 mmHg, SatO2 = 90%,\nFR = 32 irpm e FC = 110 bpm. Acerca do caso clínico, assinale a alternativa correta.","options":{"A":"O tratamento desse paciente só deve ser iniciado após o resultado do teste rápido do exame de\nescarro para bactérias e vírus.","B":"Há necessidade de serem feitos exames complementares para melhor estabelecer a gravidade\ndo quadro clínico do paciente.","C":"Os dados obtidos com a história clínica, o exame físico e a radiografia de tórax são suficientes\npara o estabelecimento do diagnóstico.","D":"O uso de corticoide sistêmico deve ser evitado, pois pode agravar a condição clínica do\npaciente.","E":"Os critérios clínicos identificados indicam que o tratamento deve ocorrer em ambiente de\nunidade de terapia intensiva pela necessidade de se iniciar ventilação mecânica."},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-343409","number":"343409","sourceNumber":"343409","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Com relação ao choque séptico em criança, é CORRETO afirmar:","options":{"A":"O uso de drogas vasoativas deve ser evitado no tratamento do choque séptico.","B":"O choque quente caracteriza-se por extremidades aquecidas, pulsos amplos e rápidos e\nenchimento capilar rápido.","C":"A hipotensão é um sinal precoce de disfunção cardiovascular na criança em choque séptico.","D":"O choque frio pode se apresentar por extremidades frias, enchimento capilar prolongado por\nmenos de 2 segundos e pulsos de fácil palpação."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-307089","number":"307089","sourceNumber":"307089","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um paciente de 26 anos de idade, morador de rua e usuário de drogas (maconha e\ncrack), deu entrada na emergência por causa\nde dispneia, dor torácica, ventilatório-dependente do\nlado direito, febre, perda ponderal, sudorese noturna e tosse. Nega outras doenças. Com base no\nexame apresentado de raios X de tórax desse paciente, o achado radiológico é:","options":{"A":"Derrame pleural à direita.","B":"Atelectasia do lobo inferior esquerdo.","C":"Pneumotórax à esquerda.","D":"Pneumomediastino.","E":"Tromboembolismo pulmonar."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-268892","number":"268892","sourceNumber":"268892","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Uma paciente de 28 anos de idade compareceu à emergência com queixa de dor\nabdominal em região hipogástrica, de forte\nintensidade, urgência miccional e disúria importante. O\nquadro teve início há aproximadamente 24 horas e, há 12 horas, a paciente apresentou febre,\naferida em 38,8ºC. Referiu urina escura e em pequeno volume nas últimas 12 horas. Os ciclos\nmenstruais estavam normais. Ao exame clínico, a paciente apresentava-se sonolenta, orientada,\ncorada, desidratada (+), febril (38,5ºC), com enchimento capilar periférico em cinco segundos,\nabdome sem alterações relevantes, punho percussão positiva à direita, PA = 90 mmHg x 60 mmHg,\nFC = 118 bpm, FR = 26 irpm e SatO2 = 94%. Acerca da conduta para essa paciente, assinale a\nalternativa CORRETA.","options":{"A":"Solicitar exames laboratoriais para confirmação de sepse; caso os resultados sejam positivos,\nabrir o protocolo de sepse, priorizando coleta\nde culturas, antibioticoterapia e hidratação com\ncristaloides.","B":"Abrir imediatamente o protocolo de sepse, priorizando coleta de culturas, antibioticoterapia e\nhidratação com cristaloides, e solicitar os exames confirmatórios já com o protocolo em andamento.","C":"Colher gasometria arterial e culturas e iniciar antibioticoterapia de amplo espectro; caso o\nlactato\nvenha positivo, abrir o protocolo de sepse e iniciar hidratação vigorosa com cristaloides.","D":"Abrir imediatamente o protocolo de sepse, priorizando coleta de culturas, antibioticoterapia e\nhidratação com coloides, e solicitar os exames confirmatórios já com o protocolo em andamento.","E":"Abrir imediatamente o protocolo de sepse, solicitar culturas e exames confirmatórios já com o\nprotocolo em andamento e iniciar antibióticos após o resultado definitivo das culturas."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-263355","number":"263355","sourceNumber":"263355","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um homem com 54 anos de idade, transplantado renal há 3 meses, apresenta, há\ncerca de 7 dias, febre elevada (> 40°C),\ntosse pouco produtiva (escarro pouco purulento) e dor\ntorácica à esquerda. Ele procurou o serviço onde realizou o transplante de órgão, sendo observada\na presença de febre elevada e ausculta pulmonar com estertores crepitantes difusos, além de\nsemiologia compatível com derrame pleural à esquerda. O Gram de escarro não mostrou\npatógenos, mas apenas alguns polimorfonucleares. A Tomografia Computadorizada de Tórax\n(TCT), realizada no mesmo dia, revelou opacidades alveolares arredondadas e derrame pleural\nleve à esquerda. Como o paciente respondeu bem à administração de antitérmico, mantendo bom\nestado hemodinâmico e padrão respiratório satisfatório, foi liberado para casa com prescrição de\namoxicilina-clavulanato. No entanto, após 4 dias de tratamento, mantinha-se febril, sem melhora do\nquadro clínico. Nova TCT revelou que algumas das opacidades parenquimatosas haviam evoluído\ncom escavação central. Foi formulada a hipótese de pneumonia por Legionella pneumophila. Em\nfunção de o paciente estar em tratamento imunossupressor com ciclosporina e tacrolimus, qual é o\ntratamento antimicrobiano adequado a ser prescrito?","options":{"A":"Sulfametoxazol-trimetoprim.","B":"Levofloxacino.","C":"Azitromicina.","D":"Doxiciclina."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-273345","number":"273345","sourceNumber":"273345","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente de 34 anos, tabagista, vítima de acidente automobilístico há 10 dias. Internado\ninicialmente na unidade de trauma por tórax instável em ventilação mecânica. Após melhora inicial,\nevolui com piora respiratória e febre persistente. TC de tórax realizada na ocasião demonstrou\nextensa consolidação pneumônica em base e terço médio do pulmão direito. Realizadas culturas de\nsangue, urina e do lavado broncoalveolar protegido e iniciado esquema antimicrobiano empírico\ncom meropenem e linezolida. Após cerca de 3 dias o paciente permanece febril, sem parâmetros\nobjetivos de melhora do padrão ventilatório. Duas hemoculturas e a cultura da secreção traqueal\nsão finalizadas com crescimento de Pseudomonas aeruginosa multissensível e Stenotrophomonas\nmaltophilia. Neste momento qual a melhor conduta?","options":{"A":"Manter esquema antimicrobiano.","B":"Associar Polimixina.","C":"Associar Doxiciclina e suspender a Linezolida.","D":"Associar Sulfametoxazol/Trimetoprim, suspender linezolida."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-291511","number":"291511","sourceNumber":"291511","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um paciente de 35 anos de idade, vivendo com HIV/AIDS há alguns anos, sem adesão\nà terapia antirretroviral indicada (TARV), é\ninternado em hospital de média complexidade com\nquadro de tosse produtiva, febre e dor torácica, associados à imagem radiológica compatível com\ncondensação em base direita, sendo iniciado tratamento com amoxicilina-clavulanato. Revendo os\nexames de admissão do paciente, o médico que o atende percebe que o infiltrado radiológico evolui\ncom áreas de cavitação, o que o leva a considerar a hipótese diagnóstica de tuberculose pulmonar\natípica, decorrente da presença de imunossupressão. Visando a proceder à investigação\ndiagnóstica indicada no caso, a recomendação atual da Organização Mundial de Saúde é que o\nteste diagnóstico de 1.ª linha para tais pacientes com doença pulmonar ativa, tendo ainda a\nvantagem de detectar resistência antimicrobiana, seria","options":{"A":"pesquisa de bacilo álcool-ácido resistente no escarro.","B":"realização de ensaio de liberação de gama-interferon no sangue periférico.","C":"amplificação automatizada de ácido nucleico (ensaio Xpert MTB/RIF) no escarro.","D":"cultura de escarro (meio de Lowenstein-Jensen)."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-291523","number":"291523","sourceNumber":"291523","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um homem, com 20 anos de idade, desempregado, reside em casa de madeira com\num cômodo junto com o pai, mãe e 5 irmãos. Ele\nprocurou a unidade de saúde da família, com\nqueixa de tosse, febre e dispneia há mais ou menos 2 meses, inicialmente aos esforços e,\nposteriormente, em repouso. Nega Tuberculose (TB) anterior. Relata que o pai teve tuberculose,\nporém abandonou o tratamento 2 vezes. Há 6 meses, foi solicitado investigação dos contatos,\nconsiderando o reingresso após abandono do tratamento do pai, porém nenhum dos membros da\nfamília compareceu à unidade para avaliação clínica e/ou realizou os exames. No atendimento de\nhoje, o paciente realizou teste rápido (lgM/lgG) para covid-19 com resultado negativo. Aplicando as\nevidências científicas, preceitos éticos e legais, assinale a afirmativa com a melhor conduta.","options":{"A":"Realizar avaliação clínica, coletar e encaminhar 3 amostras de escarro para realizar baciloscopia\nde escarro, teste molecular rápido para a TB\n(TMR-TB) e cultura de escarro, solicitar raio-X, realizar\no teste rápido para o HIV, orientar o uso de máscara de tecido, agendar nova consulta e investigar\nos contatos.","B":"Realizar avaliação clínica, coletar e encaminhar 3 amostras de escarro para realizar baciloscopia\nde escarro, teste molecular rápido para a TB\n(TMR-TB) e cultura de escarro, solicitar raio-X, realizar\no teste rápido para o HIV, orientar o uso de máscara de cirúrgica, investigar os contatos e\nencaminhar o paciente para o serviço de referência.","C":"Realizar avaliação clínica, coletar e encaminhar 2 amostras de escarro para realizar teste\nmolecular rápido para a TB (TMR-TB) e cultura\nde escarro, solicitar raio-X, realizar teste rápido para\no HIV, orientar o uso de máscara cirúrgica, agendar nova consulta e investigar os contatos.","D":"Realizar avaliação clínica, coletar e encaminhar 2 amostras de escarro para realizar baciloscopia\ne cultura de escarro, solicitar raio-X,\nrealizar teste rápido para o HIV, orientar o uso de máscara\n\nN-95, agendar nova consulta e investigar os contatos."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-266490","number":"266490","sourceNumber":"266490","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Wilson, de 63 anos de idade, negro, aposentado, procurou uma Unidade Básica de\nSaúde (UBS) na região administrativa de São\nSebastião, por apresentar tosse havia 4 semanas,\nfebre vespertina e um episódio de hemoptise. Luísa, médica recém-formada, o atendeu no\nconsultório reservado para casos suspeitos de covid-19. Wilson realizou o teste rápido IgG/IgM\npara SARS-CoV-2, que resultou positivo. Considerando que a sensibilidade do referido teste rápido\nseja de 80% e que a sua especificidade seja de 90%, julgue o item a seguir, referentes ao caso\nclínico apresentado. Havendo confirmação diagnóstica de tuberculose em Wilson, recomenda-se o\nrastreamento de HIV, que deverá ser consentido pelo paciente, observando-se o sigilo e a\nconfidencialidade e utilizando-se os algoritmos diagnósticos estabelecidos para esse fim.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-263426","number":"263426","sourceNumber":"263426","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um homem com 24 anos de idade comparece à Unidade de Saúde da Família do seu\nbairro. Há uma semana, iniciou quadro de tosse produtiva, febre de 38ºC e inapetência. Afirmou\nfazer uso regular de antirretrovirais para tratamento de HIV/aids há 2 anos. Houve emagrecimento\nde 5 kg nos últimos seis meses. Sem alterações na ausculta pulmonar e cardíaca ou nos demais\nitens do exame físico. Qual deve ser a conduta médica para a investigação diagnóstica desse\npaciente, além da solicitação de radiografia de tórax?","options":{"A":"Solicitar teste rápido molecular para tuberculose caso haja alteração na radiografia de tórax.","B":"Solicitar teste rápido molecular para tuberculose e, se negativo, indicar a cultura de escarro\ncom\nteste de sensibilidade.","C":"Solicitar teste rápido molecular para tuberculose e cultura de escarro com teste de sensibilidade\njá na primeira consulta.","D":"Solicitar teste rápido molecular para tuberculose e cultura de escarro com teste de sensibilidade\nsomente se resistência à rifampicina."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-291550","number":"291550","sourceNumber":"291550","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um paciente masculino, 33 anos de idade, agricultor, é internado com quadro de\ncansaço, adinamia, tosse, emagrecimento\nimportante nos últimos 6 meses (cerca de 14 kg). Ao\nexame, mostra-se emagrecido, mucosas pouco coradas, ausculta pulmonar com murmúrio\nvesicular preservado, estertores bilaterais. Tomografia de tórax apresenta lesões em brotamento\ncom suspeita de tuberculose pós-primária. Diante desse caso, quais são, respectivamente, o\ndiagnóstico diferencial, o exame a ser solicitado para confirmação da tuberculose e o tratamento a\nser instituído?","options":{"A":"Pneumonia por estafilococo; solicitar pesquisa de BK e fungo em escarro; iniciar tratamento com\nrifampicina.","B":"Pneumonia por paracoccidioidomicose; solicitar biópsia tran-brônquica; iniciar rifampicina,\nisoniazida, pirazinamida.","C":"Pneumonia por estafilococo; solicitar lavado bronco alveolar para pesquisa de BK; iniciar\nrifampicina e pirazinamida.","D":"Pneumonia por paracoccidioidomicose; solicitar pesquisa de BK e fungo no escarro; iniciar\nrifampicina, isoniazida, pirazinamida."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-244468","number":"244468","sourceNumber":"244468","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um motorista de 63 anos de idade desenvolveu um quadro de dor torácica\n\nventilatório-dependente em hemitórax direito com tosse produtiva associada a febre, a tremores, a\ncalafrios e a mal-estar. Nega náuseas e vômitos. É tabagista de dois maços de cigarro por dia nos\núltimos 50 anos, hipertenso leve não controlado e obeso mórbido. Os sinais vitais são os seguintes:\npressão arterial = 90 mmHg x 60 mmHg, frequência cardíaca = 112 bpm, frequência respiratória =\n28 irpm, Tax = 38 ºC, saturação de O2 em ar ambiente = 89%. Encontra-se lúcido e orientado. A\nausculta pulmonar revela murmúrios vesiculares diminuídos no hemitórax direito, associado a\nsubmacicez à percussão ipsilateral. Aos exames laboratoriais, observaram-se HB = 14 (VR =\n\n12-16), HT = 46 (VR = 36 - 45), leucócitos = 17.000 / mm3 (VR = 4.000 - 12.000), neutrófilos = 70%\n\n(VR = 20-60), bastonetes = 15% (VR = 0- 3%), plaquetas = 230.000 (VR = 140 a 450.000). A\n\nradiografia de tórax evidenciou consolidação em lobo médio direito com sinais de broncograma\naéreo. Com base nesse quadro clínico nos\nconhecimentos médicos relacionados à pneumonia\nadquirida na comunidade (PAC), assinale a alternativa correta.","options":{"A":"Apesar da vasta variedade microbiota respiratória, da ampla disseminação de agentes\npotencialmente patogênicos, do fenômeno da\nglobalização e da ocorrência de epidemias virais, o\nStaphylococcus sp permanece como a bactéria de maior prevalência de PAC entre os agentes\netiológicos.","B":"Os escores de prognóstico disponíveis para PAC dimensionam a necessidade de investigação\netiológica, para a melhor escolha do\nantibiótico e sua via de administração. No caso do paciente\ndescrito, a escolha recomendada seria meropenem associado a vancomicina.","C":"Esse paciente apresenta 1 ponto no escore CURB-65 (ou menos 1 no escore CRB-65 ou 80\npontos no PSI); assim, o tratamento ambulatorial deve ser indicado.","D":"O uso de procalcitonina e (ou) proteína C reativa pode ser aplicado na avaliação da resposta ao\ntratamento, evidenciando que a procalcitonina é um bom biomarcador para predizer mortalidade\nrelacionada a PAC.","E":"A ultrassonografia (US) à beira do leito, realizada por clínicos no serviço de emergência\nmédica,\n\napresenta uma sensibilidade de 95% contra 60% da tomografia de tórax para PAC. A\nespecificidade é semelhante para os dois\nmétodos diagnósticos. Assim, o paciente deveria ter\nrealizado US ao invés da radiografia."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-230563","number":"230563","sourceNumber":"230563","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O tratamento em todos os casos de influenza é baseado em sintomáticos. Deve-se\nrecomendar todas as alternativas abaixo, EXCETO:","options":{"A":"Repouso.","B":"Restrição hídrica.","C":"Analgésicos e antitérmicos.","D":"Fluidificação de secreções."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-230570","number":"230570","sourceNumber":"230570","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Assinale a alternativa INCORRETA sobre o vírus influenza e as condutas relacionadas\na ele:","options":{"A":"A síndrome respiratória aguda grave é a febre de início súbito associada a sintomas\nrespiratórios.","B":"A síndrome respiratória aguda grave é a síndrome gripal associada a sinais de gravidade, como\ndesconforto respiratório e hipotensão.","C":"No Brasil, a vacinação contra influenza é administrada na rede pública, em campanhas anuais\npara indivíduos que pertençam a grupos de risco e profissionais de saúde.","D":"O oseltamivir é a medicação de escolha no Brasil para tratamento de influenza e deve ser\niniciado nas primeiras 48 horas de sintomas, quando indicado."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-227448","number":"227448","sourceNumber":"227448","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Com relação às demandas de saúde na atenção primária à saúde (APS), relacionadas\nàs doenças infecciosas e transmissíveis, julgue\no item que se segue. Reação adversa grave às\npenicilinas é comum, por isso, para a segurança do paciente, ao administrar esse medicamento na\nAPS, o médico deve manter o paciente em observação na unidade básica de saúde (UBS), até que\nse descarte o risco de anafilaxia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-230625","number":"230625","sourceNumber":"230625","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Estima-se que em 2015 cerca de 10,4 milhões de pessoas desenvolveram Tuberculose\n(TB), 580 mil na forma de TB Multirresistente\n(TB MDR) ou TB Resistente à Rifampicina (TB RR), e\n1,4 milhão morreram da doença. Os pilares e componentes da Estratégia pelo Fim da Tuberculose\nsão listados abaixo, indique a alternativa ERRADA:","options":{"A":"Prevenção e cuidado integrado e centrado no paciente.","B":"Diagnóstico precoce","C":"Teste de sensibilidade antimicrobiano universal.","D":"Investigação sistemática dos contatos e das populações menos vulneráveis."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-227451","number":"227451","sourceNumber":"227451","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Com relação às demandas de saúde na atenção primária à saúde (APS), relacionadas\nàs doenças infecciosas e transmissíveis, julgue\no item que se segue. A Organização Mundial da\nSaúde (OMS) estima que um quarto da população mundial tenha infecção latente por tuberculose\n(ILTB), condição em que a pessoa, mesmo infectada, permanece saudável por anos, com\nimunidade parcial ao bacilo, sem apresentar sintomas, mas com transmissibilidade baixa do bacilo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-230633","number":"230633","sourceNumber":"230633","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Estudos sugerem que o adoecimento por TB resulta da relação entre determinantes\nprovenientes de diferentes níveis, podemos apenas CONCORDAR que:","options":{"A":"Determinantes a comunidade e ambiente domiciliar, mas não características individuais.","B":"Os padrões de vida em uma comunidade conformam a posição socioeconômica domiciliar.","C":"Oportunidades individuais em termos de educação, ocupação, qualidade da habitação e\ninterações sociais não interagem.","D":"A transmissão e adoecimento por TB não são influenciados por fatores demográficos, sociais e\neconômicos."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-230638","number":"230638","sourceNumber":"230638","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A probabilidade de uma pessoa ser infectada depende de fatores exógenos. Assim,\nsomente podemos determinar como ERRADA a alternativa:","options":{"A":"Entre eles, pode-se citar a infectividade do caso-fonte, a duração do contato e o tipo de\nambiente partilhado.","B":"Os pacientes com exame bacteriológico de escarro positivo não sustentam a cadeia de\ntransmissão da doença.","C":"Estima-se que uma pessoa com baciloscopia positiva infecte de 10 a 15 pessoas em média, em\numa comunidade, durante um ano.","D":"Entre pessoas que têm contatos duradouros com pacientes com TB pulmonar, aqueles com\nBAAR positivo no escarro são os que mais\ntransmitem a doença."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-206119","number":"206119","sourceNumber":"206119","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A radiografia de tórax é um método complementar importante na investigação da\ndoença e deve ser solicitada para todo\npaciente com suspeita clínica de tuberculose pulmonar. Em\ncasos raros, mesmo existindo a doença, a radiografia do paciente pode não apresentar alterações.\nSendo INADEQUADO que:","options":{"A":"Diferentes achados radiológicos apontam para a suspeita de doença em atividade ou anterior.","B":"Existem diversas imagens radiológica patognomônicas de tuberculose.","C":"Sempre devem ser realizados exames laboratoriais comprobatórios.","D":"As principais funções do exame radiológico em pacientes com baciloscopia positiva são excluir\noutra doença pulmonar associada e avaliar a extensão do acometimento e sua evolução\nradiológica, sobretudo nos pacientes que não respondem ao tratamento antituberculose."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-203127","number":"203127","sourceNumber":"203127","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um paciente fumante de 56 anos de idade, com histórico de hipertensão arterial e\ninsuficiência cardíaca leve, vai ao serviço de emergência em razão de tosse produtiva, febre e\ndispneia ao repouso. O quadro clínico iniciou há uma semana com febre, dor muscular, dor\nabdominal difusa e diarreia sem muco, pus ou sangue com três dias de duração. Realizou raios X\nde tórax que evidenciam sinais de broncopneumonia em base pulmonar direita. Considerando esse\ncaso clínico, assinale a alternativa que indica o microrganismo para qual se deve iniciar o\ntratamento antimicrobiano.","options":{"A":"Chlamydia pneumoniae.","B":"Legionella pneumophila.","C":"Mycoplasma pneumoniae.","D":"Aspergillus fumigatus.","E":"Candida albicans."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-203109","number":"203109","sourceNumber":"203109","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Uma criança de 11 meses de vida tem histórico de febre há dois dias. Os pais\n\nlevaram-no ao pronto-socorro, pois, desde o início do quadro, observaram que o filho não os estava\nreconhecendo, além de apresentar sono agitado ao longo do dia. Hoje, associado ao quadro,\niniciou episódios de vômitos e de recusa alimentar. Ao exame, percebe-se peso de 10 kg, fontanela\nabaulada, sem sinais meníngeos. Pálido, sonolento e desidratado. FC = 185 bpm, PA = 55 mmHg x\n35 mmHg, FR = 38 irpm, SpO? = 93% em ambiente, temperatura axilar = 35,5°C. Ausculta\ncardiopulmonar sem alteração, com tiragem subcostal leve. Abdome normotenso. Pulsos centrais\ncom média amplitude e pulsos periféricos filiformes. Tempo de enchimento capilar de 4 segundos.\nConsiderando o caso clínico, o diagnóstico mais provável e os sinais/sintomas que o caracterizam\nsão:","options":{"A":"síndrome da resposta inflamatória sistêmica - taquicardia (FC > 180 bpm) e hipotermia\n(temperatura < 36 °C).","B":"Sepse - taquipneia (FR > 34 irpm) e hipotensão (pressão arterial média < 60 mmHg).","C":"Síndrome da resposta inflamatória sistêmica - taquicardia (FC > 180 bpm) e hipotensão (pressão\narterial média < 60 mmHg).","D":"Sepse - taquicardia (FC > 180 bpm) e hipotermia (temperatura < 36 °C).","E":"Síndrome da resposta inflamatória sistêmica - taquipneia (FR > 34 irpm) e hipotensão (pressão\narterial medida < 60 mmHg)."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-206090","number":"206090","sourceNumber":"206090","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação à pneumonia pós-operatória:","options":{"A":"Os pacientes cirúrgicos são particularmente suscetíveis à pneumonia, principalmente aqueles\nque necessitam de ventilação mecânica.","B":"A pneumonia associada à ventilação mecânica é aquela que ocorre de 48-72 horas após a\nintubação endotraqueal.","C":"É a infecção mais comum nas UTIs entre pacientes cirúrgicos e traumáticos.","D":"A pneumonia associada à ventilação mecânica é definida como tardia quando ela ocorre em\nmais de 7 dias após a intubação."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-225148","number":"225148","sourceNumber":"225148","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um menino de 4 anos de idade foi encaminhado ao ambulatório de pediatria porque\nsua mãe havia sido recém-diagnosticada com\ntuberculose pulmonar, com tratamento iniciado havia\n3 semanas. Na consulta, a criança apresentava sinais\n\ngripais com tosse seca e coriza hialina havia 10 dias, sem febre. O cartão vacinal estava completo\ne, no exame físico, foi constatada apenas a\npresença de coriza e de cicatriz de bacilo de\n\nCalmette-Guérin (BCG). O pediatra solicitou radiografia de tórax e derivado proteico purificado\n(PPD). O resultado da radiografia foi normal,\nao passo que o do PPD foi de 4 mm. Com relação a\nesse caso clínico, julgue o item que se segue. Considerando os sinais e sintomas respiratórios\napresentados\n\npela criança, deve-se iniciar o tratamento de tuberculose com o esquema RIPE (esquema 1 do\nMinistério da Saúde).","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-212101","number":"212101","sourceNumber":"212101","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um menino de 4 anos de idade foi encaminhado ao ambulatório de pediatria porque\nsua mãe havia sido recém-diagnosticada com\ntuberculose pulmonar, com tratamento iniciado havia\n3 semanas. Na consulta, a criança apresentava sinais gripais com tosse seca e coriza hialina havia\n10 dias, sem febre. O cartão vacinal estava completo e, no exame físico, foi constatada apenas a\npresença de coriza e de cicatriz de Bacilo de Calmette-Guérin (BCG). O pediatra solicitou\nradiografia de tórax e derivado proteico purificado (PPD). O resultado da radiografia foi normal, ao\npasso que o do PPD foi = 4 mm. Com relação a esse caso clínico, julgue o item que se segue. A\ncriança deve ser isolada dos outros familiares e afastada da escola, pelo risco de estar com\ntuberculose pulmonar, na forma bacilífera, que ocorre na sua faixa etária.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-212103","number":"212103","sourceNumber":"212103","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um menino de 4 anos de idade foi encaminhado ao ambulatório de pediatria porque\nsua mãe havia sido recém-diagnosticada com\ntuberculose pulmonar, com tratamento iniciado havia\n3 semanas. Na consulta, a criança apresentava sinais gripais com tosse seca e coriza hialina havia\n10 dias, sem febre. O cartão vacinal estava completo e, no exame físico, foi constatada apenas a\npresença de coriza e de cicatriz de Bacilo de Calmette-Guérin (BCG). O pediatra solicitou\nradiografia de tórax e Derivado Proteico Purificado (PPD). O resultado da radiografia foi normal, ao\npasso que o do PPD foi de 4 mm. Com relação a esse caso clínico, julgue o item que se segue.\n\nDeve ser solicitada uma baciloscopia do escarro para afastar o diagnóstico de tuberculose na\nreferida criança.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-206114","number":"206114","sourceNumber":"206114","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Para prevenção da transmissão da tuberculose nas unidades de saúde, devem ser\nimplementadas nas unidades de saúde as seguintes etapas. Determine qual está INCORRETA:","options":{"A":"Reconhecer o Sintomático Respiratório SR ou paciente com TB pulmonar ativa é o primeiro\npasso nas medidas administrativas. Pode ser\nobtido com a preparação de um profissional de saúde\npara realizar a busca ativa de SR em todo paciente que chega à unidade, interrogando a presença\ne duração da tosse.","B":"Oferecer ao SR máscara cirúrgica para uso durante sua permanência na unidade e instruí-lo\ncom relação à etiqueta da tosse (levar o braço ou\nlenço à boca quando tossir).","C":"SR ou pacientes com TB de vias aéreas em atividade ainda infectantes devem esperar\natendimentos ou procedimentos em áreas fechadas ventiladas.","D":"Priorizar o atendimento do paciente no serviço, independentemente do motivo da procura. O\npaciente deve passar à frente na fila de consultas, exames e/ou dispensa de medicamentos."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-206146","number":"206146","sourceNumber":"206146","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"As medidas de proteção individual consistem no uso correto de máscaras adequadas,\npor profissionais de saúde, em situações e ambientes\nde maior risco. Sendo INADEQUADO que:","options":{"A":"o uso de máscaras (respiradores) no atendimento de sintomático respiratório SR ou pacientes\ncom TB deve ser feito de forma criteriosa.","B":"muitos profissionais dedicam a esse item valor prioritário, negligenciando medidas\nadministrativas e de controle ambiental, que\ncertamente têm maior impacto na sua proteção e nos\ndemais pacientes.","C":"não podemos confiar nas máscaras tipo PFF2? padrão brasileiro e da União Europeia . Apenas\na N95 ? padrão dos Estados Unidos? é eficaz\npara a proteção de profissionais de saúde.","D":"as máscaras devem ser utilizadas somente em áreas de alto risco de transmissão, como quartos\nde isolamento respiratório, sala\n\nde escarro induzido."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-175084","number":"175084","sourceNumber":"175084","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A maioria dos pacientes com diagnóstico de PAC responde adequadamente ao\ntratamento, porém o chamado fracasso terapêutico\né um importante fator prognóstico na PAC, com\ntaxa de mortalidade importante, sendo INCORRETO a afirmativa:","options":{"A":"Sua relevância pode também ser mensurada por meio da morbidade associada ao fracasso\nterapêutico, traduzida pelo aumento\n\ndo tempo de internação hospitalar, pela necessidade de admissão em UTI.","B":"Não existe uniformidade na definição de fracasso terapêutico nos diferentes estudos.","C":"Em pacientes ambulatoriais, o fracasso não pode ser definido pela necessidade de internação\nhospitalar ou de modificação da antibioticoterapia inicial.","D":"Nos hospitalizados, o fracasso é definido como precoce ou tardio. O fracasso precoce é\ncaracterizado por insuficiência\nrespiratória com necessidade de ventilação mecânica e/ou presença\nde choque séptico nas primeiras 72h de internação."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-175086","number":"175086","sourceNumber":"175086","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Indivíduo com Síndrome Gripal (SG) apresenta febre de início súbito, acompanhada de\ntosse e dor de garganta, além de cefaleia e mialgia. Sendo assim, é CORRETO afirmar que:","options":{"A":"Além dos medicamentos sintomáticos e da hidratação, não está indicado o uso de fosfato de\noseltamivir (Tamiflu®) para todos os casos de SG que tenham poucas condições e fatores de risco\npara complicações.","B":"Dependentemente da situação vacinal, quando em atendimento ambulatorial está indicado o\ntratamento com fosfato de oseltamivir (Tamiflu®).","C":"Esta indicação fundamenta-se no benefício que a terapêutica precoce proporciona, tanto na\nredução da duração dos sintomas quanto na\nocorrência de complicações da infecção pelos vírus da\ninfluenza, em pacientes com condições e fatores de risco para complicações.","D":"Em pacientes com condições e fatores de risco para complicações e com SRAG, o antiviral\nainda apresenta benefícios, mesmo se iniciado após\n72 horas do início dos sintomas."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-175096","number":"175096","sourceNumber":"175096","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A diminuição do tempo de tratamento com antimicrobianos, quando bem indicado,\napenas não promove o seguinte item:","options":{"A":"Reduz a exposição de pacientes com PAC a antibióticos.","B":"Ocorre que limita o risco de indução de resistência.","C":"Reduz os custos.","D":"Piora a adesão ao tratamento por não o valorizar adequadamente."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-183924","number":"183924","sourceNumber":"183924","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Acerca das infecções e suas implicações clínico-cirurgícas, julgue o próximo item. A\ntuberculose pulmonar gera, com frequência, a dissociação clínico-radiológica, situação\ncaracterizada pela existência de sinais e sintomas clínicos exuberantes e ausência de alterações\nsignificativas nos exames de imagem do tórax.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-183903","number":"183903","sourceNumber":"183903","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Com relação ao tratamento das doenças infecciosas e parasitárias, julgue o item que se\nsegue. São exemplos de efeitos maiores ? aqueles que implicam interrupção ou alteração do\nregime terapêutico ? no tratamento da tuberculose: nefrite tubulointersticial associada ao uso de\netambutol; rabdomiólise com mioglobinúria e insuficiência renal associada ao uso de isoniazida; e\nneuropatia periférica decorrente do uso de pirazinamida.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-177240","number":"177240","sourceNumber":"177240","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A respeito das medidas de bloqueio e de rastreio epidemiológico relativas à\ntuberculose, assinale a alternativa correta.","options":{"A":"Quando houver recém-nascido de mulher diagnosticada com tuberculose bacilífera durante a\ngestação, tal criança deve receber vacina BCG ao nascer e receber tratamento com isoniazida por\n3 meses, seguido por prova tuberculínica, para se definir a continuidade do tratamento.","B":"Recém-nascidos de mãe HIV positiva, mas sem sintomas da Aids, devem receber a vacina BCG\nao nascer.","C":"No caso de recém-nascido de mãe com tuberculose bacilífera, caso não haja prova tuberculínica\ndisponível, o tratamento com isoniazida\ndeve ser realizado por 6 meses.","D":"Moradores do mesmo domicílio que paciente com tuberculose bacilífera que possuam\ninsuficiência renal em tratamento dialítico\ndevem ser submetidos ao tratamento da infecção latente\nse a prova tuberculínica for de 5 mm.","E":"O uso de insulina é fator de risco definidor no tratamento ou não da infecção latente."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-175146","number":"175146","sourceNumber":"175146","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Além dos medicamentos e da hidratação, é recomendado o uso de Fosfato de\nOseltamivir. Esta indicação fundamenta-se no\nbenefício que a terapêutica proporciona em\npacientes com condições e fatores de risco para complicações. Sobre isso, assinale a alternativa\nINCORRETA:","options":{"A":"Os benefícios do uso do antiviral fosfato de oseltamivir para pacientes de SG e SRAG suspeitos\npara influenza já foram amplamente comprovados\npor estudos clínicos, observados no manejo\nclínico de pacientes durante a pandemia de 2009 e reforçados no protocolo da Organização\nPanamericana da Saúde (OPAS) e Organização Mundial da Saúde (OMS), além de consultas\nreferendadas pelas sociedades médicas brasileiras e especialistas da área.","B":"Além dos medicamentos sintomáticos e da hidratação, está indicado o uso de fosfato de\noseltamivir para todos os casos de SG que\ntenham condições e fatores de risco para complicações,\ndependentemente da situação vacinal, mesmo em atendimento ambulatorial.","C":"Esta indicação do uso de fosfato de oseltamivir fundamenta-se no benefício que a terapêutica\nprecoce proporciona, tanto na redução da duração dos\nsintomas quanto na ocorrência de\ncomplicações da infecção pelos vírus da influenza, em pacientes com condições e fatores de risco\npara complicações.","D":"Em pacientes com condições e fatores de risco para complicações e com SRAG o antiviral ainda\napresenta benefícios, mesmo se iniciado após 48 horas do início dos sintomas."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-175178","number":"175178","sourceNumber":"175178","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Quando um vírus influenza animal infecta seu hospedeiro animal natural, ele é\ndenominado de acordo com o hospedeiro, sendo\nvírus influenza aviário, vírus influenza suíno, vírus\ninfluenza equino, etc. Assim, o termo ?gripe suína? se refere a vírus influenza suíno infectando\nsuínos e nunca a esse vírus infectando humano. Sendo inadequado apenas a seguinte alternativa:","options":{"A":"Humanos também podem se infectar com vírus influenza que circulam rotineiramente em\nanimais, como os subtipos de vírus influenza aviários A(H5N1) ou A(H7N9). Outras espécies,\nincluindo cavalos e cachorros, também possuem seus subtipos de vírus influenza A.","B":"Os vírus influenza animais não são distintos dos vírus influenza humanos e são transmitidos\nfacilmente entre humanos. Alguns ocasionalmente\ninfectam humanos, podendo causar infecções\ncom complicações graves e inclusive óbito. Geralmente infecções humanas com um vírus influenza\nzoonótico são adquiridas por meio de contato direto com animais infectados ou ambientes\ncontaminados.","C":"Se um vírus zoonótico adquire a capacidade de se disseminar pessoa a pessoa, por meio de\nadaptação ou rearranjo, ele se torna capaz de iniciar uma epidemia ou uma pandemia. Ao longo\ndas décadas passadas, houve várias ocasiões de transmissão esporádica de vírus influenza de\nanimais para humanos.","D":"Quando um subtipo de vírus influenza A (H3N2), circulante de suínos, começou a infectar\nhumanos nos Estados Unidos em 2011, ele\nrecebeu o termo ?variante? (com um ?v? colocado\napós o nome do vírus) com o intuito de distinguir dos vírus humanos do mesmo subtipo. A\nterminologia ?variante? é usada apenas para outros vírus influenza não sazonais de um mesmo\nsubtipo de vírus influenza sazonal humano, particularmente os vírus H1 e H3 circulantes em suínos\nquando detectados em humanos."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-168462","number":"168462","sourceNumber":"168462","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Uma criança com 4 anos de idade, cujos pais são diagnosticados com tuberculose\npulmonar, está em acompanhamento em unidade\nbásica de saúde. Ela apresenta cartão vacinal\ncompleto, crescimento e desenvolvimento adequados e está assintomática. Realizou radiografia de\ntórax, que não apresentou alteração, e o teste tuberculínico (PPD), que apresentou enduração de 5\n\nmm. Considerando-se o quadro clínico dessa criança, o tratamento da tuberculose latente\n(quimioprofilaxia):","options":{"A":"Deverá ser realizado, pois ela apresenta enduração do PPD de 5 mm e ausência de tuberculose.","B":"Não deverá ser realizado, pois a presença dessa enduração está relacionada à vacina BCG.","C":"Deverá ser realizado, pois os pais são bacilíferos e estão em tratamento para tuberculose.","D":"Não deverá ser realizado, pois, para isso, a enduração deveria ser de pelo menos 10 mm."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-168471","number":"168471","sourceNumber":"168471","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um homem com 38 anos de idade, portador de diabete melito tipo 1 desde os 12 anos,\nsem tratamento regular de sua doença de base,\nfoi admitido no centro de tratamento intensivo em\nrazão de quadro de sepse grave. Segundo relato de familiar, o paciente iniciou, há cerca de 4 dias,\nquadro de tosse produtiva e febre alta. Fez uso de sintomáticos (mucolítico e antitérmico) sem obter\nmelhora. Há 24 horas, passou a apresentar diminuição importante do débito urinário e, há 3 horas,\nprostração e rebaixamento do nível de consciência. O exame físico demonstra temperatura axilar =\n\n38.6ºC; frequência cardíaca = 112 bpm; frequência respiratória = 33 irpm (com tiragem intercostal)\ne pressão arterial = 68 x 40 mmHg. Solicitados\nexames complementares de urgência, o\nhemograma revela 26.000 leucócitos/mm³ (valor de referência: 4.000 a 10.000/mm³) e 16% bastões\n(valor de referência: 0 a 5%). Diante desse quadro, a conduta inicial apropriada deve ser:","options":{"A":"Colher hemoculturas e iniciar imediatamente ressuscitação volêmica e antibioticoterapia\ndirecionada a germes atípicos com claritromicina.","B":"Colher hemoculturas e iniciar imediatamente ressuscitação volêmica e antibioticoterapia\nintravenosa de amplo espectro com ceftriaxona e\nazitromicina.","C":"Colher secreção traqueal para bacterioscopia e cultura e solicitar tomografia computadorizada\nde tórax de alta resolução, para definir esquema\nantibiótico.","D":"Colher secreção traqueal para bacterioscopia e cultura e solicitar radiografia de tórax em AP no\nleito, aguardando resultados para início da antibioticoterapia."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-158059","number":"158059","sourceNumber":"158059","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Nos últimos anos, há grandes dificuldades na atenção primária à saúde no que tange a\nabordagem de contactantes de pacientes com tuberculose bacilífera na ausência do teste\ntuberculínico (PPD). Considerando os conhecimentos de medicina preventiva e a Nota Informativa\nnº 8/2014, CGPNTC/DEVEP/SVS/MS, assinale a alternativa CORRETA quanto à abordagem de\nneonatos de mãe bacilífera.","options":{"A":"Havendo disponibilidade de PPD, indica-se não vacinar com BCG ao nascer, tratar com\nisoniazida por seis meses e realizar PPD após para avaliar resposta.","B":"Havendo disponibilidade de PPD, não se deve vacinar com BCG ao nascer, e sim tratar com\nisoniazida por três meses e realizar PPD. Caso PPD > 5 mm, iniciar esquema RIP.","C":"Na ausênia de PPD, os neonatos devem ser tratados com isoniazida por três meses e apenas\napós serem vacinados com BCG.","D":"Na ausência de PPD, os neonatos devem realizar esquema RIP por três meses e depois devem\nser vacinados com BCG, apenas.","E":"Na ausência de PPD, os neonatos devem receber tratamento com isoniazida por seis meses e\nvacinação com BCG apenas após o tratamento."},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-168453","number":"168453","sourceNumber":"168453","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um menino com 8 anos de idade foi encaminhado ao setor de emergência de um\nhospital pelo Corpo de Bombeiros. À\nadmissão, a mãe do menino relata que, há 3 dias, ele\ncomeçou a ter febre de 39 °C e tosse produtiva, com expectoração amarelada. Refere, ainda, que a\ncriança apresentou piora significativa do estado geral nas últimas 24 horas, com redução do débito\nurinário. Ao exame físico, encontrava-se torporoso, taquicárdico, taquidispneico, hipotenso, com\npulsos finos, extremidades frias e cianóticas e enchimento capilar de 5 segundos. Os exames e\nrespectivos resultados são apresentados a seguir: hemograma: leucócitos = 24.000/mm³ (valor de\nreferência: 4.000 a 10.000/mm³), bastões = 15%, segmentados = 50%. Gasometria: alcalose\nrespiratória. Radiografia de tórax: condensação em todo pulmão direito. Nesse caso, nos primeiros\n10 minutos, além de iniciar oxigenoterapia e antibioticoterapia, a conduta em relação ao acesso e à\nexpansão volumétrica deve ser:","options":{"A":"Venoso central; soro glicofisiológico a 40 ml/kg.","B":"Venoso central; soro fisiológico a 40 ml/kg.","C":"Intraósseo; soro glicofisiológico a 20 ml/kg.","D":"Intraósseo; soro fisiológico a 20 ml/kg."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-111341","number":"111341","sourceNumber":"111341","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Mulher de 33 anos chega À unidade básica de saúde encaminhada por unidade de\nurgência. Entrega um receituário com prescrição do início de tratamento de tuberculose. A\nradiografia de tórax mostra cavitação de dois cm de diâmetro em ápice de hemitórax direito, e\nexame de pesquisa do bacilo álcool-ácido resistente positivo (BAAR +++). O peso da paciente não\nestá anotado. A conduta correta segundo o Programa Nacional de Controle da Tuberculose é:","options":{"A":"Reiniciar a investigação com a realização de uma cultura deescarro.","B":"Encaminhá-la para a farmácia para a dispensação da medicação (auto-administrado),\nagendar retorno em 30 dias e buscar todos os contatos domiciliares.","C":"Reinvestigar o caso buscando confirmação clínica epidemiológico, realizar a\nnotificação compulsória na suspeita da doença e investigar os contatos domiciliares.","D":"Realizar acolhimento e avaliação clínica adequada, iniciar o uso do tratamento diretamente\nobservado (supervisionado), notificar o caso e investigar os contatos.","E":"Reencaminhar a paciente para a unidade de\nemergência solicitando relatório consubstanciado."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-97807","number":"97807","sourceNumber":"97807","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um paciente com 24 anos de idade, estudante universitário, procura unidade básica de\nsaúde referindo, há dois dias, febre alta de\ninício súbito, dor torácica na inspiração profunda e tosse\nprodutiva com expectoração amarelada. Nega antecedentes patológicos significativos. Ao exame, o\npaciente apresenta-se lúcido; orientado; com mucosas normocoradas, normo-hidratadas,\nescleróticas anictéricas. Aparelho respiratório: murmúrio vesicular audível, exceto em terço médio\nde hemitórax direito, onde ausculta-se um sopro tubário. Verifica-se aumento do frêmito toracovocal\nnessa mesma região. Aparelho cardiovascular: ritmo cardíaco regular em dois tempos com bulhas\nnormofonéticas, sem sopros. Abdome flácido, ausência de visceromegalias. Membros inferiores\nsem alterações. Sinais vitais: pressão arterial = 120 x 80 mmHg; frequência respiratória = 24 irpm;\nfrequência cardíaca = 98 bpm e temperatura axilar = 39,0°C. A radiografia de tórax realizada no\natendimento é mostrada abaixo. (VER IMAGEM) A conduta terapêutica mais adequada para essa\npaciente é:","options":{"A":"Cefalexina por via oral.","B":"Azitromicina por via oral.","C":"Levofloxacino por via oral ou endovenosa.","D":"Ceftriaxona endovenosa ou intramuscular + azitromicina por via oral."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-80701","number":"80701","sourceNumber":"80701","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em relação às manifestações clínicas da tuberculose, é CORRETO afirmar que:","options":{"A":"A maioria dos casos de tuberculose primária (complexo primário) é assintomática.","B":"A tosse, quando ocorre, é sempre bem produtiva.","C":"A presença de eritema nodoso afasta a possibilidade de tuberculose.","D":"Caracteristicamente não há ruídos adventícios pulmonares.","E":"Ao RX de tórax há velamento bilateral de ápices na maioria dos casos."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-97826","number":"97826","sourceNumber":"97826","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um paciente com 45 anos de idade, casado e com três filhos (8 meses, 7 anos e 12\nanos de idade), trabalhador da construção\ncivil, tem histórico de febre vespertina, tosse e\nemagrecimento há seis meses. Radiografia de tórax mostra infiltrado em lobo superior direito\ncontendo cavitação e a baciloscopia do escarro é positiva para tuberculose. Em relação à avaliação\ndos contatos do paciente, é correto afirmar que:","options":{"A":"Nos contatos crianças (< 10 anos), a Prova Tuberculínica menor que 5 mm exclui o diagnóstico\nde tuberculose.","B":"Nos contatos crianças (< 10 anos), assintomáticos, o tempo de vacinação com BCG é fator\nimportante na definição da conduta.","C":"Nos contatos adultos ou adolescentes (>10 anos ), assintomáticos, não há necessidade de\nsolicitação da Prova Tuberculínica.","D":"Nos contatos sintomáticos adultos, o diagnóstico de tuberculose é estabelecido pela cultura de\nescarro positiva para Bacilo de Koch (BK)."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-97793","number":"97793","sourceNumber":"97793","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um paciente com 42 anos de idade é atendido no ambulatório de uma Unidade Básica\nde Saúde com quadro de tosse com expectoração\namarelada há mais de três semanas,\nacompanhada de febre vespertina. É submetido à realização de exame de escarro para pesquisa\nde bacilos álcool-ácido-resistentes (BAAR), que é positiva (+++/4+). Informa que reside com a\nesposa, que apresenta os mesmos sintomas. O casal não tem filhos. Diante dessas informações, a\ninvestigação da esposa deverá ser feita com","options":{"A":"realização de prova tuberculínica.","B":"solicitação de radiografia de tórax e PPD.","C":"encaminhamento para tratamento em posto de saúde.","D":"solicitação de radiografia de tórax e baciloscopia de escarro."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-75461","number":"75461","sourceNumber":"75461","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Mulher com 68 anos de idade foi trazida à Emergência por apresentar quadro de febre\nde até 39°C, mialgias, cefaleia, tosse seca,\ndispneia e piora do estado geral há três dias, com piora\nnas últimas seis horas. Ao exame encontra-se acordada, orientada, com frequência respiratória =\n30 irpm, pressão arterial = 100 x 60 mmHg, frequência cardíaca = 115 bpm, oximetria digital = 86%,\nem ar ambiente. Sem outras alterações ao exame físico. A radiografia de tórax mostra infiltrado\nintersticial bilateral. A paciente foi transferida para a Unidade de Terapia Intensiva em quarto\nprivativo e foi iniciada reposição volêmica. Qual a conduta inicial indicada para esta paciente?","options":{"A":"Iniciar oxigenoterapia, colher três amostras de\nhemocultura aeróbia e iniciar azitromicina.","B":"Colher secreção respiratória para PCR viral, prescrever oxigenoterapia e oseltamivir.","C":"Iniciar ventilação mecânica não invasiva, colher material para exame bacteriológico e iniciar\noseltamivir.","D":"Iniciar ventilação mecânica invasiva com circuito fechado como medida de isolamento\nrespiratório e prescrever zanamivir.","E":"Colher material para PCR para H1N1 e prescrever medidas de suporte, já que a paciente\napresenta sintomas há mais de 48 horas."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-75507","number":"75507","sourceNumber":"75507","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem de 34 anos de idade foi submetido, há cinco dias, a correção cirúrgica de\núlcera perfurada. Vem evoluindo com vômitos\ndesde a operação, acompanhados de dor abdominal\ndifusa e distensão abdominal, que se acentuaram nas últimas seis horas. No momento\n\napresenta-se desidratado, com frequência cardíaca = 132 bpm, pressão arterial = 80x40 mmHg,\ntemperatura axilar = 38,7 ºC. Está em uso de metronidazol na dose de 500 mg de 6/6 horas,\ngentamicina - 240 mg em\n\ndose única dia e ampicilina - 1g de 6/6 horas, além de omeprazol - 40 mg de 12/12 horas. Diante do\npresente quadro, a melhor conduta é:","options":{"A":"solicitar radiografia de abdome, mudar esquema\nantibiótico e transferir paciente para unidade de\ncuidados críticos.","B":"encaminhar para a unidade de cuidados críticos,\n\nmudar esquema antibiótico e puncionar acesso venoso central.","C":"chamar o cirurgião responsável, instituir reposição\nvolêmica e reservar vaga em unidade de cuidados\ncríticos.","D":"solicitar tomografia abdominal, mudar esquema\nantibiótico e instituir reposição volêmica.","E":"chamar o cirurgião responsável, mudar esquema\nantibiótico e instituir reposição volêmica."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-75541","number":"75541","sourceNumber":"75541","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Mulher com 57 anos de idade, portadora de diabetes tipo II não controlada, apresenta\nquadro de febre associada a dor, edema e\neritema de limites mal definidos em coxa esquerda,\nmedindo 20 cm em seu maior diâmetro. Ao exame físico: temperatura axilar = 38,9° C, FC = 110\nbpm, FR = 21 irpm, PA = 120 x 70 mmHg. Entre as opções abaixo, que exame laboratorial é\nindicativo da gravidade do comprometimento tecidual no quadro infeccioso?°","options":{"A":"Leucometria.","B":"Lactato sérico.","C":"Haptoglobina.","D":"Ferritina sérica.","E":"Proteína C reativa."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-75543","number":"75543","sourceNumber":"75543","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Mulher de 33 anos de idade, desempregada, refere dor à deglutição há 2,5 semanas,\ncom piora acentuada há três dias. Tem tido um\npico de febre diária há uma semana, que coincidiu\ncom uma discreta irritação e embaçamento visual no olho esquerdo. Refere ser portadora do vírus\nHIV há onze anos. Tem histórico de tratamento prévio para pneumonia por Pneumocystis jirovecii.\nApresentava placas esbranquiçadas na mucosa jugal, sem outros achados significativos. O\nhemograma inicial mostrava uma pancitopenia, e a endoscopia digestiva alta mostrou o esôfago\ncom erosões lineares, confluentes, recobertas por fibrina, ocupando toda a circunferência do órgão\ne gastrite enantematosa. Qual a medicação mais adequada para esta paciente?","options":{"A":"Fluconazol.","B":"Ganciclovir.","C":"Pantoprazol.","D":"Sulfametoxazol + trimetoprima.","E":"Zidovudina + lamivudina."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-75488","number":"75488","sourceNumber":"75488","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A Unidade Básica de Saúde de uma pequena cidade é responsável pela atenção a um\nasilo municipal. Em uma das visitas ao asilo, o médico atende um homem de 78 anos de idade com\nquadro de tosse produtiva há aproximadamente um mês. O paciente dorme em um quarto com\noutros três idosos, e, na instituição, vivem ao todo 23 idosos. Já fez uso de antialérgico e\nazitromicina - 500 mg por 5 dias, sem melhora. Após coleta de escarro, é feito diagnóstico de\ntuberculose pulmonar e iniciado tratamento. Qual a conduta a ser adotada em relação aos\ncontactantes?","options":{"A":"Os três idosos que dividem o quarto com o paciente índice devem ser tratados para tuberculose.","B":"Todos os contatos devem coletar duas amostras de escarro para exame de BAAR.","C":"Somente os sintomáticos respiratórios devem ser investigados para tuberculose.","D":"Contatos assintomáticos devem realizar prova\ntuberculínica.","E":"Todos os contatos devem realizar raio-X de tórax."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-137596","number":"137596","sourceNumber":"137596","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Na Unidade Básica de Saúde (UBS), após o diagnóstico de tuber culose\n(BAAR+++), a mãe de uma criança com sete\nanos de idade, iniciou o tratamento. A criança\nnão apresenta\n\nsintomatologia e foi vacinada com BCG ao nascer. Qual a conduta mais adequada a ser\nseguida em relação à criança?","options":{"A":"Solicitar baciloscopia de escarro e, se o exame for negativo,\nrecomendar\n\nreavaliação em seis meses.","B":"Solicitar baciloscopia de escarro, exame\n\nradiológico do tórax e prova tuberculínica e, se todos forem negativos ou normais, dar alta para a\ncriança.","C":"Solicitar prova\n\ntuberculínica e, se superior a 10 mm, iniciar o tratamento completo com os medicamentos da\nprimeira e segunda fases, conforme norma vigente no país.","D":"Solicitar prova tuberculínica e, se superior a 5 mm, sem achados radiológicos, indicar\ntratamento da infecção latente.","E":"Iniciar tratamento\nprofilático com\n\nhidrazida até 3 meses após a negativação do escarro da mãe."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-138685","number":"138685","sourceNumber":"138685","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um menino, com quatro anos de idade, chegou ao Setor de Emergência com grave\nalteração na perfusão sistêmica. Sua mãe relatou que o menor estava febril há 20 dias e que não\nhavia feito o tratamento indicado pelo médico para infecção do trato urinário. Foi diagnosticado\nchoque séptico e administrado oxigênio (concentração 100%), providenciado acesso venoso e\niniciada a infusão de Soro Fisiológico, 30 ml/Kg em quinze minutos, sendo então realizada a\nsequência\n\nrápida de intubação orotraqueal e instalada ventilação pulmonar mecânica. Após essa conduta,\nenquanto esperava vaga na Unidade de Cuidados\nIntensivos, o paciente foi reavaliado e\napresentou: Frequência respiratória = 40 irpm, Frequência cardíaca = 140 bpm, tempo de\nenchimento capilar de cinco segundos, Pressão arterial = 75 x 50 mmHg. As extremidades estavam\nfrias. Diante desse quadro, qual deve ser a conduta para essa criança?","options":{"A":"Manter infusão de volume e iniciar dopamina ou\ndobutamina.","B":"Manter infusão de volume e iniciar dopamina ou\nnorepinefrina.","C":"Suspender infusão de volume e iniciar dopamina\ndose alfa adrenérgica ou epinefrina.","D":"Manter infusão de volume e iniciar dopamina dose\nalfa adrenérgica ou norepinefrina","E":"Manter infusão de volume e iniciar dopamina dose\nalfa adrenérgica ou epinefrina."},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-138718","number":"138718","sourceNumber":"138718","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Criança, com 5 anos de idade, mora com os pais em bairro de periferia. Seu pai é\nfumante, há três meses apresenta tosse\ncrônica, produtiva, sudorese noturna e febre diária e não\nprocura cuidados médicos. Sua mãe é aparentemente saudável. Há três semanas, a criança iniciou\ntosse produtiva com escarro purulento, febre ao final da tarde e emagrecimento. O cartão de\nvacinas demonstra que ele foi vacinado com BCG ID no primeiro ano de vida. No atendimento é\nconstatada temperatura oral de 37,5 °C, taquipneia e redução de murmúrio vesicular em terço\nmédio do hemitórax direito. O exame radiológico do tórax mostra condensação homogênea em\nápice de pulmão direito. O PPD é de 10 mm. Qual a conduta terapêutica para essa criança?","options":{"A":"quimioprofilaxia primária.","B":"quimioprofilaxia secundária e controle com exames\na cada 2 meses.","C":"revacinar com BCG e controle com exames a cada 2 meses.","D":"esquema tríplice (2HRZ ) e duplo (4HR) e controle\ncom exames a cada 2 meses.","E":"esquema quádruplo 2(HRZE) e duplo (5HR) e controle com exames a cada 2 meses."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-8656","number":"8656","sourceNumber":"8656","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Segundo dados do Ministério da Saúde, a prevalência de tuberculose no Brasil é de 58\ncasos por 100.000 habitantes, com\naproximadamente 50 milhões de infectados e 6.000 óbitos\nocorrendo anualmente. Com relação a essa doença, julgue o item que se segue. No Brasil, em\npacientes com tuberculose pós-primária, é comum o achado radiológico de massas no interior do\nparênquima pulmonar, com porção central necrosada - as chamadas cavitações, frequentemente\nvista nos segmentos apicais posteriores dos lobos superiores ou nos segmentos superiores dos\nlobos inferiores.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-359202","number":"359202","sourceNumber":"359202","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Quanto à estrutura, à atividade antibacteriana e ao mecanismo de ação das\npolimixinas, assinale a alternativa CORRETA.","options":{"A":"A ação antibacteriana das polimixinas é atribuída a sua composição anfipática e à capacidade\nde formar poros na membrana de Gram-negativos.","B":"A Polimixina B (PMB) e a colistina, grupos mais estudados, são caracterizadas pela presença de\num resíduo de leucina na posição 7 e diferem\nem relação ao resíduo da posição 6, o qual, na PMB,\né a d-leucina e, na colistina, é a-fenilalanina.","C":"As polimixinas agem contra algumas bactérias Gram-positivas, embora não tenham ação contra\ncocos Gram-negativos, anaeróbios e fungos.","D":"As polimixinas são polipeptídeos catiônicos cíclicos não ribossômicos cuja estrutura é composta\npor um anel tripeptídio, resíduos não\nprotogênicos de Dab com carga positiva, um segmento linear\nheptapeptídeo e um grupo de ácido graxo hidrofóbico com terminal metil."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-359219","number":"359219","sourceNumber":"359219","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"AMC, de 1 ano e 10 meses, sexo feminino, é levada pela mãe ao pediatra da Unidade\nBásica de Saúde com relato de febre,\npolaciúria, irritabilidade e vômitos muito frequentes. Desde o\ninício do quadro, há 48 horas, não consegue comer quase nada, apresenta vômitos e está mais\nprostrada. Ao exame físico, apresenta-se desidratada, taquicárdica e com perfusão capilar = 5'. Em\nrelação ao caso descrito, assinale a alternativa que apresenta a conduta CORRETA para a criança:","options":{"A":"Solicitar urina rotina, gram e urocultura e aguardar o resultado de exames para definir o\ntratamento antimicrobiano de acordo com a sensibilidade do micro-organismo isolado.","B":"Encaminhar a criança à Unidade de Pronto Atendimento, pois encontra-se indicado o início\nimediato de tratamento com antimicrobiano venoso após coleta de urina para exames.","C":"Prescrever quimioprofilaxia por um período mínimo de 1 ano após tratamento para erradicar a\nbactéria, independente da investigação morfofuncional de vias urinárias.","D":"Realizar imediatamente o ultrassom de vias urinárias e a uretrocistografia miccional após o\ndiagnóstico de infecção do trato urinário ser confirmado pela urocultura."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-351603","number":"351603","sourceNumber":"351603","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Sobre as apresentações e manifestações da tuberculose (TB), é INCORRETO afirmar\nque:","options":{"A":"A apresentação da tuberculose na forma pulmonar, além de ser mais frequente, é também a\nmais relevante para a saúde pública.","B":"A tuberculose pleural é a forma mais comum de TB extrapulmonar em indivíduos HIV\nsoronegativos, e ocorre mais em jovens.","C":"A tuberculose ganglionar periférica é a forma mais frequente de TB extrapulmonar em pacientes\nHIV soropositivos e crianças, sendo mais comum\nabaixo dos 40 anos.","D":"A tuberculose miliar é uma forma grave de doença e ocorre em até 50% dos casos de TB em\npacientes HIV soropositivos, em fase avançada de imunossupressão."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-346836","number":"346836","sourceNumber":"346836","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem de 66 anos retornou de viagem em um cruzeiro marítimo apresentando febre\n(38,6°C) e tosse produtiva com escarro\namarelado. A radiografia do tórax apresentou consolidação\npulmonar no hemitórax esquerdo. Está em uso de amoxicilina-clavulanato 500/125mg de 8/8h por\nvia oral há 4 dias, sem melhora clínica. Realizou teste de antígeno para Legionella sp. na urina,\nque\nresultou positivo. Ao exame físico, PA: 142x88mmHg, FC: 72bpm, FR: 17ipm, SpO2 96% (aa). Sem\noutras alterações. Assinale a alternativa que apresenta o tratamento MAIS adequado para esse\npaciente.","options":{"A":"Trocar o tratamento para levofloxacino (VO).","B":"Manter amoxicilina-clavulanato(VO) e acrescentar doxiciclina (VO).","C":"Manter amoxicilina-clavulanato em dose dobrada (IV).","D":"Trocar o tratamento para ceftriaxona (IV) e azitromicina (VO)."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-346838","number":"346838","sourceNumber":"346838","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Mulher de 27 anos vai ao PS queixando-se de lombalgia direita muito intensa, náuseas\ne vômitos. É portadora de lúpus eritematoso\nsistêmico e está em uso de prednisona 10mg ao dia e\nhidroxicloroquina 400mg ao dia. Nega internações recentes. Ao exame físico, PA: 100x60mmHg,\nFC: 128bpm, FR: 26ipm, SpO? 94% (aa). Apresenta- se alerta e orientada. O exame cardiovascular\nrevela ritmo cardíaco taquicárdico; as extremidades estão aquecidas e apresentam o enchimento\ncapilar imediato. O exame respiratório revela taquipnéia, sem esforço e ausculta normal. O exame\ndo abdome não revela anormalidades. A punho-percussão revela dor na região lombar direita.\n\nExames de laboratório: Hemoglobina: 8,3g/dL (VR 12-16d/dL); Leucócitos: 14.780/mm³\n(4.000-11.000/mm³); neutrófilos: 10.890/mm³ (1.500-7.000/mm³); plaquetas: 78.000/mm³\n(150.000-450.000mm³); creatinina: 2,2mg/dL; ureia: 54mg/dL; bilirrubina total: 3,4mg/dL\n\n(<1,2mg/dL); bilirrubina direta: 2,0mg/dL (<0,4mg/dL). Assinale a alternativa que apresenta uma\nconduta INCORRETA:","options":{"A":"Prescrever transfusão de concentrado de hemácias.","B":"Solicitar TC abdominal total na urgência.","C":"Prescrever antibiótico parenteral de espectro adequado.","D":"Prescrever hidrocortisona parenteral."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-346873","number":"346873","sourceNumber":"346873","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Apesar de ser uma enfermidade antiga, a tuberculose continua sendo um importante\nproblema de saúde pública. Sobre a tuberculose, é CORRETO afirmar que:","options":{"A":"Os bacilos que se depositam em roupas, lençóis, copos e outros objetos facilmente se\ndispersam em aerossóis e, por isso, podem ajudar na transmissão da doença.","B":"Embora o risco de adoecimento seja maior nos primeiros 2 anos após a primoinfecção, uma vez\ninfectada, a pessoa pode adoecer em qualquer momento da sua vida.","C":"Com o início do esquema terapêutico adequado, a transmissão tende a diminuir gradativamente\ne, em geral, após 5 dias de tratamento, chega\na níveis insignificantes.","D":"A suscetibilidade à infecção é praticamente universal. A maioria dos infectados posterga o\nadoecimento após a infecção e desenvolve imunidade total à doença."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-321191","number":"321191","sourceNumber":"321191","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente de 55 anos, no 7°dia de pós-operatório de ressecção intestinal por bridas,\napresentando 38,9°C, FC: 110bpm, FR: 25ipm, SpO2 = 89%, PA: 95X55mmHg, 12.600/mm3\nleucócitos, confuso e torporoso. Sobre este caso, assinale a alternativa CORRETA:","options":{"A":"A febre seria esperada pela resposta inflamatória do trauma cirúrgico.","B":"O paciente apresenta sinais de choque séptico.","C":"A leucocitose é normal neste período do pós-operatório.","D":"O paciente apresenta uma resposta inflamatória sistêmica e íleo paralítico devido à ressecção\nintestinal realizada."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-337657","number":"337657","sourceNumber":"337657","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A Tuberculose (TB) é uma doença que pode ser prevenida e curada, mas ainda\nprevalece nas condições de pobreza e contribui\npara a perpetuação da desigualdade social. Sobre\no tratamento da tuberculose, assinale a alternativa INCORRETA:","options":{"A":"Em geral, após duas a três semanas de tratamento com esquema anti TB que contenham\nfármacos com atividade bactericida precoce,\nocorre significativa diminuição da capacidade de\ntransmissão de bacilos pelos indivíduos doentes.","B":"Para a prevenção da seleção de bacilos resistentes e a efetiva cura da doença, é necessária a\nutilização de esquemas terapêuticos com associação de diferentes medicamentos que agirão sobre\nos bacilos sensíveis e nos naturalmente resistentes.","C":"O tratamento de formas extrapulmonares tem a duração de seis meses, mas no caso do\ntratamento de TB em pacientes com HIV, a duração se prolonga para oito meses.","D":"O esquema de tratamento da tuberculose é padronizado, deve ser realizado de acordo com as\nrecomendações do Ministério da Saúde e compreende duas fases: a intensiva ( ou de ataque ), e a\nde manutenção."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-345747","number":"345747","sourceNumber":"345747","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A tuberculose primária é mais frequente em crianças, mas pode também ocorrer em\nadultos. Sendo correto que:","options":{"A":"Na infância, em razão da facilidade de se estabelecer o diagnóstico baciloscópico, os métodos\nde imagem têm papel menos relevante.","B":"Na infância, em razão da facilidade de se estabelecer o diagnóstico baciloscópico, os métodos\nde imagem têm papel menos relevante.","C":"Na infância, em razão da dificuldade de se estabelecer o diagnóstico baciloscópico, os métodos\nde imagem têm papel ainda mais relevante.","D":"Na infância, em razão da dificuldade de se estabelecer o diagnóstico baciloscópico, os métodos\nde imagem são contraindicados."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-345749","number":"345749","sourceNumber":"345749","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Entre as múltiplas formas de apresentação da doença tuberculose, os achados\nradiográficos mais comuns são representados por alterações associadas:","options":{"A":"Incluindo opacidade(s) parenquimatosa(s), segmentar(es) ou lobar(es), e linfonodomegalias\nhilares e nunca as mediastinais, que\ndeterminam redução volumétrica do pulmão (epituberculose),\nsendo a síndrome do lobo médio a expressão mais conhecida.","B":"Incluindo opacidade(s) parenquimatosa(s), segmentar(es) ou lobar(es), e linfonodomegalias\nhilares e/ou mediastinais, que determinam\naumento volumétrico do pulmão (epituberculose), sendo\na síndrome do lobo médio a expressão mais conhecida.","C":"Incluindo opacidade(s) parenquimatosa(s), segmentar(es) ou lobar(es), e linfonodomegalias\nhilares e/ou mediastinais, que determinam\nredução volumétrica do pulmão (epituberculose), sendo\na síndrome do lobo superior a expressão mais conhecida.","D":"Incluindo opacidade(s) parenquimatosa(s), segmentar(es) ou lobar(es), e linfonodomegalias\nhilares e/ou mediastinais, que determinam\nredução volumétrica do pulmão (epituberculose), sendo\na síndrome do lobo médio a expressão mais conhecida."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-345751","number":"345751","sourceNumber":"345751","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A Tuberculose secundária ou de reinfecção:","options":{"A":"É a forma mais comum de adoecimento entre adolescentes e não entre adultos e, nesses, o\ncomprometimento dos pulmões ocorre em 85-90% dos casos.","B":"É a forma mais comum de adoecimento entre adolescentes e adultos e, nesses, o\ncomprometimento dos pulmões ocorre em 85- 90% dos casos.","C":"É a forma mais comum de adoecimento entre adolescentes e adultos e, nesses, o\ncomprometimento dos pulmões ocorre em 5- 9% dos casos.","D":"É a forma mais rara de adoecimento entre adolescentes e adultos e, nesses, o\ncomprometimento dos pulmões ocorre em 85-90% dos casos."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-345753","number":"345753","sourceNumber":"345753","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Embora a radiografia do tórax seja o mais importante método de imagem no diagnóstico\ne acompanhamento de pacientes com tuberculose, a TC é\numa realidade cada vez mais presente.\nEstá correto que:","options":{"A":"A TC é menos sensível e específica do que a radiografia do tórax, podendo demonstrar\nalterações iniciais ainda imperceptíveis pelo\nmétodo radiográfico, e deve ser realizada em pacientes\nsintomáticos respiratórios com alterações mal definidas ou duvidosas nos quais o contexto\n\nclínico-epidemiológico aponta para a possibilidade de tuberculose.","B":"A TC é mais sensível e específica do que a radiografia do tórax, podendo demonstrar alterações\niniciais ainda imperceptíveis pelo método\nradiográfico, e nunca deve ser realizada em pacientes\nsintomáticos respiratórios com alterações mal definidas ou duvidosas nos quais o contexto\n\nclínico-epidemiológico aponta para a possibilidade de tuberculose.","C":"A TC é mais sensível e menos específica do que a radiografia do tórax, podendo demonstrar\nalterações iniciais ainda imperceptíveis pelo\nmétodo radiográfico, e deve ser realizada em pacientes\nsintomáticos respiratórios com alterações mal definidas ou duvidosas nos quais o contexto\n\nclínico-epidemiológico aponta para a possibilidade de tuberculose.","D":"A TC é mais sensível e específica do que a radiografia do tórax, podendo demonstrar alterações\niniciais ainda imperceptíveis pelo método\nradiográfico, e deve ser realizada em pacientes\nsintomáticos respiratórios com alterações mal definidas ou duvidosas nos quais o contexto\n\nclínico-epidemiológico aponta para a possibilidade de tuberculose."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-291920","number":"291920","sourceNumber":"291920","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um senhor de 67 anos procurou o pronto-socorro com quadro de febre (38,5°C) e tosse\nprodutiva há dois dias. Referiu vacinação apenas na infância e negou comorbidades. Ao exame,\nestava lúcido, orientado, normotenso, com FR: 28 irpm, estertores crepitantes na base do pulmão\ndireito e a radiografia do tórax mostrou condensação no lobo inferior direito. Foi recomendado\ntratamento ambulatorial. Nesse caso, o antibiótico INDICADO, é:","options":{"A":"Azitromicina.","B":"Ciprofloxacino.","C":"Clindamicina.","D":"Rifampicina."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-313284","number":"313284","sourceNumber":"313284","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O Ministério da Saúde aponta uma lista de reações adversas dos fármacos utilizados\nnos Esquemas Especiais e de Tuberculose\ndrogarresistentes (TB DR) e condutas preconizadas.\nDessa lista, estão associados à neurite óptica os fármacos:","options":{"A":"Etambutol e Linezolida.","B":"Amicacina e Capreomicina.","C":"Estreptomicina e Moxifloxacino.","D":"Bedaquilina e Clofazimina.","E":"Etionamida e Pirazinamida."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-305009","number":"305009","sourceNumber":"305009","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Sobre a antibioticoterapia e a sepse abdominal, analise as afirmativas a seguir. I. Os\nantibióticos são administrados para prevenir disseminação da infecção e evitar complicações\ntardias. II. A obtenção do controle do foco infeccioso associada à antibioticoterapia adequada não\naltera o prognóstico. III. O aumento da mortalidade está associado com o uso inapropriado inicial\nde antibióticos e não é reversível pela mudança posterior do agente antimicrobiano. Estão corretas\nas afirmativas","options":{"A":"I e II, apenas.","B":"I e III, apenas.","C":"II e III, apenas.","D":"I, II e III."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-306719","number":"306719","sourceNumber":"306719","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"S.R.A, 70 anos, portador de hipertensão arterial e fibrilação atrial, em uso de losartana\n50mg/dia, atenolol 50mg/dia e rivaroxabana 20mg/dia. Chega ao hospital com dispneia, febre,\ntosse produtiva, icterícia, confusão mental e prostração com 5 dias de evolução. PA =\n100/60mmHg, FC = 65bpm, FR = 30 irpm, SpO2 = 90%. Com relação ao quadro clínico\napresentado, marque a alternativa correta:","options":{"A":"O paciente apresenta diagnóstico de choque séptico e por isso deve receber ressuscitação\nvolêmica com ringer lactato, pelo menor risco\nde acidose hiperclorêmica.","B":"A avaliação da variação da pressão de pulso poderá auxiliar na predição de resposta à\nressuscitação volêmica neste paciente, portanto devendo ser realizada cateterização arterial.","C":"O uso da procalcitonina em associação à avaliação clínica poderá auxiliar no momento correto\npara a suspensão do uso de antimicrobianos,\nevitando o uso prolongado desnecessário.","D":"A administração de antibióticos não deverá ser retardada, porém de acordo com as\nrecomendações mais recentes para o tratamento\nde sepse, poderá ser iniciada nas primeiras 6\nhoras."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-291946","number":"291946","sourceNumber":"291946","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente de 45 anos vai ser operado de uma úlcera perfurada e se apresenta com\nchoque séptico. Foram tomadas as medidas\niniciais para abordagem do caso. É CORRETO afirmar\nque se trata de alteração característica da fase inicial do choque séptico:","options":{"A":"Bradicardia.","B":"Baixo débito cardíaco.","C":"Elevação da pressão capilar pulmonar.","D":"Baixa resistência vascular sistêmica."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-291638","number":"291638","sourceNumber":"291638","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente, sexo feminino, queixa de tosse seca há cerca de 7 dias, seguida de\naparecimento de escarro purulento, inodoro,\nfebre de 38,5ºC e dor pleurítica nas últimas 48 horas.\nTeve perda ponderal de quase 10% do peso nas últimas 3 semanas. RX de tórax com consolidação\nno lobo superior direito e adenomegalias mediastinais ipsilaterais. Os sinais vitais eram estáveis\ne a\npaciente estava em regular estado geral. Qual alternativa abaixo inclui a propedêutica adequada no\ncaso?","options":{"A":"Iniciar com azitromicina e liberar para tratamento ambulatorial.","B":"Coletar hemocultura e cultura de escarro.","C":"Coletar escarro para pesquisa BAAR.","D":"Solicita biópsia de massa pulmonar.","E":"Realizar fibrobroncoscopia com biópsia transbrônquica."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-291956","number":"291956","sourceNumber":"291956","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A tuberculose continua sendo mundialmente um importante problema de saúde,\nexigindo o desenvolvimento de estratégias para o seu controle, considerando aspectos\nhumanitários, econômicos e de saúde pública. São ações de vigilância epidemiológica para a\ntuberculose, EXCETO:","options":{"A":"Definição, investigação do caso e notificação.","B":"Acompanhamento e encerramento dos casos.","C":"Exame e tratamento profilático de todos os contatos.","D":"Visita domiciliar a caso novo e convocação de faltosos."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-260669","number":"260669","sourceNumber":"260669","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Qual a forma que melhor explica a transmissão do vírus da influenza A e B,\nconsiderando os vários subtipos que sofrem\ncontínuas mutações com surgimento de novas cepas?","options":{"A":"Por meio de pequenas gotículas de aerossol (>5 milimicras de diâmetro) expelidas pelo indivíduo\ninfectado com o vírus (ao falar, tossir e espirrar) às pessoas suscetíveis.","B":"Ingesta de alimentos contaminados com saliva durante o período prodrômico por suscetíveis\nsaudáveis.","C":"Pelo contato com tecidos, sangue, urina, secreções vaginais, fetos abortados, placenta (grande\nfonte de infecção).","D":"Pelo contato sexual, com penetração do vírus por meio da pele ou mucosa, com solução de\ncontinuidade e respiração.","E":"Pelo contato por mais de 20 dias nos casos dos indivíduos imunocompetentes, e 2 dias nos\nimunocomprometidos."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-283891","number":"283891","sourceNumber":"283891","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Sepse é uma das causas mais frequentes de admissão na UTI. Em relação aos\nsobreviventes, assinale a alternativa correta.","options":{"A":"Os pacientes sépticos retornam frequentemente às suas atividades instrumentais de vida diária e\nàs suas atividades laborais normalmente.","B":"Os pacientes sépticos frequentemente apresentam distúrbios psicológicos e cognitivos, bem\ncomo uma redução de sua capacidade de realizar\nas atividades de vida diária.","C":"Os pacientes sépticos raramente necessitam reinternação hospitalar após a alta da UTI.","D":"Os pacientes sépticos apresentam uma taxa de mortalidade semelhante à da população geral,\nquando pareados por idade, comorbidades e nível educacional.","E":"Pacientes sépticos não sobrevivem à internação na UTI."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-266374","number":"266374","sourceNumber":"266374","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Mulher de 81 anos, hipertensa e moradora de asilo, iniciou há 3 dias quadro de\nconfusão mental, adinamia e anorexia. Sem\nhistória prévia de diabetes mellitus, tabagismo,\ninternação ou uso de antimicrobianos nos últimos 3 meses. Sem cartão vacinal. Ao exame: pressão\narterial de 110/70 mmHg, frequência respiratória de 28 irpm. No rastreio de foco infeccioso, o raio\nX\nde tórax detectou consolidação em base de pulmão direito. Dos antibióticos propostos para tratá-la,\nqual esquema não é considerado de escolha nesta situação?","options":{"A":"Ampicilina/sulbactam + azitromicina.","B":"Piperacilina/tazobactam.","C":"Levofloxacina.","D":"Ceftriaxona + azitromicina."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-232105","number":"232105","sourceNumber":"232105","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Qual o esquema básico para tratamento da tuberculose, na fase intensiva, em\npacientes com 10 anos de idade ou mais,\npreconizado pelo Ministério da Saúde, para casos novos\nde tuberculose pulmonar e/ou extrapulmonar (exceto a forma meningoencefálica e osteoarticular),\ninfectados ou não pelo HIV?","options":{"A":"RHZE (150/75/400/275 mg) ? comprimido em dose fixa combinada. Pacientes com 20 a 35 kg: 2\ncomprimidos; 36 a 50 kg: 3 comprimidos, e > 50 kg: 4 comprimidos, durante 2 meses.","B":"Rifampicina (RFM): dose mensal de 600 mg (2 cápsulas de 300 mg) com administração\nsupervisionada, e Dapsona (DDS): dose mensal\nde 100 mg supervisionada e dose diária de 100 mg\nautoadministrada.","C":"RHb (150/75 mg) ? comprimido em dose fixa combinada. Pacientes com 20 a 35 kg: 2\ncomprimidos; 36 a 50 kg: 3 comprimidos, e > 50 kg: 4 comprimidos, durante 2 meses.","D":"Rifampicina (RFM): dose mensal de 600 mg (2 cápsulas de 300 mg) com administração\nsupervisionada, Dapsona (DDS): dose mensal de 100\nmg supervisionada e uma dose diária de 100\nmg autoadministrada, e Clofazimina (CFZ): dose mensal de 300 mg (3 cápsulas de 100 mg) com\nadministração supervisionada e uma dose diária de 50 mg autoadministrada.","E":"Rifampicina (RFM): dose mensal de 600 mg (2 cápsulas de 300 mg) com administração\nsupervisionada, Dapsona (DDS): dose mensal de 100\nmg supervisionada e uma dose diária de 100\nmg autoadministrada, e Isoniazida (H): dose diária de 200 mg (2 comprimidos de 100 mg) com\nadministração supervisionada."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-227248","number":"227248","sourceNumber":"227248","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Mulher de 33 anos, previamente saudável, há dois dias, após viagem de avião,\napresenta quadro de febre de 39,5ºC, astenia,\nmialgia e artralgia difusa, evoluindo com dispneia\nintensa e tosse nas últimas 6 horas. É atendida na sala de emergência consciente, com saturação\nperiférica de oxigênio de 81% em ar ambiente, esforço respiratório, roncos e estertores crepitantes\ndifusos. A radiografia de tórax evidenciou opacidades em vidro fosco difusas e consolidações em\nambas as bases pulmonares. Hemograma apresenta 12.530 leucócitos/mm³, 624 bastonetes/mm³,\n\n5.012 segmentados/mm³ e 5.763 linfócitos/mm³. Foi instituída ventilação não invasiva. Assinale a\nalternativa que representa o tratamento mais bem indicado para esta paciente.","options":{"A":"Oseltamivir.","B":"Levofloxacino.","C":"Amoxicilina + ácido clavulânico.","D":"Ceftriaxona + claritromicina."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-227081","number":"227081","sourceNumber":"227081","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem de 45 anos se queixa de tosse produtiva com escarro claro, dispneia, perda de\napetite e emagrecimento há 3 meses. Nega febre, sudorese noturna ou outras queixas. É lavrador\ne não está conseguindo exercer as funções por causa de fraqueza. Desconhece comorbidades e\nnega uso de medicamentos. É etilista e tabagista. Ao exame físico, está alerta e orientado, com\nmucosas hipocoradas, hidratadas e anictéricas. Está emagrecido. Palpam-se linfonodomegalias\ncervicais. A oroscopia revela lesão granulada no palato mole. Há roncos holorrespiratórios na\nausculta pulmonar em ambos os hemitórax. Sem outras anormalidades ao exame. Foi realizada\nradiografia do tórax e exame do escarro. Radiografia de tórax: exame do escarro (visualização\ndireta): Considerando o caso descrito, assinale a alternativa que apresenta o tratamento MAIS\nADEQUADO para esse paciente:","options":{"A":"Amoxicilina + clavulanato e azitromicina.","B":"Levofloxacino.","C":"Rifampicina, isoniazida, pirazinamida e etambutol.","D":"Sulfametoxazol + trimetoprima."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-246357","number":"246357","sourceNumber":"246357","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente 76 anos, hipertenso, diabético, portador de Alzheimer, com história de há 3\ndias ter apresentado quadro de vômito e\npossível bronco-aspiração. Deu entrada no pronto\nsocorrro 1 dia depois em insuficiência respiratória e com os seguintes sinais vitais e exames: FR:30\nIPM SAT 86%, PaO2 : 40 mmHg, Pressão Arterial: 80/40 mmHg, Escala de Coma de Glasgow 12,\noligúria com creatinina sérica: 3,2 mg/dl, Plaquetas: 40.000 mm³. Seguindo critério diagnóstico do\nSepse 3 (2016) esse paciente é classificado como:","options":{"A":"Sepse","B":"Sepse grave","C":"Choque séptico","D":"Falência múltipla de órgãos"},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-227254","number":"227254","sourceNumber":"227254","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem de 54 anos, sem fatores de risco, apresenta tosse produtiva há 3 dias com\nexpectoração purulenta e febre de 39ºC. Ao exame físico, apresenta roncos esparsos e estertores\ncrepitantes em terço médio do hemitórax direito. Assinale o esquema de antibioticoterapia mais\nindicado neste caso.","options":{"A":"Azitromicina por 5 dias.","B":"Levofloxacino por 5 dias.","C":"Ceftriaxona + claritromicina por 7 dias.","D":"Amoxicilina + ácido clavulânico + claritromicina por 7 dias."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-227258","number":"227258","sourceNumber":"227258","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O manejo racional de pacientes portadores de influenza dentro do ambiente hospitalar\né fundamental para minimizar riscos de transmissão\ne otimizar leitos de internação. Portanto, a\nComissão de Controle de Infecção Hospitalar deve reforçar as seguintes medidas, de acordo com\norientações fornecidas pelo Ministério da Saúde:","options":{"A":"Coleta de swab nasal para realização de PCR (Polymerase Chain Reaction) em todos os\npacientes internados, independente dos critérios de gravidade.","B":"Manter precaução por aerosol até o momento da alta hospitalar.","C":"Manter precaução respiratória até 72 horas após desaparecimento da febre.","D":"Notificar à Vigilância Epidemiológica todos os pacientes que se encaixem na definição de caso:\nfebre, de início súbito, acompanhada de tosse ou odinofagia, associada a pelo menos um dos\nseguintes sintomas: mialgia, cefaleia ou artralgia."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-234433","number":"234433","sourceNumber":"234433","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Escolar de 6 anos é internado em enfermaria para investigação de quadro respiratório.\nApresenta redução do apetite, perda de peso e tosse persistente há mais de 2 semanas mesmo\napós uso de amoxicilina-clavulanato por 7 dias. A criança mora com o avô que também está\ntossindo há mais de 2 meses. Em relação à principal suspeita clínica do caso em questão, é\nCORRETO afirmar que:","options":{"A":"O diagnóstico pode ser feito através de um sistema de pontuação que leva em consideração\ndados clínicos, radiológicos e epidemiológicos.","B":"A prova tuberculínica não está indicada no caso, pois a vacina BCG feita ao nascimento pode\nocasionar resultado falso-positivo.","C":"O tratamento consiste em 2 meses de rifampicina, isoniazida, pirazinamida e etambutol e 4\nmeses de rifampicina e isoniazida.","D":"A profilaxia com isoniazida deve ser iniciada para o avô da criança por se tratar de um caso de\ninfecção latente pelo M. tuberculosis."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-246751","number":"246751","sourceNumber":"246751","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente com 37 anos, sem comorbidades procura atendimento no PS devido lesão em\ncoxa direita com sinais flogísticos\nimportantes e vários pontos de drenagem de secreção purulenta\nprecedida por pequena lesão papuloeritematosa. Nega febre e relata estar em uso de cefalexina,\nsem melhora. Qual conduta inicial seria mais apropriada para o caso acima:","options":{"A":"amoxicilina clavulanato vo por 7 dias e retorno se piora","B":"drenagem cirúrgica e retorno se piora","C":"drenagem cirúrgica e ceftriaxone por 7 dias","D":"oxacilina por 7 dias","E":"drenagem cirúrgica e oxacilina por 7 dias"},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-246752","number":"246752","sourceNumber":"246752","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente com 66 anos, etilista, admitido no PS com relato de tosse produtiva (secreção\namarela espessa) há 21 dias, dispneia a médios esforços e febre intermitente diária, sem horário\npredominante, perda ponderal não quantificada. Relata ter feito uso de amoxicilina clavulanato por\n7 dias, sem melhora. Na admissão, estava normotenso e com dispneia leve. Qual seria a\npropedêutica inicial adequada:","options":{"A":"Rx de tórax, hemocultura, hemograma, ureia e creatinina e gasometria arterial","B":"Rx de tórax, hemocultura, hemograma, ureia e creatinina, gasometria arterial, coleta de escarro\npara pesquisa de baar/micobacteria","C":"Hemograma, ureia, creatinina e gasometria arterial","D":"Rx de tórax e coleta de escarro para pesquisa de baar/micobacteria","E":"Rx de tórax e hemograma"},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-227110","number":"227110","sourceNumber":"227110","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Sobre a Síndrome de Resposta Inflamatória Sistêmica (SIRS), é CORRETO afirmar\nque:","options":{"A":"Bacteremia é critério de diagnóstico e deve ser confirmado para o diagnóstico.","B":"Hipotermia é mais frequente do que a hipertermia.","C":"Leucocitose está sempre presente.","D":"Frequência respiratória é maior que 20 respirações por minuto e a PaCO? é menor que\n32mmHg."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-234442","number":"234442","sourceNumber":"234442","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Você está atendendo um paciente com quadro de abdômen agudo inflamatório e\nchoque que ao exame se apresenta\ntaquicárdico, hipotenso, pefusão capilar diminuída, com sinais\nde confusão mental. Primeiro passo para o sucesso no tratamento de estados de choque é o\nreconhecimento da e o fármaco de primeira linha para tratamento da hipotensão\nno choque séptico é a .","options":{"A":"extremidades frias; dobutamina.","B":"hipotensão arterial; vasopressina.","C":"taquicardia; dopamina.","D":"hipoperfusão tecidual; noradrenalina."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-227113","number":"227113","sourceNumber":"227113","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A tuberculose continua sendo mundialmente um importante problema de saúde,\nexigindo o desenvolvimento de estratégias para o seu controle, considerando aspectos\nhumanitários, econômicos e de saúde pública. Sobre as recomendações para o controle da\ntuberculose no Brasil, assinale a alternativa INCORRETA:","options":{"A":"A busca ativa do sintomático respiratório deve ser realizada permanentemente por todos os\nserviços de saúde e tem sido uma estratégia recomendada internacionalmente.","B":"O tratamento diretamente observado deve ser realizado para todo caso de tuberculose, pois não\né possível predizer os casos que irão aderir\nao tratamento.","C":"O exame microscópico direto (baciloscopia direta), por ser um método simples e seguro, deve\nser realizado por todo laboratório público de\nsaúde e pelos laboratórios privados tecnicamente\nhabilitados.","D":"A vacina BCG é prioritariamente indicada para crianças de 0 a 4 anos. Lactentes que foram\nvacinados e não apresentem cicatriz vacinal após seis meses, devem ser revacinados quantas\nvezes forem necessárias, até que se forme a cicatriz."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-227297","number":"227297","sourceNumber":"227297","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Pacientes críticos sob cuidados em Unidade de Terapia Intensiva, quando apresentam\nquadro clínico de choque, por vezes têm\ninstituído terapia com drogas vasopressoras. A droga de\nprimeira escolha na grande maioria dos choques sépticos é:","options":{"A":"Adrenalina.","B":"Noradrenalina.","C":"Vasopressina.","D":"Dobutamina."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-199580","number":"199580","sourceNumber":"199580","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O time de futebol tailandês \"Javalis Selvagens\" ficou confinado em uma caverna devido\na uma inundação por um período superior a 1\nsemana. Caso essa caverna estivesse localizada no\nBrasil, a quais doenças esse grupo estaria exposto?","options":{"A":"Paracoccidioidomicose, toxoplasmose, leptospirose.","B":"Febre maculosa, leptospirose, tuberculose.","C":"Histoplasmose, tuberculose, paracoccidioidomicose.","D":"Leptospirose, histoplasmose, hantavirose."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-212942","number":"212942","sourceNumber":"212942","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"De acordo com a Campanha ?Sobrevivendo à Sepse?:","options":{"A":"A ressuscitação volêmica deve ser realizada em todos os pacientes com choque séptico com 30\nml/kg de colóides.","B":"A meta inicial de pressão arterial a ser perseguida na estabilização hemodinâmica do paciente\nséptico é de 120/80 mmHg.","C":"A medida da pressão venosa central é a melhor maneira de avaliar a fluido-responsividade do\npaciente séptico.","D":"Uma dose de ataque de 1.000 mg de vancomicina será insuficiente em atingir níveis\nterapêuticos precoces para um significante número de pacientes.","E":"Para aminoglicosídeos, os desfechos clínicos serão melhores quanto maior for o tempo no qual\na concentração sérica da droga fique acima da\nconcentração inibitória mínima do patógeno\nenvolvido."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-212947","number":"212947","sourceNumber":"212947","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"No tocante às Pneumonias Adquiridas na Comunidade (PAC), assinale a correta:","options":{"A":"Os casos graves devem ser tratados em UTI e receber antimicrobianos empíricos por no mínimo\n10 dias.","B":"Amoxicilina isolada não deve ser utilizada para tratamento de PAC, independente da gravidade\nou da apresentação clínica, devido altos\níndices de resistência antimicrobiana.","C":"Pacientes com CURB-65 pontuação 1 e 2 são bons candidatos à tratamento ambulatorial.","D":"Deve-se evitar o uso de corticoides em pacientes com PAC pelo risco de imunossupressão.","E":"Recomenda-se realizar exames que busquem a etiologia somente para pacientes com PAC\ngrave ou PAC não respondedora à terapia empírica inicial, bem como nos internados em UTI."},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-199567","number":"199567","sourceNumber":"199567","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"J.M.S, 56 anos, feminina, com diagnóstico prévio de diabetes mellitus e hipertensão\narterial, chega ao pronto-socorro desorientada\ne agitada, com história de febre há três dias. Ao\nexame físico a temperatura axilar é de 36,6ºC, frequência cardíaca de 104 bpm, frequência\nrespiratória de 28 ipm, saturação de oxigênio de 92% em ar ambiente, pressão arterial de 100/80\nmmHg, enchimento capilar de 4 segundos. Os exames laboratoriais mostraram glicose de 355\nmg/dl; creatinina de 3,4 mg/dl; uréia de 85 mg/dl; potássio de 5,6 mEq/L; sódio = 142 mEq/L;\nleucócitos totais de 13.840/mm³; plaquetas de 128.00; bilirrubina de 1,8 mg/dl. Foi aberto o\nprotocolo de sepse. Observe as alternativas abaixo e responda sobre quais os dados clínicos e/ou\nlaboratoriais justificaram a abertura do protocolo de sepse.","options":{"A":"A abertura do protocolo de sepse foi correta, pois a paciente apresenta história de febre e\napresenta disfunção renal.","B":"A abertura do protocolo de sepse foi precipitada, pois ainda não tinha o resultado de lactato.","C":"A abertura do protocolo de sepse foi correta, pois a paciente apresenta taquicardia, taquipneia e\nleucócitos alterados.","D":"A abertura do protocolo de sepse foi correta, pois a paciente é diabética, teve febre e tem\nleucocitose."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-215108","number":"215108","sourceNumber":"215108","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Segundo as recomendações de fluidoterapia nos pacientes sépticos, a dose inicial\nrecomendada é:","options":{"A":"20 ml/kg.","B":"10 ml/kg.","C":"30 ml/kg.","D":"60 ml/kg.","E":"50 ml/kg."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-215110","number":"215110","sourceNumber":"215110","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"De acordo com o Guideline de sepse (campanha de sobrevivência a sepse), qual das\nalternativas abaixo não faz parte do manejo inicial do paciente séptico?","options":{"A":"Iniciar antibioticoterapia empírica na primeira hora.","B":"Coletar lactato arterial.","C":"Solicitar hemoculturas e culturas direcionadas de preferência antes da antibioticoterapia.","D":"Realizar antitérmico e controle intensivo da febre.","E":"Manejo hemodinâmico com reposição de fluido."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-202759","number":"202759","sourceNumber":"202759","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Marque a alternativa correta, de acordo com as diretrizes do SEPSE 3.0, a respeito do\nqSOFA na abordagem do paciente com sepse:","options":{"A":"O qSOFA determina as disfunções orgânicas durante o algoritmo de diagnóstico de sepse.","B":"O qSOFA é uma ferramenta de triagem para o diagnóstico de sepse.","C":"Os três parâmetros que compõem qSOFA são nível pressórico, nível de consciência e\nfrequência cardíaca.","D":"Paciente com qSOFA < 2 exclui o diagnóstico de sepse.","E":"Os pacientes que preenchem 2 ou mais critérios no qSOFA têm maior gravidade e, portanto,\nmaior chance de óbito."},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-220323","number":"220323","sourceNumber":"220323","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em relação à tuberculose, são medidas de controle ambiental e de proteção individual\nem serviços que atendam grande quantidade de\npacientes bacilíferos, EXCETO:","options":{"A":"Deve-se manter o paciente suspeito de tuberculose pulmonar em isolamento respiratório,\nzelando para que seu tempo de permanência no\nsetor seja o menor possível.","B":"É recomendado o uso de máscaras N95 para profissionais de saúde que tenham acesso às\náreas de alto risco de transmissão em ambientes hospitalares.","C":"Aos profissionais do laboratório, não é recomenda a utilização de máscaras N95 durante a\nmanipulação de materiais com suspeita de conter bacilos álcool-ácidos resistentes.","D":"No transporte de doentes bacilíferos ou suspeitos de TB pulmonar em ambulâncias, os\nprofissionais devem utilizar máscaras do tipo\nN95 e os pacientes devem utilizar máscaras cirúrgicas\ncomuns."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-196765","number":"196765","sourceNumber":"196765","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Gestante apresentando quadro de tosse crônica há cerca de 2 meses, tendo sido\ndiagnosticada com tuberculose pulmonar logo após entrar em trabalho de parto, iniciando a terapia\nadequada imediatamente após o parto. Diante do exposto, qual a melhor conduta a ser tomada em\nrelação ao recém-nascido:","options":{"A":"investigar tuberculose congênita, tratar se positivo; caso contrário, não vacinar, administrar\nisoniazida por 3 meses, quando deve-se realizar o teste tuberculínico","B":"investigar tuberculose congênita, tratar se positivo; caso contrário, administrar a vacina BCG e\nrealizar o teste tuberculínico aos 3 meses de idade","C":"administrar isoniazida por 6 meses e, em seguida, realizar o teste tuberculínico","D":"administrar isoniazida apenas de houver sintomas no recém-nascido; caso contrário\nacompanhar no ambulatório de pediatria."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-196818","number":"196818","sourceNumber":"196818","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Mulher de 55 anos com tosse produtiva e secreção purulenta há 5 dias, com febre e dor\ntorácica, é admitida com FC = 32 bpm, PA = 80/35 mmHg, Glasgow = 14, pO2 = 91 mmHg em ar\nambiente. Assinale a melhor opção para o manejo na primeira hora de abordagem.","options":{"A":"Noradrenalina, cristaloide, ceftriaxona, azitromicina.","B":"Cristaloide, ceftriaxona, azitromicina.","C":"Noradrenalina, dobutamina, Ringer lactato, piperacilina + tazobactam.","D":"Ringer lactato, noradrenalina, meropenem."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-172756","number":"172756","sourceNumber":"172756","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem de 61 anos, tabagista, hipertenso, dislipidêmico, previamente submetido à\nangioplastia coronariana com implante de dois stents, admitido em pronto atendimento com quadro\nde pneumonia adquirida na comunidade. Encontra-se orientado, com frequência respiratória de 32\nirpm; pressão arterial de 160 x 90 mmHg; ureia = 42 mg/dl; creatinina = 1,1 mg/dl; leucócitos =\n12.300/mm³ (bastonetes = 3%, segmentados = 66%, linfócitos = 22%). Considerando a escala\nCURB-65, assinale a alternativa correspondente ao caso clínico citado:","options":{"A":"Paciente de baixo risco, considerar tratamento ambulatorial.","B":"Paciente de risco intermediário, considerar hospitalização por período curto.","C":"Paciente com pneumonia grave, considerar hospitalização em enfermaria.","D":"Paciente com pneumonia muito grave, considerar hospitalização em CTI."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-172795","number":"172795","sourceNumber":"172795","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Sobre o manejo da sepse e choque séptico, a alternativa CORRETA é:","options":{"A":"Reposição volêmica com cristaloides e coloides deve ser feita nas primeiras 3 horas.","B":"Deve ser iniciado vasopressor se a pressão arterial média for menor que 50 mmHg.","C":"Antibioticoterapia empírica deve ser iniciada nas primeiras 6 horas.","D":"Normolactatemia é sugestiva de melhora da perfusão tissular."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-172549","number":"172549","sourceNumber":"172549","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Acerca dos novos critérios de sepse é CORRETO afirmar:","options":{"A":"Que após muitas críticas e dificuldade de aceitação universal, tiveram uma nova revisão em\n2017 com o retorno da Síndrome da Resposta\nInflamatória Sistêmica (SRIS) como o ponto de\nalerta inicial da sepse.","B":"Representaram um grande avanço aumentando a sensibilidade diagnóstica, ao de forma\nbastante abrangente, incluírem critérios bastante específicos de infecção, praticamente\nreduzindo a zero a inclusão de pacientes não infectados dentro do diagnóstico de sepse.","C":"Que apesar de não poderem ser indubitavelmente usados para o diagnóstico preciso de\nsepse, apresentam maior especificidade que os\ncritérios antigos e podem, por outro lado, com um\nquickSOFA \"maior que\" ou = a 2, serem úteis para detecção de pacientes com maior probabilidade\nde piores desfechos.","D":"Que definiram o quickSOFA (freqüência respiratória \"maior que\" 22/min; pressão sistólica\n\"menor que\" 100mmHg e o lactato sérico \"maior que\" 3) como o passo inicial para\ndesencadear a abordagem terapêutica em um possível paciente séptico.","E":"Recebem muitas críticas por reduzir a sensibilidade e a especificidade do diagnóstico da sepse,\natendendo principalmente aos interesses das seguradoras de saúde dos países desenvolvidos,\numa vez que usaram um escore validado apenas dentro de UTIs, o quickSOFA, em salas de\nemergência."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-174392","number":"174392","sourceNumber":"174392","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Leia as assertivas abaixo sobre o abscesso pulmonar: I ? Sua incidência vem\naumentando com o aumento da expectativa de\nvida da população.; II ? Broncoaspiração em\nindivíduos idosos com doença esofágica é uma de suas causas.; III ? Disseminação hematogênica\nem usuários de drogas intravenosas pode ser um fator predisponente.; IV ? O pulmão direito é o\nmais acometido em casos de broncoaspiração. Assinale a alternativa que informa as assertivas\ncorretas:","options":{"A":"II, III e IV.","B":"II e IV.","C":"I, II, III e IV.","D":"I, II e IV.","E":"Somente a IV."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-172836","number":"172836","sourceNumber":"172836","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O Brasil está entre os 22 países priorizados pela Organização Mundial da Saúde\n(OMS), por apresentarem 80% da carga mundial\nda tuberculose. O número de casos estimados de\ntuberculose na infância para países de alta incidência é de mais de 10% de todos os casos.\n\nContudo, em 2013, o Brasil notificou apenas 3,3% dos seus casos em crianças. Provavelmente,\nessa subnotificação é ocasionada pelo subdiagnóstico,\nque, por sua vez, decorre das dificuldades\nna sua realização. Sobre a tuberculose infantil é CORRETO afirmar:","options":{"A":"A tuberculose pode ocorrer em diversos sítios do organismo, sendo os mais comuns na infância\na tuberculose pulmonar seguida da tuberculose\nóssea.","B":"A vacina BCG está indicada em crianças até 5 anos de idade e é contraindicada em\nimunossuprimidos ou recém-nascidos com menos de 2.000 g.","C":"A febre, quando presente, é intermitente, geralmente baixa, e costuma ocorrer pela manhã.","D":"Tosse persistente por mais de 2 semanas leva a suspeita de tuberculose, mas se associada a\nconjuntivite flictenular e eritema nodoso o diagnóstico de tuberculose na infância deve ser\ndescartado."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-187467","number":"187467","sourceNumber":"187467","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Entre as abaixo, qual alternativa é verdadeira frente ao diagnóstico de pneumonia\ncomunitária?","options":{"A":"Tratamento específico, direcionado para o microrganismo etiológico é mais efetivo do que o\ntratamento empírico em pacientes hospitalizados que não estão em terapia intensiva.","B":"Cerca de 5 a 15% dos pacientes internados com pneumonia comunitária apresentarão\nhemoculturas positivas.","C":"Pacientes com bacteremia causada por Streptococcus peneumoniae apresentam culturas de\nescarro positivas em mais de 80% dos casos.","D":"Testes com reação em cadeia de polimerase estão amplamente disponíveis e devem ser usados\nrotineiramente para pacientes internados com diagnóstico de pneumonia comunitária.","E":"A etiologia da pneumonia adquirida em comunidade é identificada em 70% dos casos."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-149161","number":"149161","sourceNumber":"149161","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Acerca das infecções estafilocócicas marque a alternativa INCORRETA:","options":{"A":"A linezolida é uma excelente opção para o tratamento das infecções de corrente\nsanguínea.","B":"Nas infecções pulmonares por cepas oxacilina-resistentes, a linezolida é preferível em relação à\nvancomicina, principalmente em locais onde a vancocinemia não é disponível.","C":"A daptomicina está indicada para tratamento de infecções de corrente sanguínea por cepas\noxacilina-resistentes.","D":"Sempre que possível, as infecções estafilocócicas devem ser tratadas com as drogas\nespecíficas, oxacilina, vancomicina, daptomicina, linezolida ou\n\nteicoplanina, dependendo do sítio da infecção e do resistência da cepa.","E":"A oxacilina deve ser a droga de escolha para as infecções por cepas sensíveis, mesmo se\ntratando de infecções graves e choque séptico."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-155377","number":"155377","sourceNumber":"155377","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Assinale a opção que indica, após consulta inicial, a conduta a ser adotada frente a um\nadulto assintomático que tem contato domiciliar de paciente com tuberculose pulmonar ativa.","options":{"A":"Colher amostra de escarro para exame.","B":"Investigar tuberculose doença.","C":"Iniciar isoniazida profilática imediatamente.","D":"Fazer teste terapêutico por dois meses.","E":"Realizar a prova tuberculínica."},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-155383","number":"155383","sourceNumber":"155383","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem de 70 anos é atendido na UTI com sepse de origem urinária. Não há\nantecedentes de doença cardíaca ou pulmonar.\nAo exame físico, encontra-se hipotenso (70 x 50\nmmHg); taquicárdico (110 bpm); taquipneico; com palidez cutâneo-mucosa e confusão mental.\n\nApós infusão inicial de 2.000 ml de solução salina a pressão arterial é de 120 x 70 mmHg, a\npressão venosa central é de 14 cm H2O, a\nfrequência cardíaca é de 94 bpm e a frequência\nrespiratória é normal. Os exames iniciais revelam: Hematócrito 33%; Leucócitos 22.000/mm3; 14%\nde bastões; Ureia 76mg%, Creatinina 1,9mg% e gasometria arterial normal. A saturação venosa\ncoletada por cateter venoso central foi de 62%. Além do início imediato de antibioticoterapia\nadequada, uma medida necessária será:","options":{"A":"Iniciar noradrenalina.","B":"Iniciar dobutamina.","C":"Realizar hemotransfusão com concentrado de hemácias.","D":"Manter reposição volêmica vigorosa com solução salina.","E":"Dosar PCR (Proteína C Reativa)."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-155349","number":"155349","sourceNumber":"155349","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em relação ao citomegalovírus, pode-se afirmar que:","options":{"A":"A grande maioria dos casos de infecção adquirida é sintomática e manifesta-se como síndrome\nda mononucleose.","B":"Todo paciente com IgG e IgM positivas deve ser tratado com ganciclovir, tendo em vista a\ntendência de cronificação da doença.","C":"As formas de transmissão ocorrem por contato sexual, por transfusão sanguínea, por\ntransplantes de órgãos, por infecção perinatal e por contato com secreções de orofaringe.","D":"Sua principal manifestação em imunocompetentes é a coriorretinite.","E":"É um arbovírus."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-149122","number":"149122","sourceNumber":"149122","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Pode-se afirmar que:","options":{"A":"Que os novos casos de infecção por H1N1 em 2016 estão relacionados à má atuação das\nautoridades sanitárias nacionais, pois\nimunizaram apenas uma parcela reduzida da população após\no primeiro surto de 2009.","B":"Os resultados no tratamento com uso de osetalmivir são praticamente anedóticos e seu uso\ndeverá ser abolido em breve.","C":"O influenza é um vírus de comportamento sazonal e tem aumento no número de casos entre as\nestações climáticas mais frias, podendo haver anos com menor ou maior circulação do vírus.\nHabitualmente em cada ano circula mais de um tipo de influenza concomitantemente (exemplo:\ninfluenza A (H1N1), influenza A (H3N2) e influenza B).","D":"Os benefícios do uso do antiviral fosfato de oseltamivir para pacientes com Síndrome Gripal\n(SG) e Síndrome Respiratória Aguda Grave\n(SRAG) suspeitos para influenza não foram\ncomprovados por estudos clínicos, sendo indicado apenas por opiniões pessoais após consultas\nreferendadas pelas sociedades médicas brasileiras e especialistas da área.","E":"Uma vez iniciado o oseltamivir, seu uso deve ser mantido por pelo menos 10 dias nos pacientes\ncom SRAG."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-137844","number":"137844","sourceNumber":"137844","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Escolar, sexo masculino, 6 anos, vem apresentando quadro de tosse persistente e\nfebre há 3 semanas. Exame físico: FR 50\nirpm, Fc 130 bpm e murmúrio vesicular diminuído em\nhemitórax esquerdo. Raio X de tórax: extenso derrame pleural. A toracocentese apresentou líquido\namarelado e citologia diferencial mostrando predomínio de linfócitos (>80%). O agente etiológico\nmais provável:","options":{"A":"Mycoplasma pneumoniae.","B":"Haemophylus influenzae.","C":"Staphylococcus aureus.","D":"Mycobacterium tuberculosis.","E":"Streptococcus feccalis."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-127212","number":"127212","sourceNumber":"127212","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Você atendeu João, 45 anos, com tuberculose na Unidade de Saúde da Família. Na\nlista de contatos, está a mulher, Maria, de\n43 anos e o filho, Marcos, de 21 anos. Você avalia que\nambos estão assintomáticos e solicita a Prova Tuberculínica (PT). Maria apresenta PT de 8mm e\nMarcos está com PT de 2mm. Tendo como base as recomendações do Ministério da Saúde para o\ncontrole da tuberculose, qual a conduta para Maria e Marcos?","options":{"A":"Encaminhar ambos para serviço especializado no tratamento de tuberculose.","B":"Solicitar Raio-X de tórax para ambos e, caso normais, interromper investigação.","C":"Iniciar esquema básico para tratamento de tuberculose em Maria; solicitar Raio-X de tórax para\nMarcos e, caso normal, interromper investigação.","D":"Solicitar Raio-X de tórax para Maria e, caso normal, iniciar isoniazida; repetir PT em Marcos em\n5 a 8 semanas.","E":"Solicitar Raio-X de tórax para ambos e, caso normais, repetir PT em 5 a 8 semanas."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-102740","number":"102740","sourceNumber":"102740","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente masculino, de 34 anos, morador de rua, trazido ao serviço de saúde pela\nassistência social do município devido às precárias condições de saúde. Paciente apresentando\ncaquexia importante, prostração e tosse seca persistente. Queixava-se de dispneia. Observado,\ndurante internação hospitalar, febre diária vespertina e derrame pleural moderado à direita na\nradiografia de tórax. Considerando o diagnóstico de tuberculose pleural, assinale a alternativa que\napresenta o que NÃO seria esperado encontrar na análise do líquido pleural desse paciente.","options":{"A":"Aumento de células mesoteliais na citometria.","B":"LDH aumentada e mais que 3,0 g/dl de proteínas.","C":"Adenosina deaminase maior que 40 U/L.","D":"Celularidade com predomínio de linfócitos."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-100985","number":"100985","sourceNumber":"100985","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em relação às reações adversas aos medicamentos antituberculose, assinale a\nalternativa INCORRETA:","options":{"A":"Epigastralgia e dor abdominal geralmente não requerem suspensão das medicações, apenas\nreformulação dos horários de administração.","B":"O aparecimento de exantema pode estar relacionado à rifampicina, a qual deve ser suspensa e\nreintroduzida após melhora do quadro.","C":"O aparecimento de dor e queimação nas extremidades pode estar relacionado com a isoniazida\ne/ou o etambutol e requer suspensão das\nmedicações e tratamento com piridoxina.","D":"A coloração alaranjada em suor e urina pode estar relacionada ao uso da rifampicina e somente\nrequer orientação/esclarecimento ao paciente.","E":"A nefrite intersticial associada ao uso da rifampicina ou da pirazinamida pode cursar com\noligúria, exantema e febre."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-77362","number":"77362","sourceNumber":"77362","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Qual é, segundo a Organização Mundial de Saúde, a principal causa de morte evitável\nno mundo?","options":{"A":"Tabagismo.","B":"Hipertensão arterial.","C":"Desnutrição.","D":"Desidratação.","E":"Diabetes."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-59048","number":"59048","sourceNumber":"59048","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente de 25 anos, masculino, trabalhador rural, com perda de peso e episódios de\nfebre nos últimos 30 dias. Ao exame físico,\napresenta gânglios cervicais aumentados, um deles se\ndiferencia por sinais inflamatórios evidentes, baço a três centímetros da reborda costal esquerda. A\nhipótese diagnóstica mais provável é:","options":{"A":"Síndrome mononucleose/toxoplasmose.","B":"Histoplasmose aguda.","C":"Leishmaniose visceral.","D":"Paracoccidioidomicose.","E":"Doença linfoproliferativa."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-43983","number":"43983","sourceNumber":"43983","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O médico do PSF é comunicado pela Agente Comunitária de Saúde (ACS) sobre a\npresença de icterícia no paciente MSD,\nportador de tuberculose pulmonar bacilífera (escarro 3+)\nem tratamento há 20 dias com a forma farmacêutica 4 em 1 (rifampicina 150 mg, isoniazida 75 mg,\npirazinamida 400 mg e etambutol 275 mg) 04 comprimidos ao dia. Pesava 53 kg no 1º dia de\ndrogas antituberculosas. O paciente relatou anorexia intensa. Escolha abaixo a conduta mais\nimportante a ser adotada pelo médico.","options":{"A":"Coletar transaminases séricas para confirmar ou excluir hepatotoxicidade às drogas\nantituberculosas.","B":"Deslocar até a residência do paciente para examiná-lo, no momento que for possível.","C":"Referenciar o paciente para o ambulatório de gastroenterologia do SUS.","D":"Coletar sorologias para VHB, VHC para confirmar ou excluir coinfecção pelo vírus do Hepatite B\ne/ou C.","E":"Pedir para a ACS recolher no mesmo dia todas as drogas antituberculosas ainda disponíveis na\ncasa do paciente e trazer essas medicações\npara a Unidade Sanitária. Durante essa ação, o\npaciente deverá ser informado de que as drogas antituberculosas estão suspensas até a 2ª ordem,\npor ordem médica."},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-32455","number":"32455","sourceNumber":"32455","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente do sexo masculino, 24 anos, é referenciado para o pronto-socorro por uma\nUnidade de Atendimento devido ao relato de hemoptise há 03 semanas. Negou tabagismo,\nhiporexia, calafrios, sudorese noturna, perda de peso e dor torácica. Ao ser questionado, confirmou\nfebre (temperatura axilar entre 37,8 e 38°C) durante os primeiros dias de hemoptise. O exame\nfísico foi normal na admissão ao pronto-socorro. Radiografia simples de tórax revelou opacificações\nfibroexsudativas com cavidade superior a 01 cm de diâmetro em terço superior do pulmão\nesquerdo. De acordo com as III Diretrizes para Tuberculose da Sociedade Brasileira de\nPneumologia e Tisiologia, escolher a conduta correta quanto à investigação de tuberculose\npulmonar.","options":{"A":"Tentar coletar duas amostras de escarro espontâneo para pesquisa de bacilos álcool-ácido\nresistentes e cultura para micobactérias.","B":"Coletar três amostras de escarro induzido em dias diferentes.","C":"Iniciar rifampicina, isoniazida, pirazinamida e etambutol uma vez que a história clínica e as\nimagens observadas na radiografia de tórax são compatíveis com o diagnóstico de tuberculose\npulmonar e dispensam a coleta de escarro.","D":"Submeter o paciente à broncoscopia para coleta de lavado broncoalveolar e biópsia\ntransbrônquica para pesquisa de bacilos álcool-ácido\nresistentes e cultura para micobactérias.","E":"Tentar coletar amostra de escarro para PCR (Reação em Cadeia da Polimerase) para o\ncomplexo Mycobacterium tuberculosis."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-27408","number":"27408","sourceNumber":"27408","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Com relação ao comportamento clínico e patogenético da paracoccidioidomicose, é\nERRADO afirmar:","options":{"A":"É uma doença espectral, cujas manifestações dependem da resposta celular do hospedeiro.","B":"Formas de transmissão que têm comprovação experimental relacionam-se com inalação dos\nmicélios, a partir de transmissão inter-humana.","C":"Formas mais graves relacionam-se com o acometimento do sistema fagocíticomononuclear,\nsendo mais vistas em jovens.","D":"Acometimento pulmonar sintomático não está habitualmente presente nas formas agudas, dos\njovens.","E":"É uma importante causa de doença de Addison no nosso meio."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-9385","number":"9385","sourceNumber":"9385","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Quais as evoluções possíveis do complexo primário pulmonar da\nParacoccidiodomicose?","options":{"A":"A calcificação do foco parenquimatoso pulmonar é evidenciável radiologicamente de rotina,\ncomo na tuberculose.","B":"Disseminação por contiguidade com a instalação de focos metastáticos.","C":"O gânglio hilar não toma parte na possível re-infecção endógena.","D":"Re-infecção endógena é o que explica o aparecimento da doença em residentes nos países não\nendêmicos.","E":"Glândula adrenal e parede intestinal não são focos de possível re-infecção endógena."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-9399","number":"9399","sourceNumber":"9399","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente portador de HIV, chega ao ambulatório com resultado de PPD - induração de\n6mm. A conduta correta, considerando que não tem qualquer sintoma, é:","options":{"A":"Orientar o paciente sobre as formas de aquisição da tuberculose, procurar contatos e\nacompanhar com a repetição do exame em 6 meses.","B":"Orientar o paciente sobre as formas de aquisição da tuberculose, procurar contactantes e iniciar\nhidrazida profilática na dose de 300 mg/dia, por seis meses.","C":"Iniciar esquema RIP profilático por 3 meses.","D":"Iniciar tratamento para HIV/AIDS, pois o paciente pode desenvolver doença oportunística.","E":"Iniciar tratamento com esquema RIP."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-9435","number":"9435","sourceNumber":"9435","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Qual conduta deve ser adotada em recém-nascido de mãe com tuberculose pulmonar\nbacilífera?","options":{"A":"Vacinar imediatamente com BCG.","B":"Administrar Isoniazida por três meses e, então, solicitar PPD. Se negativo, fazer BCG e\nsuspender a profilaxia.","C":"Afastar a criança da mãe, recomendar a não amamentação, vacinar com BCG e iniciar\nisoniazida para profilaxia.","D":"Vacinar imediatamente com BCG e iniciar profilaxia com Isoniazida.","E":"Fazer profilaxia desde o nascimento e PPD com um mês. Se negativo, vacinar com BCG."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-8162","number":"8162","sourceNumber":"8162","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"MAC, sexo masculino, 34 anos, pardo, casado, auxiliar de pedreiro, residente em\nCariacica (ES). Há 2 meses evolui com tosse,\ninicialmente seca, passando a produtiva de\nexpectoração amarelada, medicado com xaropes caseiros, sem melhora. Há 3 semanas passou a\napresentar episódios de febre baixa, intermitente, adinamia, cansaço, dificuldade para tolerar\nesforço no trabalho, e notou emagrecimento. Feito exame médico, apresentava-se febril, eupneico,\nlevemente hipocorado, linfonodos não palpáveis, discretos estertores audíveis na região\ninterescapular à direita, demais dados do exame físico normais; diagnosticada infecção respiratória,\nsendo prescrito azitromicina/5 dias e xarope antitussígeno. Evoluiu sem melhora, vindo a\napresentar hemoptóicos. Retornou ao médico sendo então solicitado exame de escarro que foi\npositivo para BAAR em duas amostras consecutivas. O paciente é tabagista há 15 anos, nega\nantecedentes de pneumopatias ou outras doenças, e desconhece contato com portadores de\ntuberculose. Com relação ao caso acima você afirmaria que:","options":{"A":"Há elementos suficientes para caracterizar como caso de turbeculose pulmonar de re-infecção\ndo adulto (pós-primária), devendo ser iniciado\nimediatamente o tratamento específico.","B":"Há elementos característicos de tuberculose pulmonar primária (primo-infecção evolutiva),\ndevendo ser iniciado o tratamento específico.","C":"Não há elementos suficientes para definir como caso de tuberculose, sendo necessário proceder\nà radiografia do tórax e cultura do escarro antes\nde iniciar o tratamento.","D":"Pode ser firmado o diagnóstico de tuberculose, mas antes de iniciar o tratamento deve ser\nsolicitada cultura de escarro BK e teste de\nsensibilidade às drogas anti-tuberculose, devido ao risco\nde resistência bacteriana às mesmas.","E":"Trata-se de um caso de tuberculose pulmonar, mas não é possível definir se é primária ou\npós-primária."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-353842","number":"353842","sourceNumber":"353842","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Dadas as seguintes infecções, é mais comumente associada à presença de sondas de\nalimentação em pacientes em posição inadequada ou com refluxo gastroesofágico:","options":{"A":"Sinusopatias decorrentes de infecção urinária.","B":"Translocação bacteriana associada ao uso de antibióticos.","C":"Pneumonia broncoaspirativa ou de Mendelson.","D":"Pneumonia por ventilação mecânica."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-362663","number":"362663","sourceNumber":"362663","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente masculino, 56 anos, apresenta dispneia, febre e tosse seca. O exame\nradiológico mostra opacidades pulmonares\nbilaterais. Dada a situação atual, qual é o diagnóstico\nmais provável?","options":{"A":"Pneumonia bacteriana.","B":"Síndrome Respiratória Aguda Grave (SARS).","C":"Asma.","D":"Bronquite."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-354809","number":"354809","sourceNumber":"354809","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Leia o relato do caso clínico a seguir. Menino de 4 anos de idade vem para consulta\ncom história de tosse seca há 2 meses. Nesse\nperíodo fez uso de várias medicações\n(expectorantes, descongestionantes, mucolíticos e antibiótico), sem qualquer sinal de melhora.\nTrata-se de uma criança previamente hígida, porém apresenta perda ponderal há 2 meses. Ao\nexame físico, encontra-se em bom estado geral, peso entre o escore z -2 e -3, estatura no escore z\n\n0. Sem sinais de desconforto respiratório e sem outras alterações ao exame físico. De acordo com\no relato, os exames a serem solicitados para\no esclarecimento do diagnóstico são:","options":{"A":"radiografia de tórax, teste tuberculínico, pesquisa e cultura para bacilo de Koch no lavado\nbrônquico.","B":"tomografia de tórax, teste tuberculínico, pesquisa e cultura para bacilo de Koch no lavado\nbrônquico.","C":"radiografia de tórax, teste tuberculínico, pesquisa e cultura para bacilo de Koch no lavado\ngástrico.","D":"tomografia de tórax, teste tuberculínico, pesquisa e cultura para bacilo de Koch no lavado\ngástrico."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-363945","number":"363945","sourceNumber":"363945","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Sobre o tratamento do Empiema Pleural.","options":{"A":"a antibioticoterapia deve sempre aguardar confirmação por culturas de identificação de bactérias\ne ser guiada por antibiograma.","B":"a pleurostomia é uma opção de tratamento para os pacientes com múltiplas comorbidades e alto\nrisco de complicação cirúrgica.","C":"a pleuroscopia estará indicada quando as coleções pleurais forem volumosas e o paciente\napresentar dispneia ou sinais de comprometimento respiratório.","D":"a pleurodese deverá ser realizada sempre que houver risco de recidiva de formação de coleções\npleurais, como nos casos de empiema tuberculoso."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-354836","number":"354836","sourceNumber":"354836","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um paciente portando síndrome gripal pode possuir diversos diagnósticos etiológicos e\nnosológicos/anatômicos. Com relação a esses diagnósticos:","options":{"A":"a apresentação de rinossinusite aguda deve ser confirmada por meio de exame radiológico,\ncomo radiografia ou tomografia computadorizada.","B":"as diretrizes geralmente recomendam o uso de antibióticos para bronquite aguda em adultos.","C":"os pacientes com diagnóstico etiológico de COVID-19 podem se apresentar com rinossinusite\naguda e bronquite aguda.?","D":"o corticoide nasal é proscrito contra rinossinusite bacteriana leve a moderada."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-354761","number":"354761","sourceNumber":"354761","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O conceito sepse, sindrômico por natureza, deve ser entendido como em constante\nevolução. A PCR (proteína C reativa) é o\nprotótipo das proteínas de fase aguda, com uma marcada\nelevação na sua concentração sérica em resposta a diversos estímulos inflamatórios. A PCR se\ncaracteriza por","options":{"A":"possuir baixa sensibilidade e moderada especificidade enquanto marcador de infecção\nbacteriana.","B":"ser sintetizada exclusivamente no fígado, à semelhança de outras proteínas de fase aguda.","C":"sofrer influência, em sua concentração sérica, das técnicas de substituição da função renal.","D":"ter acurácia adequada para predizer mortalidade nos pacientes sépticos."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-366990","number":"366990","sourceNumber":"366990","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A respeito da indução de escarro em solução salina hipertônica, é correto afirmar:","options":{"A":"Visa a coleta de escarro alveolar profundo, sendo útil na detecção de patógenos pulmonares.","B":"É um método utilizado para aumentar a concentração de glicose no escarro.","C":"A solução salina hipertônica causa uma reação hipertônica no pulmão, dificultando a\nexpectoração.","D":"A principal indicação é para a avaliação da função renal."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-353818","number":"353818","sourceNumber":"353818","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A patogênese da pneumonia relacionada à assistência à saúde envolve a interação\nentre patógeno, hospedeiro e variáveis\nepidemiológicas que facilitam esta dinâmica. Sobre esse\nassunto, é CORRETO afirmar:","options":{"A":"A pneumonia relacionada à assistência à saúde é principalmente de disseminação hematológica\na partir de um foco infeccioso à distância.","B":"A pneumonia relacionada à assistência à saúde é principalmente de origem inalatória.","C":"Pacientes internados são um grupo de risco diminuído para pneumonia.","D":"A pneumonia relacionada à assistência à saúde é principalmente de origem aspirativa."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-362636","number":"362636","sourceNumber":"362636","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Vale ressaltar também que as medidas e equipamentos de proteção coletiva são\nextremamente importantes quando se trata da prevenção da TB:","options":{"A":"Em trabalhadores e profissionais de saúde, bem como as questões relativas às condições\nadequadas para o atendimento às pessoas com suspeita ou diagnóstico de TB.","B":"Em trabalhadores e não em todos os profissionais de saúde, bem como as questões relativas às\ncondições adequadas para o atendimento às pessoas com suspeita ou diagnóstico de TB.","C":"Em trabalhadores e profissionais de saúde, não com as questões relativas às condições\nadequadas para o atendimento às pessoas com suspeita ou diagnóstico de TB.","D":"Em trabalhadores e profissionais de saúde, bem como as questões relativas às condições\nadequadas para o atendimento às pessoas sem suspeita ou diagnóstico de TB."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-363924","number":"363924","sourceNumber":"363924","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Leia o caso clínico a seguir. Pré-adolescente, atleta, participante ativo de jogos em\ncampeonatos de futebol e com saúde previamente hígida, apresenta, há mais de uma semana,\nepisódios de febre acima de 38ºC, predominantemente vespertina, associada à perda de peso e à\ntosse persistente. Qual é a doença deste pré-adolescente?","options":{"A":"Malária.","B":"Tuberculose pulmonar.","C":"Leishmaniose visceral.","D":"Legionelose."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-330065","number":"330065","sourceNumber":"330065","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente, 65 anos, sexo masculino, deu entrada na emergência com queixa de febre,\ncalafrios e tosse há quatro dias. Refere\nque neste período a temperatura axilar chegou a atingir 40o\nC, apresentou um episódio de vômito, relata diminuição no volume urinário e prostração, recebe o\ndiagnóstico de sepse e disfunção múltipla de órgãos. Diante da conclusão, uma variável\ninflamatória para o caso é:","options":{"A":"Redução do enchimento capilar.","B":"Hiperlactatemia.","C":"Leucocitose (contagem > 12.000/mm3).","D":"Índice cardíaco acima de 3,5 L/min/m2."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-334100","number":"334100","sourceNumber":"334100","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A tosse é um dos principais sintomas do paciente com Tuberculose Pulmonar, sendo\ncorreto que:","options":{"A":"O tempo da tosse deve ser considerado independendo da população.","B":"O tempo da tosse deve ser desconsiderado dependendo da população.","C":"O tempo da tosse deve ser considerado apenas na população tabagista.","D":"O tempo da tosse deve ser considerado dependendo da população."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-334102","number":"334102","sourceNumber":"334102","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Deve-se investigar Tuberculose, com qualquer tempo de tosse:","options":{"A":"Em pessoas sem contato com pacientes com Tuberculose, pessoas vivendo com o HIV (PVHIV),\npopulação privada de liberdade, população em situação de rua, indivíduos que vivem em albergues\nou instituições de longa permanência, indígenas, profissionais de saúde, imigrantes e refugiados\n(quando houver maior vulnerabilidade).","B":"Em pessoas em contato com pacientes com Tuberculose, pessoas vivendo com o HIV (PVHIV),\npopulação privada de liberdade, população em situação de rua, indivíduos que vivem em albergues\nou instituições de longa permanência, indígenas, profissionais de saúde, imigrantes e não\nrefugiados (quando houver maior vulnerabilidade).","C":"Em pessoas em contato com pacientes com Tuberculose, pessoas vivendo com o HIV (PVHIV),\npopulação privada de liberdade, população em situação de rua, indivíduos que vivem em\nalbergues, mas não em instituições de longa permanência, indígenas, profissionais de saúde,\nimigrantes e refugiados (quando houver maior vulnerabilidade).","D":"Em pessoas em contato com pacientes com Tuberculose, pessoas vivendo com o HIV (PVHIV),\npopulação privada de liberdade, população em situação de rua, indivíduos que vivem em albergues\nou instituições de longa permanência, indígenas, profissionais de saúde, imigrantes e refugiados\n(quando houver maior vulnerabilidade)."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-334779","number":"334779","sourceNumber":"334779","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente de 57 anos de idade, na terceira semana do tratamento de tuberculose\npulmonar em uso do esquema preferencial\nconforme Manual e Recomendações para Controle da\nTuberculose no Brasil (Ministério da Saúde), passou a apresentar náuseas, vômitos e dor em\nhipocôndrio direito. Procurou Unidade Básica de Saúde, onde não foram constatados sinais de\ngravidade clínica, porém exames laboratoriais demonstraram TGO 460 U/L e TGP 530 U/L.\nPaciente sem história de hepatopatias prévias. Nesse caso, a conduta a ser adotada é a suspensão","options":{"A":"da rifampicina pelas características da hepatotoxicidade, mantendo as demais medicações do\nesquema até o final do tratamento.","B":"do esquema completo, com reintrodução programada das medicações, iniciando-se com\nrifampicina e etambutol após a redução das transaminases.","C":"da pirazinamida pelo maior potencial de hepatotóxico desta, mantendo as demais medicações\ndo esquema até o final do tratamento.","D":"do esquema completo e início de esquema alternativo com levofloxacino, linezolida e amicacina."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-330081","number":"330081","sourceNumber":"330081","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Considerando a tuberculose na infância, a alternativa que representa o tipo mais\ncomum na faixa etária pediátrica é:","options":{"A":"Tuberculose óssea.","B":"Tuberculose pulmonar.","C":"Tuberculose ganglionar.","D":"Tuberculose meningoencefálica."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-346428","number":"346428","sourceNumber":"346428","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Mulher de 48 anos, internada em unidade de terapia intensiva por sepse de foco\nrespiratório, encontra-se hipotensa - pressão\narterial = 80 x 42 mmHg (pressão arterial média\n55mmHg) e extremidades frias. Está no segundo dia de tratamento com ceftriaxone e azitromicina\nendovenosos. Resultado de hemocultura positiva para Streptococcus pneumoniae sensível a\ncefalosporinas. Realizada prova volêmica com 500mL de ringer lactato, sem reversão do quadro.\nEcocardiograma a beira-leito: miocárdio hiperdinâmico, sem outras alterações. Ultrassonografia\npulmonar com linhas B bilaterais, sem outras alterações. A conduta terapêutica nesse momento é:","options":{"A":"Modificar antibioticoterapia para cefepime e realizar nova prova volêmica;","B":"Suspender azitromicina e realizar nova prova volêmica;","C":"Modificar antibioticoterapia para levofloxacino e introduzir noradrenalina;","D":"Suspender azitromicina e introduzir noradrenalina."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-331996","number":"331996","sourceNumber":"331996","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Giovanna, sete anos, recebeu BCG ao nascer, é contactante intradomiciliar de\ntuberculoso bacilífero, apresenta-se assintomática,\nraio-x de tórax normal e prova tuberculínica de\noito milímetros. Deve receber a orientação de:","options":{"A":"Repetir o PPD em oito semanas.","B":"Realizar lavado gástrico.","C":"Tratar infecção latente.","D":"Revacinar."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-334131","number":"334131","sourceNumber":"334131","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A partir da identificação do choque séptico, existem alguns alvos terapêuticos que\ndevem ser atingidos, com especial atenção na\nprimeira hora de assistência ao paciente. São esses\nalvos todas as abaixo, exceto:","options":{"A":"Manter as extremidades frias.","B":"Manter TEC igual ou inferior a 2 segundos.","C":"Normalizar o nível de consciência.","D":"Manter níveis adequados de glicemia e calcemia iônica."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-321579","number":"321579","sourceNumber":"321579","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Leia o caso clínico. Paciente do sexo masculino, 40 anos de idade e soropositivo para o\nVírus da Imunoeficiência Humana exibia febre e tosse há um mês. O exame físico mostrou\ntemperatura de 37.5ºC, bem como diminuição do murmúrio vesicular no àpice posterior do\nhemitórax direito. A radiografia do tórax exibiu grande área de consolidação na área central, com\nnível hidroaéreo no lobo médio direito. Uma biópsia transbrônquica mostrou organismos\nfilamentosos fracamente álcool-ácido resistentes. Evoluiu para empiema e início agudo de cefaleia.\nUma tomografia computadorizada de crânio apresentava uma lesão de 4cm no hemisfério cerebral\ndireito, com realce anelar do contraste. Qual dos seguintes agentes infecciosos é o mais provável\nde estar provocando a doença?","options":{"A":"Aspergillus fumigatus.","B":"Mycobacterium avium complex.","C":"Nocardia asteroides.","D":"Mucor circinelloides."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-321580","number":"321580","sourceNumber":"321580","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente do sexo feminino, 47 anos de idade, casada e menopausada é portadora de\nartrite reumatoide. Sua médica assistente optou pelo uso de um bloqueador do fator de necrose\ntumoral-alfa, ertanecept. O seu marido foi acometido por tuberculose pulmonar bacilífera há sete\nanos, com tratamento efetivo por 6 meses. Ela, porém, não exibia febre ou sintomas respiratórios.\nNa sua avaliação, no entanto, o teste tuberculínico (TT) foi 4mm e o teste de liberação de\ninterferon-gama (IGRA, do inglês interferon-gama release assay) foi positivo. A radiografia do tórax\nexibiu nódulo calcificado no lobo superior do pulmão direito, ao lado de espessamento pleural\napical ipsilateral. Com base no exposto, qual é a melhor conduta a ser tomada com essa paciente?","options":{"A":"Iniciar tratamento para tuberculose pulmonar com associação de rifampicina, isoniazida,\npirazinamida e etambutol por 02 meses, seguidos por rifampicina e isoniazida por 04 meses.","B":"Contraindicar o uso de ertanecept.","C":"Repetir o TT.","D":"Iniciar tratamento para infecção latente pelo Mycobacterium tuberculosis com a associação de\nrifapentina e isoniazida em dose semanal por 12 semanas consecutivas."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-321582","number":"321582","sourceNumber":"321582","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O primeiro método de imagem Raios-X descobertos em 1895, permitiu a demonstração\ndos diferentes tecidos do corpo humano tem um\nnúmero preciso de densidade radiológica é o","options":{"A":"3","B":"4","C":"5","D":"6"},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-330118","number":"330118","sourceNumber":"330118","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente, jovem, dá entrada em hospital com dispneia, sendo residente em região de\nclima muito frio, relata que apresentou há 30 dias tosse seca, dispneia progressiva e temperatura\nde 37º C. Em exame radiográfico do tórax é constatado velamento do hemitórax direito, com desvio\ndo mediastino contralateralmente. O procedimento CORRETO indicado é:","options":{"A":"Realizar apenas o procedimento para evacuar o conteúdo aéreo ou líquido anômalo da cavidade\npleural.","B":"Realizar apenas a toracotomia de emergência para obter amostras de tecido para exame\nlaboratorial.","C":"Realizar a videotoracoscopia por se tratar de fase aguda do trauma torácico.","D":"Realizar a toracocentese conjuntamente com esvaziamento do derrame pleural e biópsia pleural\ncom agulha de Cope."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-342683","number":"342683","sourceNumber":"342683","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Duas crianças estão internadas, num hospital, com meningite: a criança A com\nmeningite meningocócica, e a criança B, com meningite pneumocócica. Qual é a conduta de\nimediato com relação aos contactantes íntimos das crianças?","options":{"A":"rifampicina para contactantes dos 2 casos","B":"rifampicina para contactantes do caso A apenas","C":"rifampicina para contactantes do caso B apenas","D":"vacina meningocócica C conjugada para crianças do caso A apenas"},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-302832","number":"302832","sourceNumber":"302832","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem de 43 anos vem ao pronto-socorro por febre, cansaço e tosse produtiva há três\nsemanas. No quinto dia de quadro, procurou outro serviço de emergência no qual foi feito\ndiagnóstico de pneumonia lobar à esquerda com velamento do seio costofrênico ipsilateral. Foi\nprescrita antibioticoterapia com amoxicilina por 10 dias, utilizada corretamente. Apesar de ter\napresentado uma melhora inicial, ao terminar o tratamento com amoxicilina, houve piora de falta de\nar e recidiva da febre. No exame clínico, pulso: 116 bpm; frequência respiratória: 30 ipm; pressão\narterial: 102 x 66 mmHg/ saturação de oxigênio em ar ambiente: 91%. Diminuição da ausculta\npulmonar na base do hemitórax esquerdo com estertores grossos. O restante do exame clínico é\nnormal. Foram solicitados os exames de imagem a seguir: Qual o diagnóstico e a conduta para o\ncaso?","options":{"A":"Diagnóstico: empiema pleural em fase de organização; Conduta: videotoracoscopia com\ndecorticação pulmonar.","B":"Diagnóstico: empiema em fase fibrino-purulenta; Conduta: toracocentese esvaziadora.","C":"Diagnóstico: empiema em fase fibrino-purulenta.","D":"Diagnóstico: empiema em fase exsudativa; Conduta: drenagem pleural com dreno tipo pigtail.","E":"Diagnóstico: derrame pleural parapneumônico; Conduta: drenagem pleural convencional"},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-315765","number":"315765","sourceNumber":"315765","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Esquemas para tratamento de tuberculose sem a rifampicina na sua composição, seja\npor resistência ou por intolerância:","options":{"A":"Requerem o uso de fármacos de segunda linha, resultam em tratamento com duração mais\ncurta, com maior potencial de toxicidade e de pior prognóstico.","B":"Requerem o uso de fármacos de segunda linha, resultam em tratamento com duração mais\nprolongada, com maior potencial de toxicidade, mas de melhor prognóstico.","C":"Requerem o uso de fármacos de segunda linha, resultam em tratamento com duração mais\nprolongada, com maior potencial de toxicidade e de pior prognóstico.","D":"Requerem o uso de fármacos de segunda linha, resultam em tratamento com duração mais\nprolongada, com menor potencial de toxicidade e de pior prognóstico."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-315768","number":"315768","sourceNumber":"315768","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O tratamento da Tuberculose Drogarresistente (TB DR) é um dos maiores desafios para\no controle da doença no mundo, sendo correto\nque:","options":{"A":"Especialmente a que envolve resistência à rifampicina, isolada ou combinada a outros fármacos,\npois se trata do medicamento mais ativo contra\no bacilo da TB.","B":"Especialmente a que envolve resistência à rifampicina, isolada ou combinada a outros fármacos,\npois se trata do medicamento menos ativo\ncontra o bacilo da TB.","C":"Exceto a que envolve resistência à rifampicina, isolada ou combinada a outros fármacos, pois se\ntrata do medicamento mais ativo contra o bacilo da TB.","D":"Especialmente a que envolve resistência à rifampicina, isolada ou combinada a outros fármacos,\npois se trata do medicamento sem atividade\ncontra o bacilo da TB."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-315771","number":"315771","sourceNumber":"315771","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O diagnóstico precoce de infecção pelo HIV em pessoas com Tuberculose (TB) tem\nimportante impacto no curso clínico da doença. Portanto:","options":{"A":"O teste diagnóstico para HIV, preferencialmente o rápido, deve ser oferecido, o mais cedo\npossível, a toda pessoa com diagnóstico estabelecido de TB.","B":"O teste diagnóstico para HIV, nunca o rápido, deve ser oferecido.","C":"O teste diagnóstico para HIV, preferencialmente o rápido, deve ser oferecido, o mais tardiamente\npossível, a toda pessoa com diagnóstico\nestabelecido de TB.","D":"O teste diagnóstico para HIV, preferencialmente o lento, deve ser oferecido, o mais cedo\npossível, a toda pessoa com diagnóstico estabelecido de TB."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-317933","number":"317933","sourceNumber":"317933","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um homem de 44 anos procurou o serviço de urgência com história de dois dias de dor\nem pontada à direita,\nventilatório-dependente, com características pleuríticas, associada a dispneia.\nNega tosse ou expectoração. Ele também relatou uma sensação de febre concomitante. Sem\nhistórico de traumas. A radiografia de tórax revelou: derrame pleural direito de quantidade\nmoderada. O líquido pleural evidencia: pH 7,2; DHL 1459 U/L, glicose 30, proteína total 4,97 g/dL.\nO DHL sérico é 245 U/L e a proteína sérica: 6,7 g/dL. Tendo em vista esses achados, qual a\ncaracterística do líquido e o tratamento de escolha?","options":{"A":"Trata-se de um transudato, pois os critérios de Light evidenciam relação de proteína\nsérico/pleural maior que 0,5. O tratamento de escolha é a toracocentese esvaziadora.","B":"Trata-se de um exsudato, pois a razão entre o DHL do líquido pleural e a DHL sérica é maior que\n0,6. O tratamento de escolha é drenagem pleural fechada e antibioticoterapia.","C":"Trata-se de um exsudato, pois o pH é menor que 7,4 e o DHL pleural é 2/3 vezes maior que o\nlimite superior do DHL sérico. O tratamento de escolha é a toracocentese esvaziadora.","D":"Trata-se de um transudato, pois a glicose do líquido pleural é menor que 100 e a proteína pleural\né menor que 6,5. O tratamento de escolha é\ndrenagem torácica fechada."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-314108","number":"314108","sourceNumber":"314108","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente do sexo masculino, de 32 anos, com tosse, com escarro amarelado há três\ndias, febre alta, calafrios, dor torácica,\nventilatório dependente. Nega patologias prévias ou uso de\nmedicações contínuas. Tabagista 20 anos/maço e usuário de Vape. Alega dispneia aos grandes\nesforços. Ao exame, apresentou bom estado geral, frequência respiratória 25 irm, frequência\ncardíaca 90 bpm, PA: 120x80 mmHg, saturação de oxigênio 98% em ar ambiente. Na ausculta\npulmonar, observou-se estertores crepitantes em terço médio e superior de hemitórax direito. Traz\nraio X de tórax, mostrado a seguir. Qual a abordagem inicial para esse paciente?","options":{"A":"Internar e iniciar antibioticoterapia venosa.","B":"Iniciar antibioticoterapia via oral ambulatorial.","C":"Solicitar tomografia de tórax.","D":"Solicitar hemograma."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-314109","number":"314109","sourceNumber":"314109","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente do sexo masculino, de 32 anos, com tosse, com escarro amarelado há três\ndias, febre alta, calafrios, dor torácica,\nventilatório dependente. Nega patologias prévias ou uso de\nmedicações contínuas. Tabagista 20 anos/maço e usuário de Vape. Alega dispneia aos grandes\nesforços. Ao exame, apresentou bom estado geral, frequência respiratória 25 irm, frequência\ncardíaca 90 bpm, PA: 120x80 mmHg, saturação de oxigênio 98% em ar ambiente. Na ausculta\npulmonar, observou-se estertores crepitantes em terço médio e superior de hemitórax direito. Traz\nraio X de tórax, mostrado a seguir. Qual deve ser o diágnóstico desse paciente?","options":{"A":"Traqueobronquite.","B":"DPOC.","C":"Tuberculose pulmonar.","D":"Pneumonia comunitária."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-317171","number":"317171","sourceNumber":"317171","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente DEF, masculino, 19 anos, procura atendimento no Pronto Socorro por quadro\nde dispneia e dor torácica em região basal\nposterior esquerda, principalmente quando respira\nfundo. Diz que há alguns meses percebeu que estava cansado para jogar futebol, e que nas\núltimas duas semanas o quadro piorou, e agora apresentava falta de ar para subir 1 lance de\nescada. Nega alergias ou comorbidades. Nega uso de medicação contínua. Mora em casa de dois\ncômodos com outros 10 familiares. Trabalha de auxiliar de pedreiro, sem uso de EPI. Nega febre,\nmas diz que no final da tarde sente \"moleza no corpo\". Percebeu que a calça está um pouco mais\nlarga. Ao exame físico: Paciente hipocorado, hidratado, acianótico, anictérico. SpO2 96%, FC\n98bpm, PA 110x80. FR 18irpm, Temperatura axilar: 37,5. Peso 60kg, Altura 1,70m. Ausculta\nrespiratória com murmúrio vesicular presente, reduzido em base pulmonar esquerda. Percussão\ncom som submaciço em topografia de 1/3 inferior de hemitórax esquerdo. Sem esforço respiratório.\nAusculta respiratória com bulhas rítmicas e normofonéticas, sem sopros. Abdome flácido, indolor e\ninocente. Extremidade sem edema de membros inferiores. Sem alterações da mímica facial ou\nredução de força ou sensibilidade em membros. Sobre o caso clínico, assinale a alternativa\nverdadeira:","options":{"A":"A principal hipótese diagnóstica é pneumonia adquirida na comunidade, e o tratamento é\nrealizado com quinolona respiratória.","B":"A principal hipótese diagnóstica é tromboembolismo pulmonar, e o tratamento é realizado com\nanticoagulação oral.","C":"A principal hipótese diagnóstica é COVID-19, e o tratamento é com corticoide oral.","D":"A principal hipótese diagnóstica é tuberculose, e o tratamento é realizado com esquema básico\ncombinado com rifampicina, isoniazida, prianzinamida e etambutol."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-295366","number":"295366","sourceNumber":"295366","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente do sexo masculino, de 45 anos, refere há cerca de três meses tosse seca,\ndispneia progressiva até nos moderados esforços,\nfebre de 37,9°C no período vespertino, perda de\noito quilos nesse período e inapetência. Fez uso de vários antibióticos, sem melhora. Nega\ntabagismo e patologias prévias ou uso de medicações contínuas. Ao exame físico: regular estado\ngeral, afebril, eupneico, emagrecido, consciente mv abolida em terço inferior de hemitórax direito e\nsem outras alterações ao exame. Traz raio X de tórax, conforme as imagens a seguir. Resultado de\nanálise laboratorial de líquido pleural por toracocentese em hemitórax direito: líquido seroso.\n\nCitologia: linfócitos 80%, ausência de células mesoteliais, citologia oncótica negativa, pH 7,35,\nadenosina desaminase (ada): 70mg/dl, glicose 70mg/dl, LDH 500u/l, cultura bacteriana e fúngica\nnegativa, cultura micobactérias em andamento, proteína líquido/proteína sérica > 0,5, LDH do\nlíquido/LDH sérica > 0,6. Qual deve ser a conduta inicial para esse paciente?","options":{"A":"Iniciar antibiótico.","B":"Iniciar diurético.","C":"Realizar biópsia pleural.","D":"Realizar drenagem torácica fechada."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-317172","number":"317172","sourceNumber":"317172","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente DEF, masculino, 19 anos, procura atendimento no Pronto Socorro por quadro\nde dispneia e dor torácica em região basal\nposterior esquerda, principalmente quando respira\nfundo. Diz que há alguns meses percebeu que estava cansado para jogar futebol, e que nas\núltimas duas semanas o quadro piorou, e agora apresentava falta de ar para subir 1 lance de\nescada. Nega alergias ou comorbidades. Nega uso de medicação contínua. Mora em casa de dois\ncômodos com outros 10 familiares. Trabalha de auxiliar de pedreiro, sem uso de EPI. Nega febre,\nmas diz que no final da tarde sente \"moleza no corpo\". Percebeu que a calça está um pouco mais\nlarga. Ao exame físico: Paciente hipocorado, hidratado, acianótico, anictérico. SpO2 96%, FC\n98bpm, PA 110x80. FR 18irpm, Temperatura axilar: 37,5. Peso 60kg, Altura 1,70m. Ausculta\nrespiratória com murmúrio vesicular presente, reduzido em base pulmonar esquerda. Percussão\ncom som submaciço em topografia de 1/3 inferior de hemitórax esquerdo. Sem esforço respiratório.\nAusculta respiratória com bulhas rítmicas e normofonéticas, sem sopros. Abdome flácido, indolor e\ninocente. Extremidade sem edema de membros inferiores. Sem alterações da mímica facial ou\nredução de força ou sensibilidade em membros. Para confirmar a sua principal hipótese diagnóstica\nqual o exame pode auxiliar na sua investigação:","options":{"A":"Prova tuberculinica (PPD).","B":"Toracocentese com dosagem de ADA (adenosina deaminase) no líquido pleural.","C":"Hemocultura para aeróbios e anaeróbios.","D":"Dosagem sérica de D Dímero."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-295367","number":"295367","sourceNumber":"295367","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente do sexo masculino, de 45 anos, refere há cerca de três meses tosse seca,\ndispneia progressiva até nos moderados esforços,\nfebre de 37,9°C no período vespertino, perda de\noito quilos nesse período e inapetência. Fez uso de vários antibióticos, sem melhora. Nega\ntabagismo e patologias prévias ou uso de medicações contínuas. Ao exame físico: regular estado\ngeral, afebril, eupneico, emagrecido, consciente mv abolida em terço inferior de hemitórax direito e\nsem outras alterações ao exame. Traz raio X de tórax, conforme as imagens a seguir. Resultado de\nanálise laboratorial de líquido pleural por toracocentese em hemitórax direito: líquido seroso.\n\nCitologia: linfócitos 80%, ausência de células mesoteliais, citologia oncótica negativa, pH 7,35,\nadenosina desaminase (ada): 70 mg/dl, glicose 70\nmg/dl, LDH 500 u/l, cultura bacteriana e fúngica\nnegativa, cultura micobactérias em andamento, proteína líquido/proteína sérica > 0,5, LDH do\nlíquido/LDH sérica > 0,6. Após avaliação dos exames, qual deve ser o diagnóstico mais provável\npara esse paciente?","options":{"A":"Pneumonia bacteriana complicada.","B":"Tuberculose pleural.","C":"Insuficiência cardíaca congestiva.","D":"Embolia pulmonar."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-317173","number":"317173","sourceNumber":"317173","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente DEF, masculino, 19 anos, procura atendimento no Pronto Socorro por quadro\nde dispneia e dor torácica em região basal\nposterior esquerda, principalmente quando respira\nfundo. Diz que há alguns meses percebeu que estava cansado para jogar futebol, e que nas\núltimas duas semanas o quadro piorou, e agora apresentava falta de ar para subir 1 lance de\nescada. Nega alergias ou comorbidades. Nega uso de medicação contínua. Mora em casa de dois\ncômodos com outros 10 familiares. Trabalha de auxiliar de pedreiro, sem uso de EPI. Nega febre,\nmas diz que no final da tarde sente \"moleza no corpo\". Percebeu que a calça está um pouco mais\nlarga. Ao exame físico: Paciente hipocorado, hidratado, acianótico, anictérico. SpO2 96%, FC\n98bpm, PA 110x80. FR 18irpm, Temperatura axilar: 37,5. Peso 60kg, Altura 1,70m. Ausculta\nrespiratória com murmúrio vesicular presente, reduzido em base pulmonar esquerda. Percussão\ncom som submaciço em topografia de 1/3 inferior de hemitórax esquerdo. Sem esforço respiratório.\nAusculta respiratória com bulhas rítmicas e normofonéticas, sem sopros. Abdome flácido, indolor e\ninocente. Extremidade sem edema de membros inferiores. Sem alterações da mímica facial ou\nredução de força ou sensibilidade em membros. Com as informações clínicas e exame físico,\nassinale a alternativa correta:","options":{"A":"Na radiografia de tórax é esperado encontrar opacidade em base esquerda, com velamento de\nseios costofrênico e uma imagem de parábola na periferia (sinal do menísco).","B":"Na radiografia de tórax é esperado encontrar uma cavidade com nível líquido em base esquerda,\ncom desvio contra lateral de linha média.","C":"Na radiografia de tórax se houver sinais de derrame pleural com líquido livre, não deve ser\nrealizado toracocentese para avaliação das características do líquido.","D":"Em casos de doenças infecciosas como tuberculose e empiema, o padrão encontrado no líquido\npleural é de transudato."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-302865","number":"302865","sourceNumber":"302865","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A tuberculose na criança permanece ainda negligenciada e com alta mortalidade no\nmundo. Considere o caso de uma puérpera, em tratamento para tuberculose pulmonar há 1\nsemana. A respeito do caso, considere as seguintes condutas: 1. Vacinar o RN com BCG. 2.\n\nContraindicar a amamentação. 3. Iniciar quimioprofilaxia com isoniazida. 4. Realizar prova\ntuberculínica. É/São conduta(s) adequada(s) a ser realizada(s) no período neo natal com o\nrecém-nascido, que se encontra assintomático, conforme as diretrizes atuais do Ministério da\nSaúde:","options":{"A":"A 3 apenas.","B":"1 e 3 apenas.","C":"2 e 4 apenas.","D":"1, 2 e 4 apenas.","E":"1,2,3 e 4."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-300932","number":"300932","sourceNumber":"300932","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O tratamento da TB em PVHIV tem a duração de seis meses, sendo adequado o item:","options":{"A":"Dependentemente da fase de evolução da infecção viral.","B":"Independentemente da fase da infecção viral.","C":"Independentemente da fase de evolução da infecção viral.","D":"Independentemente da fase de evolução adiantada da infecção viral."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-317176","number":"317176","sourceNumber":"317176","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"paciente QWE, mulher, 71 anos é trazida ao pronto socorro pelos familiares com\nquadro de sonolência, baixa ingesta\nalimentar, tosse produtiva e febre nas últimas 48h. É\nhipertensa, diabética, obesa e dislipidêmica. Mora com a filha que cuida das medicações e garante\nque a paciente toma todas as medicações corretamente. Ao exame físico: sonolenta, responde aos\nchamados, localiza estímulos dolorosos, confusa no tempo e espaço, desidratada, cianose de\nextremidades. Perfusão periférica lentificada, pulsos filiformes. Temperatura axiliar 38,2°C; FC 108\nbpm; FR 32 irpm; PA 80x50 mmHg; SpO2 88%. Marque a alternativa correta:","options":{"A":"Nesse momento a paciente tem sinais de infecção, porém sem sinais de gravidade ou\ncomprometimento de órgãos e sistemas. Deve\nser avaliada por equipe médica, receber medicação\nanti-térmica, realizar exames de sangue, e aguardar na recepção até os resultados para nova\navaliação.","B":"A paciente deve ser levada a sala de emergência para monitorização contínua de sinais vitais,\npunção periférica para iniciar hidratação endovenosa, solicitado coleta de líquor e realização de\nressonância magnética de crânio, já que apresenta alteração de nível de consciência.","C":"Paciente deve ser internada, permanecer sob monitorização contínua de sinais vitais, ter acesso\nvenoso periférico calibroso para hidratação,\npassagem de sonda vesical de demora para\nquantificação de diurese, suplementação de oxigênio inicialmente via cateter nasal, coleta de\nexames laboratoriais, hemocultura e urocultura, realização de imagem de tórax no leito. Deve ser\niniciado antibiótico empiricamente o mais rápido possível já que a paciente apresenta sinais\ninfecciosos com disfunção orgânica.","D":"Caso a paciente tenha alteração em ausculta respiratória e imagem de tórax, pode ser\nconsiderada a hipótese diagnóstica de\npneumonia nosocomial, e, pela estratificação de gravidade\nutilizando o escore CRB-65, e a paciente apresenta baixo risco para complicações."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-300938","number":"300938","sourceNumber":"300938","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação à tosse:","options":{"A":"Sintoma que funciona como sinal de alerta para várias doenças.","B":"Caracterizada como um reflexo protetor, trata-se de um mecanismo importante de defesa do\norganismo.","C":"Manobra expulsiva forçada contra a glote fechada, gera um som característico, de controle\nvoluntário ou não.","D":"Tem apenas a função de eliminar secreções e muco de grandes vias aéreas."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-300942","number":"300942","sourceNumber":"300942","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Todas as alternativas abaixo fazem parte das recomendações para tratamento dos\ncasos de influenza, exceto:","options":{"A":"Restrição hídrica.","B":"Fluidificação de secreções.","C":"Analgésicos e antitérmicos.","D":"Repouso."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-300947","number":"300947","sourceNumber":"300947","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Considerando-se o vírus influenza e as condutas relacionadas a ele, assinale a\nalternativa INCORRETA:","options":{"A":"A síndrome respiratória aguda grave é a febre de início súbito associada a sintomas\nrespiratórios.","B":"A síndrome respiratória aguda grave é a síndrome gripal associada a sinais de gravidade, como\ndesconforto respiratório e hipotensão.","C":"O oseltamivir é a medicação de escolha no Brasil para tratamento de influenza e deve ser\niniciado nas primeiras 48 horas de sintomas, quando indicado.","D":"No Brasil, a vacinação contra influenza é administrada na rede pública, em campanhas anuais\npara indivíduos que pertençam a grupos de risco e profissionais de saúde."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-300954","number":"300954","sourceNumber":"300954","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Múltiplos obstáculos dificultam a implementação de estratégias de controle da\ntuberculose nas prisões, podemos assim determinar que está CORRETA a seguinte:","options":{"A":"Risco de estigmatização e de segregação considerando a falta de importância da proteção\ngerada pelo pertencimento grupal.","B":"Risco de estigmatização e de segregação considerando a importância da proteção Gerada pelo\npertencimento grupal.","C":"Risco de estigmatização e de segregação considerando a nula importância da proteção Gerada\npelo pertencimento grupal.","D":"Risco somente de estigmatização e não de segregação considerando a importância da proteção\ngerada pelo pertencimento grupal."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-300957","number":"300957","sourceNumber":"300957","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O resultado da Prova Tuberculínica (PT) deve ser registrado em milímetros, inclusive\nquando não houver endureção. Nesse caso, o profissional deverá anotar: ZERO mm. Sendo\nCORRETO o item:","options":{"A":"Deve-se medir o menor diâmetro transverso da área do endurado palpável, com régua\nmilimetrada transparente.","B":"Deve-se medir o maior diâmetro transverso da área do endurado palpável, com régua\nmilimetrada transparente.","C":"Deve-se medir o maior diâmetro transverso da área do endurado impalpável, com régua\nmilimetrada transparente.","D":"Deve-se medir o mínimo diâmetro transverso da área do endurado palpável, com régua\nmilimetrada transparente."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-317205","number":"317205","sourceNumber":"317205","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Segundo as estratégias de controle da tuberculose que são responsabilidade da\nAtenção Básica, marcar C para as afirmativas\nCertas, E para as Erradas e, após, assinalar a\nalternativa que apresenta a sequência CORRETA: ( ) Será realizado, na Atenção Básica, o\ntratamento supervisionado dos casos positivos. ( ) A fim de efetuar o diagnóstico, a unidade deve\nencaminhar o indivíduo para exames laboratoriais e radiológicos. ( ) Não se inclui, como medida\npreventiva, a busca de indivíduos que coabitam com o paciente tuberculoso.","options":{"A":"C - C - E.","B":"E - C - C.","C":"C - E - E.","D":"E - C - E."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-315833","number":"315833","sourceNumber":"315833","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A PT consiste na inoculação intradérmica do Derivado Proteico Purificado (PPD), com a\nfunção de medir a resposta celular a estes antígenos. Sendo correto o item:","options":{"A":"A resposta à PT deve ser lida após 72 horas após a aplicação, sendo considerada positiva a\nleitura maior ou igual a 5mm.","B":"A resposta à PT deve ser lida de 48 a 72 horas após a aplicação, sendo considerada negativa a\nleitura maior ou igual a 5mm.","C":"A resposta à PT deve ser lida de 48 a 72 horas após a aplicação, sendo considerada positiva a\nleitura maior ou igual a 5mm.","D":"A resposta à PT deve ser lida de 48 a 72 horas após a aplicação, sendo considerada positiva a\nleitura maior ou igual a 15 mm."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-300966","number":"300966","sourceNumber":"300966","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Os ensaios de liberação do interferon-gama (Interferon-Gamma Release Assays -\nIGRA) apresentam vantagens que consistem no\nresultado não sujeito ao viés do leitor e no fato de\no teste ser realizado em amostra biológica, o que reduz o risco de efeitos adversos. Sendo\nadequado que:","options":{"A":"IGRAs possuem vantagens operacionais, pois, ao requerer apenas uma visita do paciente, o\nretorno para a leitura do teste não é necessário.","B":"IGRAs não possuem vantagens operacionais, pois, ao requerer apenas uma visita do paciente, o\nretorno para a leitura do teste não é necessário.","C":"IGRAs possuem vantagens operacionais, pois, ao requerer apenas duas visitas do paciente, o\nretorno para a leitura do teste não é necessário.","D":"IGRAs possuem vantagens operacionais, pois, ao requerer apenas uma visita do paciente, o\nretorno para a leitura do teste é necessário."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-318017","number":"318017","sourceNumber":"318017","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O complexo de Ranke ocorre na seguinte doença:","options":{"A":"tuberculose.","B":"blastomicose.","C":"suberose.","D":"asbestose."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-265853","number":"265853","sourceNumber":"265853","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Ocorrem especificidades do desenvolvimento do Mycobacterium Tuberculosis no que\ndiz respeito ao seu metabolismo e à atuação dos medicamentos, sendo ADEQUADO o item:","options":{"A":"Os fármacos só atuam quando há atividade metabólica, ou seja, bacilos em estado de latência\nnão são atingidos pelos medicamentos, mas são\ndestruídos pelo sistema imunológico.","B":"Os fármacos não atuam quando há atividade metabólica, ou seja, bacilos em estado de latência\nnão são atingidos pelos medicamentos, mas\nsão destruídos pelo sistema imunológico.","C":"Os fármacos só atuam quando há atividade metabólica, ou seja, bacilos em estado de latência\nsão atingidos pelos medicamentos, mas são\ndestruídos pelo sistema imunológico.","D":"Os fármacos só atuam quando há atividade metabólica, ou seja, bacilos em estado de latência\nnão são atingidos pelos medicamentos, e não\nsão destruídos pelo sistema imunológico."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-274764","number":"274764","sourceNumber":"274764","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Sobre o manejo de um paciente crítico com choque séptico, afirma-se:","options":{"A":"corticoides não devem ser administrados de rotina, mas são apropriados no choque séptico\nrefratário à ressuscitação com fluidos e vasopressores.","B":"para pacientes com choque séptico e lactato >2 nmol/L, deve-se iniciar cristaloides e\nvasopressores simultaneamente, e, posteriormente, descalonar o vasopressor.","C":"as terapias vasopressoras de escolha devem ser feitas com norepinefrina associada à\nvasopressina.","D":"Dobutamina deve ser associada ao tratamento nos pacientes com resposta inapropriada aos\nvasopressores, com o objetivo de se obter SvcO2 >70%."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-257733","number":"257733","sourceNumber":"257733","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente do sexo masculino, de 42 anos, refere que há 40 dias apresentou quadro de\ntosse com escarro purulento, febre diária\nde 38 ºC, dor torácica ventilatório dependente. Fez uso de\nazitromicina por cinco dias sem melhora. Procurou atendimento médico e realizou exames\ncomplementares, conforme descritos a seguir: Hemograma: hemoglobina 13, leucócitos 13.000,\nbastões 5%, neutrófilo 75% e plaquetas 250.000. Raios X de tórax conforme imagem a seguir.\n\nToracocentese do hemitórax direito: líquido pleural purulento: PH 7,12, glicose 38 mg%, DHL 1.100,\npredomínio de neutrófilos, aguardando culturas. Nesse caso, qual o provável diagnóstico?","options":{"A":"Derrame pleural parapneumônico não complicado.","B":"Empiema pleural.","C":"Pneumonia comunitária.","D":"Tuberculose pleural."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-257734","number":"257734","sourceNumber":"257734","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente do sexo masculino, de 42 anos, refere que há 40 dias apresentou quadro de\ntosse com escarro purulento, febre diária\nde 38 ºC, dor torácica ventilatório dependente. Fez uso de\nazitromicina por cinco dias sem melhora. Procurou atendimento médico e realizou exames\ncomplementares, conforme descritos a seguir: Hemograma: hemoglobina 13, leucócitos 13.000,\nbastões 5%, neutrófilo 75% e plaquetas 250.000. Raios X de tórax conforme imagem a seguir.\n\nToracocentese do hemitórax direito: líquido pleural purulento: PH 7,12, glicose 38 mg%, DHL 1.100,\npredomínio de neutrófilos, aguardando culturas. Qual é o tratamento adequado para esse paciente?","options":{"A":"Esquema antimicrobiano para tuberculose.","B":"Antibioticoterapia e toracocentese de repetição.","C":"Antibioticoterapia e observação.","D":"Antibioticoterapia e drenagem pleural."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-281994","number":"281994","sourceNumber":"281994","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Em relação à disfunção miocárdica na sepse grave, é incorreto afirmar que:","options":{"A":"Na maioria dos casos, acontece na fase mais tardia da sepse.","B":"Apesar de queda de fração de ejeção, o débito cardíaco pode ser alto, devido à queda\nimportante na resistência vascular sistêmica.","C":"A dobutamina associada à noradrenalina é a medicação de escolha para tratar a disfunção\nmiocárdica da sepse.","D":"A saturação venosa central fica alta devido ao fluxo sanguíneo lento."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-257757","number":"257757","sourceNumber":"257757","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A.M.S., masculino, de 38 anos, saudável até então, vem apresentando febre baixa e\ncefaleia há três semanas e apresenta, há 12 horas, náuseas e vômitos em jato. Teste rápido de\nHIV negativo. Ao ser avaliado na UPA, apresentava confusão mental, rigidez de nuca e sinal de\nBrudzinski presente. O liquor foi retirado, apresentava-se turvo e, ao exame, apresentou os\nseguintes parâmetros: celularidade: 680 cel/mm³/88% linfomononucleares; proteína: 165 mg% (N =\n15?50) e glicose: 25 mg% (N = 45?100). Bacterioscopia e culturas em andamento. Nesse caso, a\npartir dos dados clínicos epidemiológicos, o diagnóstico mais provável é meningite:","options":{"A":"Estafilocócica.","B":"Meningocócica.","C":"Tuberculosa.","D":"Viral."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-274500","number":"274500","sourceNumber":"274500","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Segundo a Organização Mundial da Saúde (OMS), a influenza é uma infecção viral\naguda que acomete, especialmente, o sistema\nrespiratório. É de transmissibilidade elevada e\ndistribuição global, podendo causar pandemias. A maioria dos casos graves, complicações,\nhospitalizações e óbitos se dá em indivíduos pertencentes aos grupos de risco. Em relação ao vírus\ninfluenza, podemos afirmar:","options":{"A":"Os mecanismos de diversificação e transformação gênica dos vírus influenza são responsáveis\npor sua perpetuação ao longo das décadas. Os\nprincipais mecanismos envolvidos nesse processo\nsão os de mutação e o rearranjo gênico.","B":"Assim como na infecção por Covid-19, as crianças abaixo de 2 anos não pertencem ao grupo de\nrisco para as complicações graves.","C":"A saturação de SpO2 <90% em ar ambiente é um dos sinais da Síndrome respiratória aguda\ngrave (SRAG).","D":"Diversas medidas podem ser tomadas para tentar evitar ou minimizar os riscos de infecção pelo\nvírus influenza. A vacinação anual é uma medida de proteção, no entanto é contra indicada em\ngestantes e em crianças menores de 2 anos."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-274806","number":"274806","sourceNumber":"274806","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A Pneumonia Adquirida na Comunidade (PAC) é uma causa comum de hospitalização\nentre as doenças respiratórias. Sobre essa\ninfecção, marque a alternativa correta.","options":{"A":"Na ausência de alterações dos sinais vitais o diagnóstico de pneumonia é altamente improvável.","B":"O Escore CURB-65 é um critério validado para diagnóstico de PAC.","C":"O sinal patognomônico de PAC é a presença de estertores finos.","D":"A Radiografia de tórax não tem utilidade para o diagnóstico de PAC."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-281315","number":"281315","sourceNumber":"281315","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A disseminação da doença tuberculose para o sistema linfático pode ser visualizada\ncomo linfonodomegalias hilares e/ou alargamento do\nmediastino.","options":{"A":"Geralmente, são linfonodos menores que 2 cm, com áreas de baixa atenuação central\nassociadas a um aumento de atenuação perinodal,\ncorrespondendo a focos de necrose caseosa\ncentral.","B":"Geralmente, são linfonodos maiores que 2 cm, com áreas de baixa atenuação central\nassociadas a um aumento de atenuação\nperinodal, correspondendo a focos de necrose caseosa\ncentral.","C":"Geralmente, são linfonodos maiores que 2 cm, com áreas de alta atenuação central associadas\na um aumento de atenuação perinodal,\ncorrespondendo a focos de necrose caseosa central.","D":"Geralmente, são linfonodos maiores que 2 cm, com áreas de baixa atenuação central\nassociadas a um aumento de atenuação\nperinodal, correspondendo a focos de necrose caseosa\nperiférico."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-265896","number":"265896","sourceNumber":"265896","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Considerando os pilares, objetivos e estratégias do Plano Nacional pelo Fim da\nTuberculose para fortalecer a rede de\ndiagnóstico laboratorial existente no país, somente podemos\nindicar como INCORRETA a alternativa:","options":{"A":"Ampliar o acesso aos métodos diagnósticos com o teste rápido molecular, baciloscopia, cultura e\nteste de sensibilidade.","B":"Ampliar a realização de cultura e teste de sensibilidade para todos os casos de tuberculose.","C":"Promover ações que garantam o acesso ao diagnóstico oportuno da tuberculose sensível e\nresistente, tendo em vista o início oportuno do tratamento.","D":"Intensificar a busca ativa de casos, desconsideradas as particularidades das populações mais\nvulneráveis nos territórios."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-281318","number":"281318","sourceNumber":"281318","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A indicação do tratamento da Infecção Latente pelo Mycobacterium Tuberculosis (ILTB)\ndepende de vários fatores, sendo correto o item:","options":{"A":"Resultado da prova tuberculínica PT ou do Interferon-Gamma Release Assays IGRA, e não\nidade da pessoa, probabilidade de ILTB e risco para o desenvolvimento de TB ativa.","B":"Resultado da prova tuberculínica PT ou do Interferon-Gamma Release Assays IGRA, idade da\npessoa, probabilidade de ILTB e não o risco para o desenvolvimento de TB ativa.","C":"Resultado da prova tuberculínica PT, mas não do Interferon-Gamma Release Assays IGRA,\nidade da pessoa, probabilidade de ILTB e risco para o desenvolvimento de TB ativa.","D":"Resultado da prova tuberculínica PT ou do Interferon-Gamma Release Assays IGRA, idade da\npessoa, probabilidade de ILTB e risco para o desenvolvimento de TB ativa."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-281322","number":"281322","sourceNumber":"281322","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Para as pessoas infectadas pelo HIV que são contatos de pessoas com TB pulmonar\nou laríngea ativa, está adequado o item:","options":{"A":"Deverão realizar o tratamento para infecção latente pelo Mycobacterium Tuberculosis (ILTB),\nindependentemente do resultado da prova tuberculínica.","B":"Deverão realizar o tratamento para infecção latente pelo Mycobacterium Tuberculosis (ILTB),\ndependentemente do resultado da prova tuberculínica.","C":"Não deverão realizar o tratamento para infecção latente pelo Mycobacterium Tuberculosis\n(ILTB), independentemente do resultado da prova tuberculínica.","D":"Nunca deverão realizar o tratamento para infecção latente pelo Mycobacterium Tuberculosis\n(ILTB), independentemente do resultado da prova\ntuberculínica."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-265904","number":"265904","sourceNumber":"265904","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Nas pessoas com TB pulmonar que tem baciloscopia positiva no escarro, têm maior\ncapacidade de transmissão. Indique a alternativa ERRADA:","options":{"A":"Em geral, eles têm a forma TB pulmonar cavitária ou, mais raramente, a TB laríngea transmite a\ndoença.","B":"Aqueles com baciloscopia de escarro negativa, mesmo com TRM-TB ou cultura positivos no\nescarro, têm infectividade menor.","C":"Pessoas com cultura de escarro negativa e as com TB extrapulmonar exclusivamente são\ndesprovidas de infectividade.","D":"Pacientes com TB pulmonar e infecção pelo HIV, na dependência de maior comprometimento da\nimunidade, podem ter menos frequentemente acometimento pulmonar e apresentação cavitária da\ndoença e, assim, também maior infectividade."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-281324","number":"281324","sourceNumber":"281324","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Assim como os contatos de casos de TB pulmonar ativa, podemos indicar como correto\no item:","options":{"A":"A única população que merece especial atenção durante o rastreamento para a identificação da\ninfecção latente pelo Mycobacterium tuberculosis (ILTB) é a dos profissionais de saúde.","B":"Duas outras populações merecem especial atenção durante o rastreamento para a identificação\nda infecção latente pelo Mycobacterium\ntuberculosis (ILTB): PVHIV e profissionais de saúde.","C":"Outras populações merecem especial atenção durante o rastreamento para a identificação da\ninfecção latente pelo Mycobacterium tuberculosis (ILTB): Pessoa vivendo com HIV PVHIV, exceto\nprofissionais de saúde.","D":"Duas outras populações não merecem especial atenção durante o rastreamento para a\nidentificação da infecção latente pelo\nMycobacterium tuberculosis (ILTB): Pessoa vivendo com HIV\nPVHIV e profissionais de saúde."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-274817","number":"274817","sourceNumber":"274817","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"A tosse é um mecanismo de defesa das vias aéreas, que funciona como meio de\npropagação de doenças infecciosas, e quando\npersistente, é causa de grande desconforto ao\npaciente. A elucidação diagnóstica da tosse é bastante desafiadora para o médico. Com relação à\ntosse, marque a alternativa correta.","options":{"A":"Em portadores de DPOC, a tosse persistente pode causar dor torácica, abdominal, tontura e\nsíncope. Em casos graves, pode haver fratura de costelas.","B":"A tosse que dura mais de 4 semanas é considerada crônica.","C":"Nas crianças, a tosse que dura menos de 5 semanas é considerada aguda, estando bem\nestabelecida, neste caso, o benefício dos xaropes expectorantes.","D":"Em nosso meio, a causa mais comum de tosse por mais de 3 semanas ainda é a tuberculose."},"answer":"A","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-274837","number":"274837","sourceNumber":"274837","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Lactente, 18 meses, sexo feminino, deu entrada no serviço de emergência com quadro\nde febre há 48 horas, constante, de\n38-38,5ºC, não cede a antitérmicos. Mãe percebeu dor\nabdominal difusa, prostação, baixa ingesta, nega tosse, nega alterações de pele. Ao exame físico\nencontra-se desidratada, prostada, saliva espessa, frequência cardíaca de 136 bpm (batimentos\npor minuto), frequência respiratória de 22 irm (incursões respiratórias por minuto), PA (pressão\narterial de 80/46 mmHG, pulsos finos. Coletado exames. Apresenta hemoglobina de 8,5g/dL,\nhematócrito de 30%. PCR: 90 (proteína C reativa). Exame simples de urina coletado por sonda\nvesical de alívio com leucocitose, hematúria, nitrito positivo. Qual o diagnóstico e a conduta?","options":{"A":"Infecção do trato urinário, antibiótico oral e observação domiciliar.","B":"Sepse, coleta de culturas e antibiótico venoso, observação por 24 horas.","C":"Infecção do trato urinário, sepse, hidratação venosa e antibiótico, internação hospitalar.","D":"Infecção do trato urinário, sepse, expansão volumétrica, coleta de culturas e iniciar\nantibiótico de\namplo expectro, internação hospitalar."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-257798","number":"257798","sourceNumber":"257798","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"O etilismo crônico, DPOC, idade avançada e permanência em UTI são fatores que,\nmais provavelmente, causam pneumonia por:","options":{"A":"Estreptococos.","B":"Estafilococos.","C":"Klebsiella.","D":"Actinobacter."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-249459","number":"249459","sourceNumber":"249459","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Considerando que a proteína C reativa é secretada pelas células hepáticas em\nresposta à elevação das interleucinas 6,1? e TNF-?. Apenas não podemos aceitar o seguinte:","options":{"A":"A proteína C reativa se eleva em qualquer processo inflamatório.","B":"Outras fontes da proteína C reativa reconhecidas são os linfócitos, monócitos, neurônios e\nplacas ateroscleróticas.","C":"O pico da proteína C reativa ocorre ao redor de 48h após o estímulo agressor.","D":"Sua meia vida plasmática é ao redor de 19h somente em situação de saúde."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-231935","number":"231935","sourceNumber":"231935","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um paciente, de 18 anos, é admitido na Emergência de um hospital público devido a\ninfarto agudo do miocárdio. No 6º dia de internação, apresenta febre de 38°C e leucometria de\n14.500/mm³, com 8% de bastões. Ao exame físico, é detectada área de hiperemia (halo: 3cm) em\nsítio de inserção de cateter vascular profundo. As hemoculturas realizadas como parte da\ninvestigação do quadro infeccioso detectam o crescimento de Staphylococcus aureus resistente a\noxacilina. Dentre os antimicrobianos a seguir, a principal opção terapêutica para o micro-organismo\ndetectado é:","options":{"A":"oxacilina","B":"linezolida","C":"teicoplanina","D":"daptomicina","E":"vancomicina"},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-248905","number":"248905","sourceNumber":"248905","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Um idoso de 75 anos, com DPOC, é admitido no pronto-socorro com tosse, febre e\nexpectoração purulenta há 5 dias. Notam-se, ao exame físico, taquipneia (FR = 32irpm), FC =\n100bpm e PA = 100x50mmHg. Os raios X de tórax demonstram consolidação na base do hemitórax\ndireito. Nesse caso, a melhor conduta é o tratamento:","options":{"A":"ambulatorial com azitromicina","B":"hospitalar com azitromicina","C":"ambulatorial com ampicilina, sulbactam + azitromicina","D":"hospitalar com ampicilina, sulbactam + azitromicina"},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-249845","number":"249845","sourceNumber":"249845","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente de 58 anos, internado em UTI há dez dias para tratamento de pneumonia\ncomplicada com derrame pleural. Realizada\ntoracocentese para análise de rotina do líquido pleural.\nNessa situação clínica, os exames necessários para diagnóstico de derrame pleural\nparapneumônico complicado são:","options":{"A":"pH, DHL, glicose e amilase.","B":"pH, triglicérides e amilase.","C":"pH, DHL, glicose e leucometria.","D":"cultura, pH e ADA (adenosina deaminase)."},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-241693","number":"241693","sourceNumber":"241693","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Homem de 78 anos, internado para tratamento de infecção do trato urinário há 2 dias\ncom ceftriaxone, evolui com rebaixamento do nível\nde consciência e hipotensão. Ao exame REG:\nTax 38,3°C; FC: 130 bpm, PA: 80 x 54 mmHg; lenta perfusão capilar. Exames laboratoriais: Hb 12,0\ng/dL; GB: 11.400/mm3; plaquetas: 110.000/mm³; creatinina: 1,4 mg/dL; bilirrubinas: 1,2 mg/dL.\nConsiderando a gravidade da sepse, faz parte da conduta apropriada nas primeiras 24 horas:","options":{"A":"ampliar espectro dos antibióticos dentro de 6 horas.","B":"coletar hemoculturas após modificação de antimicrobianos.","C":"repor volemia precocemente com até 20mL/kg de cristaloides.","D":"solicitar lactato e acompanhar o nível sérico para avaliar perfusão.","E":"usar vasopressores simultaneamente ao volume inicial."},"answer":"D","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-246526","number":"246526","sourceNumber":"246526","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Os escores prognósticos utilizados nas pneumonias adquiridas na comunidade auxiliam\nna decisão de internação e conduta terapêutica.\nSobre o tema, julgue os seguintes itens. I. O\nCURB-65 utiliza como parâmetros confusão mental, ureia, frequência cardíaca, pressão arterial e\nidade ? 65 anos. II. O CRB-65 usa como parâmetros confusão mental frequência respiratória,\npressão arterial e idade ? 65 anos. É utilizado em locais onde não se disponha de laboratórios para\ndosagem de ureia. III. O escore PSI (pneumonia severity index) tem como limitação subestimar a\ngravidade da doença em pacientes jovens e sem doenças associadas por ponderar muito a idade e\na presença de comorbidades na sua pontuação. Pode-se afirmar que apenas:","options":{"A":"o item I está certo.","B":"o item II está certo.","C":"o item III está certo.","D":"os itens I e II estão certos.","E":"Os itens II e III estão certos."},"answer":"E","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-248909","number":"248909","sourceNumber":"248909","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Constitui opção terapêutica para o tratamento de infecções causadas por bactérias\nGram negativas multidrogarresistentes à seguinte\ncombinação:","options":{"A":"linezolida + meropeném","B":"vancomicina + ceftazidima","C":"poilimixina B + meropeném","D":"amicacina + daptomicina"},"answer":"C","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-234318","number":"234318","sourceNumber":"234318","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente do sexo masculino, de 38 anos, com quadro de tosse há quinze dias, dor em\nhemitórax direito há dez dias e febre esporádica há sete dias, evoluindo com astenia e inapetência.\nRealizou raio X de tórax que apresentou opacidade homogênea em terço inferior do hemitórax\ndireito, sugestivo de derrame pleural. Foi realizada uma toracocentese. Os seguintes parâmetros\nforam encontrados à análise do líquido: \"Líquido pleural de aspecto turvo. PH = 6,8. DHL: 2000 UI/l\n(líquido). DHL = 420 UI/l (sangue). Proteínas: 4,9 mg/dl (líquido). Proteínas séricas: 3,8 mg/dl\n(sangue). Glicose: 38 mg/dl (líquido). Leucometria no líquido: 40.000, leucócitos com 87% de\nneutrófilos.\" USG de tórax: derrame pleural em HTD, sem aparente loculação. Nesse caso, o\npaciente é portador de:","options":{"A":"Derrame pleural parapneumônico não complicado e o tratamento de escolha é antibioticoterapia\ne toracocentese de alívio.","B":"Derrame pleural parapneumônico complicado e o tratamento é antibioticoterapia e toracostomia\ncom drenagem pleural fechada.","C":"Empiema pleural, fase III, e o tratamento de escolha está limitado à drenagem torácica.","D":"Empiema pleural, fase IIb, e o tratamento de escolha é descorticação pulmonar ampliada e\nantibioticoterapia endovenosa de amplo espectro."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pneumo-pne-2-249855","number":"249855","sourceNumber":"249855","collectionBlock":"medcurso:medcurso-pneumo-pne-2","collectionLabel":"Medcurso · PNE 2","documentBlock":"","area":"Pneumologia","specialty":"Pneumologia","topic":"PNE 2","subtopic":"","stem":"Paciente do sexo masuno, de 35 anos, refere há sete dias tosse com escarro\namarelado, febre de 39 ºC dor torácica em\nhemitórax direito ventilatório-dependente, mal-estar,\nhiporexia. Ao exame, apresenta-se em regular estado geral febril, dispneico (FR: 32 IRM), PA:\n90x50 mmHg, ausculta pulmonar com estertores crepitantes em base de hemitórax direito. Fez uso\nde antibiótico em casa, por conta própria, de amoxacilina 500 mg de oito em oito horas por quatro\ndias, sem melhora dos sintomas. Nega o uso de medicações contínuas. Nega patologias prévias.\nProcurou pronto-socorro, onde realizou raio X de tórax e exames laboratoriais, vistos abaixo: Raio X\nde tórax: Exames laboratoriais: Hemograma: hemoglobina 14,5; leucócitos 14.000; segmentados\n88% bastões 8%; plaquetas 250.000; ureia 60mg/dl. Qual é o diagnóstico desse paciente?","options":{"A":"Rinossinusopatia crônica agudizada.","B":"Pneumonia.","C":"Tuberculose.","D":"Derrame pleural complicado."},"answer":"B","source":"Pneumo/PNE 2/PNE 2.txt","sourceLabel":"Medcurso · PNE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pneumologia","PNE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
